INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('d74103c2-3330-5f01-a71c-d689871cbeb7', 'b93a38a9-0ff4-572d-a73e-3d689466de3a', NULL, 31, 31, 'He said, "What shall I give you?" Jacob said, "You shall not give me anything. If you will do this thing for me, I will again feed your flock and keep it.'),
  ('ab0e67cb-bd40-5e8e-a9d4-d1ef247e4d2b', 'b93a38a9-0ff4-572d-a73e-3d689466de3a', NULL, 32, 32, 'I will pass through all your flock today, removing from there every speckled and spotted one, and every black one among the sheep, and the spotted and speckled among the goats. This will be my hire.'),
  ('3d25c183-bd48-574c-a4c1-3b720b4116e2', 'b93a38a9-0ff4-572d-a73e-3d689466de3a', NULL, 33, 33, 'So my righteousness will answer for me hereafter, when you come concerning my hire that is before you. Every one that is not speckled and spotted among the goats, and black among the sheep, that might be with me, will be counted stolen."'),
  ('b8867c5f-220a-5372-afa0-643d4706e97a', 'b93a38a9-0ff4-572d-a73e-3d689466de3a', NULL, 34, 34, 'Laban said, "Behold, let it be according to your word."'),
  ('b2167f4d-96c5-5080-aa72-40ba94c2ad54', 'b93a38a9-0ff4-572d-a73e-3d689466de3a', NULL, 35, 35, 'That day, he removed the male goats that were streaked and spotted, and all the female goats that were speckled and spotted, every one that had white in it, and all the black ones among the sheep, and gave them into the hand of his sons.'),
  ('da7875f5-6918-5be0-a31d-506864d2b19d', 'b93a38a9-0ff4-572d-a73e-3d689466de3a', NULL, 36, 36, 'He set three days'' journey between himself and Jacob, and Jacob fed the rest of Laban''s flocks.'),
  ('091a4670-46b0-50bd-a5fe-2d8825dc056d', 'b93a38a9-0ff4-572d-a73e-3d689466de3a', NULL, 37, 37, 'Jacob took to himself rods of fresh poplar, almond, plane tree, peeled white streaks in them, and made the white appear which was in the rods.'),
  ('911d22cd-990a-530b-ad5d-2d74c5f6bc52', 'b93a38a9-0ff4-572d-a73e-3d689466de3a', NULL, 38, 38, 'He set the rods which he had peeled opposite the flocks in the gutters in the watering-troughs where the flocks came to drink. They conceived when they came to drink.'),
  ('92fc6a86-31f5-57bb-afe2-e7e30c899568', 'b93a38a9-0ff4-572d-a73e-3d689466de3a', NULL, 39, 39, 'The flocks conceived before the rods, and the flocks brought forth streaked, speckled, and spotted.'),
  ('6ecb06e8-7e19-5ea7-a470-936f7e9719ba', 'b93a38a9-0ff4-572d-a73e-3d689466de3a', NULL, 40, 40, 'Jacob separated the lambs, and set the faces of the flocks toward the streaked and all the black in the flock of Laban: and he put his own droves apart, and didn''t put them into Laban''s flock.'),
  ('40d61433-a83b-505f-a207-03d1f50bc7fc', 'b93a38a9-0ff4-572d-a73e-3d689466de3a', NULL, 41, 41, 'It happened, whenever the stronger of the flock conceived, that Jacob laid the rods before the eyes of the flock in the gutters, that they might conceive among the rods;'),
  ('00880387-cda0-5bc2-ac7b-b13378aaced3', 'b93a38a9-0ff4-572d-a73e-3d689466de3a', NULL, 42, 42, 'but when the flock were feeble, he didn''t put them in. So the feebler were Laban''s, and the stronger Jacob''s.'),
  ('472e60c4-cacd-56cb-a7c6-667843cf6018', 'b93a38a9-0ff4-572d-a73e-3d689466de3a', NULL, 43, 43, 'The man increased exceedingly, and had large flocks, female servants and male servants, and camels and donkeys.'),
  ('9d159a49-2855-5774-aada-e9b5e34515b3', '1111d03c-3541-554f-a84e-545e48ba7985', NULL, 1, 1, 'He heard the words of Laban''s sons, saying, "Jacob has taken away all that was our father''s. From that which was our father''s, has he gotten all this wealth."'),
  ('99e4f246-c894-536f-a1a1-6f145586207e', '1111d03c-3541-554f-a84e-545e48ba7985', NULL, 2, 2, 'Jacob saw the expression on Laban''s face, and, behold, it was not toward him as before.'),
  ('19e8deef-ac40-5a15-af7a-6eecb3ca09c3', '1111d03c-3541-554f-a84e-545e48ba7985', NULL, 3, 3, 'Yahweh said to Jacob, "Return to the land of your fathers, and to your relatives, and I will be with you."'),
  ('29eb62ab-bb5b-5733-a0bd-e4b32c46b1c2', '1111d03c-3541-554f-a84e-545e48ba7985', NULL, 4, 4, 'Jacob sent and called Rachel and Leah to the field to his flock,'),
  ('270f0dcc-a48b-57b0-afac-07e948060314', '1111d03c-3541-554f-a84e-545e48ba7985', NULL, 5, 5, 'and said to them, "I see the expression on your father''s face, that it is not toward me as before; but the God of my father has been with me.'),
  ('30a65c5b-f20e-529b-a5ac-8d908ee5e9fc', '1111d03c-3541-554f-a84e-545e48ba7985', NULL, 6, 6, 'You know that I have served your father with all of my strength.'),
  ('1e01b4fa-65e6-53bd-a02d-76ae8f8006ad', '1111d03c-3541-554f-a84e-545e48ba7985', NULL, 7, 7, 'Your father has deceived me, and changed my wages ten times, but God didn''t allow him to hurt me.'),
  ('2cfa7933-27f3-5b7e-a0f9-a63d8f412e8d', '1111d03c-3541-554f-a84e-545e48ba7985', NULL, 8, 8, 'If he said this, ''The speckled will be your wages,'' then all the flock bore speckled. If he said this, ''The streaked will be your wages,'' then all the flock bore streaked.'),
  ('1588d8c5-3030-5385-acb2-45df64d7374d', '1111d03c-3541-554f-a84e-545e48ba7985', NULL, 9, 9, 'Thus God has taken away your father''s livestock, and given them to me.'),
  ('a529dc09-4b5f-59cd-a8d8-f99128bcd258', '1111d03c-3541-554f-a84e-545e48ba7985', NULL, 10, 10, 'It happened during mating season that I lifted up my eyes, and saw in a dream, and behold, the male goats which leaped on the flock were streaked, speckled, and grizzled.'),
  ('ba8672aa-2a8f-51b4-aaa8-cf5376d6cece', '1111d03c-3541-554f-a84e-545e48ba7985', NULL, 11, 11, 'The angel of God said to me in the dream, ''Jacob,'' and I said, ''Here I am.'''),
  ('ccf4920b-535e-506f-a142-6d74f5acd1ab', '1111d03c-3541-554f-a84e-545e48ba7985', NULL, 12, 12, 'He said, ''Now lift up your eyes, and behold, all the male goats which leap on the flock are streaked, speckled, and grizzled, for I have seen all that Laban does to you.'),
  ('f3993004-40fc-5bac-a7cb-34d643df8d0f', '1111d03c-3541-554f-a84e-545e48ba7985', NULL, 13, 13, 'I am the God of Bethel, where you anointed a pillar, where you vowed a vow to me. Now arise, get out from this land, and return to the land of your birth.''"'),
  ('370831f6-8e8d-5637-a69d-46eba203d087', '1111d03c-3541-554f-a84e-545e48ba7985', NULL, 14, 14, 'Rachel and Leah answered him, "Is there yet any portion or inheritance for us in our father''s house?'),
  ('c871d3fe-0e59-59fd-a202-f81e870009a4', '1111d03c-3541-554f-a84e-545e48ba7985', NULL, 15, 15, 'Aren''t we accounted by him as foreigners? For he has sold us, and has also quite devoured our money.'),
  ('4e961033-128b-558d-a8c1-cc114e9ba99c', '1111d03c-3541-554f-a84e-545e48ba7985', NULL, 16, 16, 'For all the riches which God has taken away from our father, that is ours and our children''s. Now then, whatever God has said to you, do."'),
  ('be3fdc13-4c28-53c6-a48f-09cb34d00ebc', '1111d03c-3541-554f-a84e-545e48ba7985', NULL, 17, 17, 'Then Jacob rose up, and set his sons and his wives on the camels,'),
  ('e6fb08bc-2b74-5e1b-a9c4-32f5635a3468', '1111d03c-3541-554f-a84e-545e48ba7985', NULL, 18, 18, 'and he took away all his livestock, and all his possessions which he had gathered, including the livestock which he had gained in Paddan Aram, to go to Isaac his father, to the land of Canaan.'),
  ('6e5f9be2-e023-53a8-a697-bc06877ba20a', '1111d03c-3541-554f-a84e-545e48ba7985', NULL, 19, 19, 'Now Laban had gone to shear his sheep: and Rachel stole the teraphim that were her father''s.'),
  ('d803831f-a9c0-549c-ad0c-98739683f22d', '1111d03c-3541-554f-a84e-545e48ba7985', NULL, 20, 20, 'Jacob deceived Laban the Syrian, in that he didn''t tell him that he was running away.'),
  ('ddb67f17-25ea-522c-ac96-40ca861ca378', '1111d03c-3541-554f-a84e-545e48ba7985', NULL, 21, 21, 'So he fled with all that he had. He rose up, passed over the River, and set his face toward the mountain of Gilead.'),
  ('de019d7b-1920-51ac-ac0a-95aa4bf8ac40', '1111d03c-3541-554f-a84e-545e48ba7985', NULL, 22, 22, 'Laban was told on the third day that Jacob had fled.'),
  ('d538de5b-4fb5-5f8f-a1c4-f0efc7a55faa', '1111d03c-3541-554f-a84e-545e48ba7985', NULL, 23, 23, 'He took his relatives with him, and pursued after him seven days'' journey. He overtook him in the mountain of Gilead.'),
  ('7cb26dd4-a97b-5968-a3e7-d830558496b1', '1111d03c-3541-554f-a84e-545e48ba7985', NULL, 24, 24, 'God came to Laban, the Syrian, in a dream of the night, and said to him, "Take heed to yourself that you don''t speak to Jacob either good or bad."'),
  ('df04dbf8-0c72-50b2-a1a9-6900c6512a8c', '1111d03c-3541-554f-a84e-545e48ba7985', NULL, 25, 25, 'Laban caught up with Jacob. Now Jacob had pitched his tent in the mountain, and Laban with his relatives encamped in the mountain of Gilead.'),
  ('a9184fa6-5a7a-5632-abef-a7bdbdfed600', '1111d03c-3541-554f-a84e-545e48ba7985', NULL, 26, 26, 'Laban said to Jacob, "What have you done, that you have deceived me, and carried away my daughters like captives of the sword?'),
  ('4d4af7be-3c63-5098-ac74-2e2d59bf166a', '1111d03c-3541-554f-a84e-545e48ba7985', NULL, 27, 27, 'Why did you flee secretly, and deceive me, and didn''t tell me, that I might have sent you away with mirth and with songs, with tambourine and with harp;'),
  ('18f3be50-89d1-5eb7-a52b-9290e86120bf', '1111d03c-3541-554f-a84e-545e48ba7985', NULL, 28, 28, 'and didn''t allow me to kiss my sons and my daughters? Now have you done foolishly.'),
  ('f10a5fe0-e5d7-50e7-adec-a8fd6b1eab67', '1111d03c-3541-554f-a84e-545e48ba7985', NULL, 29, 29, 'It is in the power of my hand to hurt you, but the God of your father spoke to me last night, saying, ''Take heed to yourself that you don''t speak to Jacob either good or bad.'''),
  ('8cbddb66-6548-587a-a34e-a505108c51bf', '1111d03c-3541-554f-a84e-545e48ba7985', NULL, 30, 30, 'Now, you want to be gone, because you greatly longed for your father''s house, but why have you stolen my gods?"'),
  ('35f339c2-f46d-5e33-aa75-85b93c32d146', '1111d03c-3541-554f-a84e-545e48ba7985', NULL, 31, 31, 'Jacob answered Laban, "Because I was afraid, for I said, ''Lest you should take your daughters from me by force.'''),
  ('1c6b7d4e-c50a-568f-a638-64f4e2f074e8', '1111d03c-3541-554f-a84e-545e48ba7985', NULL, 32, 32, 'Anyone you find your gods with shall not live. Before our relatives, discern what is yours with me, and take it." For Jacob didn''t know that Rachel had stolen them.'),
  ('f7e61cef-3345-542f-a32b-c8085988598d', '1111d03c-3541-554f-a84e-545e48ba7985', NULL, 33, 33, 'Laban went into Jacob''s tent, into Leah''s tent, and into the tent of the two female servants; but he didn''t find them. He went out of Leah''s tent, and entered into Rachel''s tent.'),
  ('bdbbc7af-09d8-5e3b-a350-e215f6d26541', '1111d03c-3541-554f-a84e-545e48ba7985', NULL, 34, 34, 'Now Rachel had taken the teraphim, put them in the camel''s saddle, and sat on them. Laban felt about all the tent, but didn''t find them.'),
  ('cf898db6-3024-53d5-abc1-934ba97dfbde', '1111d03c-3541-554f-a84e-545e48ba7985', NULL, 35, 35, 'She said to her father, "Don''t let my lord be angry that I can''t rise up before you; for I''m having my period." He searched, but didn''t find the teraphim.'),
  ('f4c4f8e1-d3dc-59f1-a6b6-42fabb18af23', '1111d03c-3541-554f-a84e-545e48ba7985', NULL, 36, 36, 'Jacob was angry, and argued with Laban. Jacob answered Laban, "What is my trespass? What is my sin, that you have hotly pursued after me?'),
  ('fbf158a0-2a3a-535c-a896-a8babf966e57', '1111d03c-3541-554f-a84e-545e48ba7985', NULL, 37, 37, 'Now that you have felt around in all my stuff, what have you found of all your household stuff? Set it here before my relatives and your relatives, that they may judge between us two.'),
  ('f643dcb8-e5eb-543e-ab27-bb5de0d86e8a', '1111d03c-3541-554f-a84e-545e48ba7985', NULL, 38, 38, '"These twenty years I have been with you. Your ewes and your female goats have not cast their young, and I haven''t eaten the rams of your flocks.'),
  ('ac1dabc2-520c-5e82-a2c6-19c91c833269', '1111d03c-3541-554f-a84e-545e48ba7985', NULL, 39, 39, 'That which was torn of animals, I didn''t bring to you. I bore its loss. Of my hand you required it, whether stolen by day or stolen by night.'),
  ('c786058c-da1c-5829-a13d-fb7b0252b1b0', '1111d03c-3541-554f-a84e-545e48ba7985', NULL, 40, 40, 'This was my situation: in the day the drought consumed me, and the frost by night; and my sleep fled from my eyes.'),
  ('5bd76aad-a6bc-5eda-ab88-dd98593cb40f', '1111d03c-3541-554f-a84e-545e48ba7985', NULL, 41, 41, 'These twenty years I have been in your house. I served you fourteen years for your two daughters, and six years for your flock, and you have changed my wages ten times.'),
  ('5e258584-9c86-527a-ae7c-a977627a5e50', '1111d03c-3541-554f-a84e-545e48ba7985', NULL, 42, 42, 'Unless the God of my father, the God of Abraham, and the fear of Isaac, had been with me, surely now you would have sent me away empty. God has seen my affliction and the labor of my hands, and rebuked you last night."'),
  ('50a6c24c-e3f4-51a7-aca2-49b09b13cbc9', '1111d03c-3541-554f-a84e-545e48ba7985', NULL, 43, 43, 'Laban answered Jacob, "The daughters are my daughters, the children are my children, the flocks are my flocks, and all that you see is mine: and what can I do this day to these my daughters, or to their children whom they have borne?'),
  ('b3a15a59-37df-5d00-a55a-e1b6485a459c', '1111d03c-3541-554f-a84e-545e48ba7985', NULL, 44, 44, 'Now come, let us make a covenant, you and I; and let it be for a witness between me and you."'),
  ('4c3576ec-1105-5923-a5a1-302eade89a6e', '1111d03c-3541-554f-a84e-545e48ba7985', NULL, 45, 45, 'Jacob took a stone, and set it up for a pillar.'),
  ('ff3aa8a3-3737-5013-af8a-9ee5d1f6eacd', '1111d03c-3541-554f-a84e-545e48ba7985', NULL, 46, 46, 'Jacob said to his relatives, "Gather stones." They took stones, and made a heap. They ate there by the heap.'),
  ('772796d0-4276-57f1-a174-5edc4b432bfb', '1111d03c-3541-554f-a84e-545e48ba7985', NULL, 47, 47, 'Laban called it Jegar Sahadutha, but Jacob called it Galeed.'),
  ('3d0e4978-0ec3-5b7c-a220-5e2089ad690d', '1111d03c-3541-554f-a84e-545e48ba7985', NULL, 48, 48, 'Laban said, "This heap is witness between me and you this day." Therefore it was named Galeed'),
  ('0f79b11e-d8b8-5674-ac89-43e25b7f8ee3', '1111d03c-3541-554f-a84e-545e48ba7985', NULL, 49, 49, 'and Mizpah, for he said, "Yahweh watch between me and you, when we are absent one from another.'),
  ('b0bcab51-87c1-5a76-a088-cecd53001425', '1111d03c-3541-554f-a84e-545e48ba7985', NULL, 50, 50, 'If you afflict my daughters, or if you take wives besides my daughters, no man is with us; behold, God is witness between me and you."'),
  ('e743d563-a09b-5da4-a746-8944f31bf518', '1111d03c-3541-554f-a84e-545e48ba7985', NULL, 51, 51, 'Laban said to Jacob, "See this heap, and see the pillar, which I have set between me and you.'),
  ('574c7305-28c3-55de-a961-6dd8ff29f460', '1111d03c-3541-554f-a84e-545e48ba7985', NULL, 52, 52, 'May this heap be a witness, and the pillar be a witness, that I will not pass over this heap to you, and that you will not pass over this heap and this pillar to me, for harm.'),
  ('8f29d214-5521-5a5e-a56d-8ef52432947f', '1111d03c-3541-554f-a84e-545e48ba7985', NULL, 53, 53, 'The God of Abraham, and the God of Nahor, the God of their father, judge between us." Then Jacob swore by the fear of his father, Isaac.'),
  ('ea16a843-37bb-5b6d-a8b2-25965dd4224f', '1111d03c-3541-554f-a84e-545e48ba7985', NULL, 54, 54, 'Jacob offered a sacrifice in the mountain, and called his relatives to eat bread. They ate bread, and stayed all night in the mountain.'),
  ('79b4f1bf-1b75-56f7-aade-84d16e51e3be', '1111d03c-3541-554f-a84e-545e48ba7985', NULL, 55, 55, 'Early in the morning, Laban rose up, and kissed his sons and his daughters, and blessed them. Laban departed and returned to his place.'),
  ('7b23ce81-983d-5ccc-a355-b3033778469b', '76aa8537-2598-5b49-a28f-a7ccb36c4134', NULL, 1, 1, 'Jacob went on his way, and the angels of God met him.'),
  ('2fb34d1e-6e6c-5062-ad2a-1ab55c4c83c6', '76aa8537-2598-5b49-a28f-a7ccb36c4134', NULL, 2, 2, 'When he saw them, Jacob said, "This is God''s army." He called the name of that place Mahanaim.'),
  ('6f4c828c-0564-5156-a350-0eedbf9639ac', '76aa8537-2598-5b49-a28f-a7ccb36c4134', NULL, 3, 3, 'Jacob sent messengers in front of him to Esau, his brother, to the land of Seir, the field of Edom.'),
  ('1ffc6bea-6a11-5929-a8b8-8ef05c321101', '76aa8537-2598-5b49-a28f-a7ccb36c4134', NULL, 4, 4, 'He commanded them, saying, "This is what you shall tell my lord, Esau: ''This is what your servant, Jacob, says. I have lived as a foreigner with Laban, and stayed until now.'),
  ('a6c4e208-2e08-597f-ae60-454f8f211896', '76aa8537-2598-5b49-a28f-a7ccb36c4134', NULL, 5, 5, 'I have cattle, donkeys, flocks, male servants, and female servants. I have sent to tell my lord, that I may find favor in your sight.''"'),
  ('ee34dc7c-43c8-552c-a9bd-f2cd18536c5f', '76aa8537-2598-5b49-a28f-a7ccb36c4134', NULL, 6, 6, 'The messengers returned to Jacob, saying, "We came to your brother Esau. Not only that, but he comes to meet you, and four hundred men with him."'),
  ('3354ee1c-6017-56ea-ad25-1c42dafce49a', '76aa8537-2598-5b49-a28f-a7ccb36c4134', NULL, 7, 7, 'Then Jacob was greatly afraid and was distressed. He divided the people who were with him, and the flocks, and the herds, and the camels, into two companies;'),
  ('16177556-5416-539c-af86-87a0bb5571bc', '76aa8537-2598-5b49-a28f-a7ccb36c4134', NULL, 8, 8, 'and he said, "If Esau comes to the one company, and strikes it, then the company which is left will escape."'),
  ('2ca438ad-7916-51af-a338-e1ac269855c7', '76aa8537-2598-5b49-a28f-a7ccb36c4134', NULL, 9, 9, 'Jacob said, "God of my father Abraham, and God of my father Isaac, Yahweh, who said to me, ''Return to your country, and to your relatives, and I will do you good,'''),
  ('293dc4ab-b61d-596f-a0eb-50d19bcb02fe', '76aa8537-2598-5b49-a28f-a7ccb36c4134', NULL, 10, 10, 'I am not worthy of the least of all the loving kindnesses, and of all the truth, which you have shown to your servant; for with just my staff I passed over this Jordan; and now I have become two companies.'),
  ('a47a8d3c-284a-50d8-a548-a3bebf01876d', '76aa8537-2598-5b49-a28f-a7ccb36c4134', NULL, 11, 11, 'Please deliver me from the hand of my brother, from the hand of Esau: for I fear him, lest he come and strike me, and the mothers with the children.'),
  ('8b4a06ae-2414-5f02-a835-0143339879e2', '76aa8537-2598-5b49-a28f-a7ccb36c4134', NULL, 12, 12, 'You said, ''I will surely do you good, and make your seed as the sand of the sea, which can''t be numbered because there are so many.''"'),
  ('fccf1301-7954-5e41-a9ae-de00afa9bc68', '76aa8537-2598-5b49-a28f-a7ccb36c4134', NULL, 13, 13, 'He lodged there that night, and took from that which he had with him, a present for Esau, his brother:'),
  ('abcb9235-11c2-5e2e-a768-2ec75ae09b71', '76aa8537-2598-5b49-a28f-a7ccb36c4134', NULL, 14, 14, 'two hundred female goats and twenty male goats, two hundred ewes and twenty rams,'),
  ('5f868988-8d84-5a7e-adb2-0e700dc3b9f9', '76aa8537-2598-5b49-a28f-a7ccb36c4134', NULL, 15, 15, 'thirty milk camels and their colts, forty cows, ten bulls, twenty female donkeys and ten foals.'),
  ('3c1c68bc-e98c-51ec-a7f8-836423ec6883', '76aa8537-2598-5b49-a28f-a7ccb36c4134', NULL, 16, 16, 'He delivered them into the hands of his servants, every herd by itself, and said to his servants, "Pass over before me, and put a space between herd and herd."'),
  ('299b3664-46bd-57cb-a443-dbd195c6c204', '76aa8537-2598-5b49-a28f-a7ccb36c4134', NULL, 17, 17, 'He commanded the foremost, saying, "When Esau, my brother, meets you, and asks you, saying, ''Whose are you? Where are you going? Whose are these before you?'''),
  ('35f1c738-b899-5be2-ae18-82b52aa721fc', '76aa8537-2598-5b49-a28f-a7ccb36c4134', NULL, 18, 18, 'Then you shall say, ''They are your servant, Jacob''s. It is a present sent to my lord, Esau. Behold, he also is behind us.''"'),
  ('936f2099-13ba-5227-a794-fa58cce9b21f', '76aa8537-2598-5b49-a28f-a7ccb36c4134', NULL, 19, 19, 'He commanded also the second, and the third, and all that followed the herds, saying, "This is how you shall speak to Esau, when you find him.'),
  ('3491cc39-bd38-5bad-a412-707fb57c5a49', '76aa8537-2598-5b49-a28f-a7ccb36c4134', NULL, 20, 20, 'You shall say, ''Not only that, but behold, your servant, Jacob, is behind us.''" For, he said, "I will appease him with the present that goes before me, and afterward I will see his face. Perhaps he will accept me."'),
  ('f915eaa9-807a-5993-aa09-1f9a042b8c66', '76aa8537-2598-5b49-a28f-a7ccb36c4134', NULL, 21, 21, 'So the present passed over before him, and he himself lodged that night in the camp.'),
  ('056f6d4d-59d1-5528-a187-3b0bc5b22a7b', '76aa8537-2598-5b49-a28f-a7ccb36c4134', NULL, 22, 22, 'He rose up that night, and took his two wives, and his two handmaids, and his eleven sons, and passed over the ford of the Jabbok.'),
  ('a17f4894-75a9-5718-a936-22ebf8d0e206', '76aa8537-2598-5b49-a28f-a7ccb36c4134', NULL, 23, 23, 'He took them, and sent them over the stream, and sent over that which he had.'),
  ('753dcef2-4285-58bf-a87a-90b511a8c6e2', '76aa8537-2598-5b49-a28f-a7ccb36c4134', NULL, 24, 24, 'Jacob was left alone, and wrestled with a man there until the breaking of the day.'),
  ('b94d6c42-4762-5629-a932-d89adf0acbac', '76aa8537-2598-5b49-a28f-a7ccb36c4134', NULL, 25, 25, 'When he saw that he didn''t prevail against him, he touched the hollow of his thigh, and the hollow of Jacob''s thigh was strained, as he wrestled.'),
  ('8e0107df-ac37-50b5-a22f-9b0d38fe8baf', '76aa8537-2598-5b49-a28f-a7ccb36c4134', NULL, 26, 26, 'The man said, "Let me go, for the day breaks." Jacob said, "I won''t let you go, unless you bless me."'),
  ('8c948b6f-12b8-5e5a-a31d-d77bc3710bb0', '76aa8537-2598-5b49-a28f-a7ccb36c4134', NULL, 27, 27, 'He said to him, "What is your name?" He said, "Jacob."'),
  ('6745b7e9-b710-5671-af32-ebcbac4813f3', '76aa8537-2598-5b49-a28f-a7ccb36c4134', NULL, 28, 28, 'He said, "Your name will no longer be called Jacob, but Israel; for you have fought with God and with men, and have prevailed."'),
  ('9161be91-bbf2-5d00-a223-ecc219cc0e43', '76aa8537-2598-5b49-a28f-a7ccb36c4134', NULL, 29, 29, 'Jacob asked him, "Please tell me your name." He said, "Why is it that you ask what my name is?" He blessed him there.'),
  ('8e3849e8-f6d9-588f-ae53-644479cbbc8a', '76aa8537-2598-5b49-a28f-a7ccb36c4134', NULL, 30, 30, 'Jacob called the name of the place Peniel: for, he said, "I have seen God face to face, and my life is preserved."'),
  ('3f69006f-a598-571c-ac4f-7fe9690b4684', '76aa8537-2598-5b49-a28f-a7ccb36c4134', NULL, 31, 31, 'The sun rose on him as he passed over Peniel, and he limped because of his thigh.'),
  ('8d1ddeb0-b2ca-59c5-a08f-4445dac425ec', '76aa8537-2598-5b49-a28f-a7ccb36c4134', NULL, 32, 32, 'Therefore the children of Israel don''t eat the sinew of the hip, which is on the hollow of the thigh, to this day, because he touched the hollow of Jacob''s thigh in the sinew of the hip.'),
  ('99a6d2b4-466b-5bdc-a404-194afe71c6b8', 'ebf86095-19b0-530c-ab5b-ff2c8f8a5dcf', NULL, 1, 1, 'Jacob lifted up his eyes, and looked, and, behold, Esau was coming, and with him four hundred men. He divided the children between Leah, Rachel, and the two handmaids.'),
  ('3397426c-b720-503d-a4ab-e11150355e30', 'ebf86095-19b0-530c-ab5b-ff2c8f8a5dcf', NULL, 2, 2, 'He put the handmaids and their children in front, Leah and her children after, and Rachel and Joseph at the rear.'),
  ('5f74c919-84c2-5422-a0dd-43d4dcc873d8', 'ebf86095-19b0-530c-ab5b-ff2c8f8a5dcf', NULL, 3, 3, 'He himself passed over in front of them, and bowed himself to the ground seven times, until he came near to his brother.'),
  ('3fbbe533-ecb5-5b60-a7d6-b07126c9032a', 'ebf86095-19b0-530c-ab5b-ff2c8f8a5dcf', NULL, 4, 4, 'Esau ran to meet him, embraced him, fell on his neck, kissed him, and they wept.'),
  ('20b60d34-b962-5ad9-a1af-8c055d577dd7', 'ebf86095-19b0-530c-ab5b-ff2c8f8a5dcf', NULL, 5, 5, 'He lifted up his eyes, and saw the women and the children; and said, "Who are these with you?" He said, "The children whom God has graciously given your servant."'),
  ('f54653d6-6091-52e7-a1f2-3ade9c36fa8e', 'ebf86095-19b0-530c-ab5b-ff2c8f8a5dcf', NULL, 6, 6, 'Then the handmaids came near with their children, and they bowed themselves.'),
  ('3c01142e-169a-5cfc-aa0b-8910dbcbe614', 'ebf86095-19b0-530c-ab5b-ff2c8f8a5dcf', NULL, 7, 7, 'Leah also and her children came near, and bowed themselves. After them, Joseph came near with Rachel, and they bowed themselves.'),
  ('3b3be6bf-68c3-52e1-a991-2ce16531a13c', 'ebf86095-19b0-530c-ab5b-ff2c8f8a5dcf', NULL, 8, 8, 'Esau said, "What do you mean by all this company which I met?" Jacob said, "To find favor in the sight of my lord."'),
  ('2177d076-43ae-59d5-aa8c-98320c484398', 'ebf86095-19b0-530c-ab5b-ff2c8f8a5dcf', NULL, 9, 9, 'Esau said, "I have enough, my brother; let that which you have be yours."'),
  ('e800f4d4-41ea-571d-a856-53b3caf6faac', 'ebf86095-19b0-530c-ab5b-ff2c8f8a5dcf', NULL, 10, 10, 'Jacob said, "Please, no, if I have now found favor in your sight, then receive my present at my hand, because I have seen your face, as one sees the face of God, and you were pleased with me.'),
  ('32d51724-ac63-59f5-ad7a-f4f1b31c67a0', 'ebf86095-19b0-530c-ab5b-ff2c8f8a5dcf', NULL, 11, 11, 'Please take the gift that I brought to you, because God has dealt graciously with me, and because I have enough." He urged him, and he took it.'),
  ('86bec8cb-553b-5172-a9b4-c4bcb93ef4ec', 'ebf86095-19b0-530c-ab5b-ff2c8f8a5dcf', NULL, 12, 12, 'Esau said, "Let us take our journey, and let us go, and I will go before you."'),
  ('2f38cf82-06a1-50b6-abb3-190272c113db', 'ebf86095-19b0-530c-ab5b-ff2c8f8a5dcf', NULL, 13, 13, 'Jacob said to him, "My lord knows that the children are tender, and that the flocks and herds with me have their young, and if they overdrive them one day, all the flocks will die.'),
  ('a8e15a6c-db5a-5edd-ab2b-29347374c084', 'ebf86095-19b0-530c-ab5b-ff2c8f8a5dcf', NULL, 14, 14, 'Please let my lord pass over before his servant, and I will lead on gently, according to the pace of the livestock that are before me and according to the pace of the children, until I come to my lord to Seir."'),
  ('671418fd-bce3-5f28-a070-a0570dbcc786', 'ebf86095-19b0-530c-ab5b-ff2c8f8a5dcf', NULL, 15, 15, 'Esau said, "Let me now leave with you some of the folk who are with me." He said, "Why? Let me find favor in the sight of my lord."'),
  ('8bc0c8f8-85e8-5b89-a54f-d45d79de5bab', 'ebf86095-19b0-530c-ab5b-ff2c8f8a5dcf', NULL, 16, 16, 'So Esau returned that day on his way to Seir.'),
  ('486feeab-19f0-5f43-abf7-44138f9f4ceb', 'ebf86095-19b0-530c-ab5b-ff2c8f8a5dcf', NULL, 17, 17, 'Jacob traveled to Succoth, built himself a house, and made shelters for his livestock. Therefore the name of the place is called Succoth.'),
  ('fc791af4-a6b6-5719-aba0-2ab92986dd4f', 'ebf86095-19b0-530c-ab5b-ff2c8f8a5dcf', NULL, 18, 18, 'Jacob came in peace to the city of Shechem, which is in the land of Canaan, when he came from Paddan Aram; and encamped before the city.'),
  ('fef7382a-fdbd-503a-aa81-a9a131bac03c', 'ebf86095-19b0-530c-ab5b-ff2c8f8a5dcf', NULL, 19, 19, 'He bought the parcel of ground where he had spread his tent, at the hand of the children of Hamor, Shechem''s father, for one hundred pieces of money.'),
  ('e6058b93-5fec-5b22-a7dd-822ac7f5cf98', 'ebf86095-19b0-530c-ab5b-ff2c8f8a5dcf', NULL, 20, 20, 'He erected an altar there, and called it El Elohe Israel.'),
  ('60f7fcd2-bc04-5674-a9db-3def8a006cee', '6c10fda1-9b8a-5691-a8e6-c6ec2bdbcd3f', NULL, 1, 1, 'Dinah, the daughter of Leah, whom she bore to Jacob, went out to see the daughters of the land.'),
  ('a9b4ea66-e289-5733-a04f-c6f3d3c79847', '6c10fda1-9b8a-5691-a8e6-c6ec2bdbcd3f', NULL, 2, 2, 'Shechem the son of Hamor the Hivite, the prince of the land, saw her. He took her, lay with her, and humbled her.'),
  ('06e5b084-9f50-549d-a0d1-9ae3b64c84af', '6c10fda1-9b8a-5691-a8e6-c6ec2bdbcd3f', NULL, 3, 3, 'His soul joined to Dinah, the daughter of Jacob, and he loved the young lady, and spoke kindly to the young lady.'),
  ('1dbc9b7f-70c6-5ea2-a477-06f3c5ba0c11', '6c10fda1-9b8a-5691-a8e6-c6ec2bdbcd3f', NULL, 4, 4, 'Shechem spoke to his father, Hamor, saying, "Get me this young lady as a wife."'),
  ('660c474f-1e1d-59f8-a9f0-52deab25c3b4', '6c10fda1-9b8a-5691-a8e6-c6ec2bdbcd3f', NULL, 5, 5, 'Now Jacob heard that he had defiled Dinah, his daughter; and his sons were with his livestock in the field. Jacob held his peace until they came.'),
  ('eb7ab700-75d5-51b3-ac83-0055b2e9dc4d', '6c10fda1-9b8a-5691-a8e6-c6ec2bdbcd3f', NULL, 6, 6, 'Hamor the father of Shechem went out to Jacob to talk with him.'),
  ('80d0abab-350a-5b0d-a184-110800619562', '6c10fda1-9b8a-5691-a8e6-c6ec2bdbcd3f', NULL, 7, 7, 'The sons of Jacob came in from the field when they heard it. The men were grieved, and they were very angry, because he had done folly in Israel in lying with Jacob''s daughter; a which thing ought not to be done.'),
  ('18aebdc5-4431-58d4-a511-cc21ba3eb3a0', '6c10fda1-9b8a-5691-a8e6-c6ec2bdbcd3f', NULL, 8, 8, 'Hamor talked with them, saying, "The soul of my son, Shechem, longs for your daughter. Please give her to him as a wife.'),
  ('1881c7f2-7769-5f70-a05a-c98adb1fec71', '6c10fda1-9b8a-5691-a8e6-c6ec2bdbcd3f', NULL, 9, 9, 'Make marriages with us. Give your daughters to us, and take our daughters for yourselves.'),
  ('30958cf7-b5ee-5a5b-aa54-4682987c4122', '6c10fda1-9b8a-5691-a8e6-c6ec2bdbcd3f', NULL, 10, 10, 'You shall dwell with us, and the land will be before you. Live and trade in it, and get possessions in it."'),
  ('388f5c93-ec31-559c-af4b-fe03a5adade9', '6c10fda1-9b8a-5691-a8e6-c6ec2bdbcd3f', NULL, 11, 11, 'Shechem said to her father and to her brothers, "Let me find favor in your eyes, and whatever you will tell me I will give.'),
  ('f73313de-ebde-59c3-a96f-257b339a0e50', '6c10fda1-9b8a-5691-a8e6-c6ec2bdbcd3f', NULL, 12, 12, 'Ask me a great amount for a dowry, and I will give whatever you ask of me, but give me the young lady as a wife."'),
  ('f6c91141-1525-58d6-afcb-8eb0bd88ff3c', '6c10fda1-9b8a-5691-a8e6-c6ec2bdbcd3f', NULL, 13, 13, 'The sons of Jacob answered Shechem and Hamor his father with deceit, and spoke, because he had defiled Dinah their sister,'),
  ('e3b7af42-ddfa-5400-a3be-7d385fabb743', '6c10fda1-9b8a-5691-a8e6-c6ec2bdbcd3f', NULL, 14, 14, 'and said to them, "We can''t do this thing, to give our sister to one who is uncircumcised; for that is a reproach to us.'),
  ('01997b54-65fd-5627-ac38-0b6e3f33a665', '6c10fda1-9b8a-5691-a8e6-c6ec2bdbcd3f', NULL, 15, 15, 'Only on this condition will we consent to you. If you will be as we are, that every male of you be circumcised;'),
  ('fda350e0-b2e8-5645-a5e3-653238edad53', '6c10fda1-9b8a-5691-a8e6-c6ec2bdbcd3f', NULL, 16, 16, 'then will we give our daughters to you, and we will take your daughters to us, and we will dwell with you, and we will become one people.'),
  ('aa91944c-de3c-5a37-a58a-e7626d9cce6c', '6c10fda1-9b8a-5691-a8e6-c6ec2bdbcd3f', NULL, 17, 17, 'But if you will not listen to us, to be circumcised, then we will take our sister, and we will be gone."'),
  ('44d63eac-658a-532d-a02a-c6cf0456470b', '6c10fda1-9b8a-5691-a8e6-c6ec2bdbcd3f', NULL, 18, 18, 'Their words pleased Hamor and Shechem, Hamor''s son.'),
  ('2c3869aa-0faf-52dd-a6ff-7db1501476ed', '6c10fda1-9b8a-5691-a8e6-c6ec2bdbcd3f', NULL, 19, 19, 'The young man didn''t wait to do this thing, because he had delight in Jacob''s daughter, and he was honored above all the house of his father.'),
  ('800cad24-2a08-5d4b-a986-4d1589b67593', '6c10fda1-9b8a-5691-a8e6-c6ec2bdbcd3f', NULL, 20, 20, 'Hamor and Shechem, his son, came to the gate of their city, and talked with the men of their city, saying,'),
  ('98cc0439-18fd-5d3b-ac59-0abf5f7bbb13', '6c10fda1-9b8a-5691-a8e6-c6ec2bdbcd3f', NULL, 21, 21, '"These men are peaceful with us. Therefore let them live in the land and trade in it. For behold, the land is large enough for them. Let us take their daughters to us for wives, and let us give them our daughters.'),
  ('89d6d8b9-2db1-5a90-ae89-94268a9f67ed', '6c10fda1-9b8a-5691-a8e6-c6ec2bdbcd3f', NULL, 22, 22, 'Only on this condition will the men consent to us to live with us, to become one people, if every male among us is circumcised, as they are circumcised.'),
  ('8583e2e6-9313-5685-a322-9121aa02e44e', '6c10fda1-9b8a-5691-a8e6-c6ec2bdbcd3f', NULL, 23, 23, 'Won''t their livestock and their possessions and all their animals be ours? Only let us give our consent to them, and they will dwell with us."'),
  ('6fbc364f-c9cd-58f2-a298-06661e0f318b', '6c10fda1-9b8a-5691-a8e6-c6ec2bdbcd3f', NULL, 24, 24, 'All who went out of the gate of his city listened to Hamor, and to Shechem his son; and every male was circumcised, all who went out of the gate of his city.'),
  ('e7f738dd-12d3-56e4-a849-b91852b1c9f0', '6c10fda1-9b8a-5691-a8e6-c6ec2bdbcd3f', NULL, 25, 25, 'It happened on the third day, when they were sore, that two of Jacob''s sons, Simeon and Levi, Dinah''s brothers, each took his sword, came upon the unsuspecting city, and killed all the males.'),
  ('bbe7590a-07ce-54b7-a3c1-52d1944a5a66', '6c10fda1-9b8a-5691-a8e6-c6ec2bdbcd3f', NULL, 26, 26, 'They killed Hamor and Shechem, his son, with the edge of the sword, and took Dinah out of Shechem''s house, and went away.'),
  ('8e0cc18d-4b86-5704-a63f-c76a9b073af3', '6c10fda1-9b8a-5691-a8e6-c6ec2bdbcd3f', NULL, 27, 27, 'Jacob''s sons came on the dead, and plundered the city, because they had defiled their sister.'),
  ('dc6e2b59-8150-5d25-a2b7-f442be575899', '6c10fda1-9b8a-5691-a8e6-c6ec2bdbcd3f', NULL, 28, 28, 'They took their flocks, their herds, their donkeys, that which was in the city, that which was in the field,'),
  ('cc80b96a-8cc5-54d5-aab1-bebb8001465d', '6c10fda1-9b8a-5691-a8e6-c6ec2bdbcd3f', NULL, 29, 29, 'and all their wealth. They took captive all their little ones and their wives, and took as plunder everything that was in the house.'),
  ('b0e2b5e9-b7f8-5f6f-a93a-08bb540b6098', '6c10fda1-9b8a-5691-a8e6-c6ec2bdbcd3f', NULL, 30, 30, 'Jacob said to Simeon and Levi, "You have troubled me, to make me odious to the inhabitants of the land, among the Canaanites and the Perizzites. I am few in number. They will gather themselves together against me and strike me, and I will be destroyed, I and my house."'),
  ('6d625776-934b-5a35-aa20-8378885e0012', '6c10fda1-9b8a-5691-a8e6-c6ec2bdbcd3f', NULL, 31, 31, 'They said, "Should he deal with our sister as with a prostitute?"'),
  ('5b2b0148-93da-5d71-a296-02688ac21125', 'b0dd8c1d-e17b-5f57-ac4b-bfa446c3a6bd', NULL, 1, 1, 'God said to Jacob, "Arise, go up to Bethel, and live there. Make there an altar to God, who appeared to you when you fled from the face of Esau your brother."'),
  ('54b59484-f1a8-5408-a804-8f2357d58812', 'b0dd8c1d-e17b-5f57-ac4b-bfa446c3a6bd', NULL, 2, 2, 'Then Jacob said to his household, and to all who were with him, "Put away the foreign gods that are among you, purify yourselves, change your garments.'),
  ('2460d3cf-3fa6-5c02-a311-5901cf59c8af', 'b0dd8c1d-e17b-5f57-ac4b-bfa446c3a6bd', NULL, 3, 3, 'Let us arise, and go up to Bethel. I will make there an altar to God, who answered me in the day of my distress, and was with me in the way which I went."'),
  ('f2a01ea9-1c13-58e5-a376-6db004b55d10', 'b0dd8c1d-e17b-5f57-ac4b-bfa446c3a6bd', NULL, 4, 4, 'They gave to Jacob all the foreign gods which were in their hands, and the rings which were in their ears; and Jacob hid them under the oak which was by Shechem.'),
  ('6224b31c-594f-5504-a0d4-cf156f9859d4', 'b0dd8c1d-e17b-5f57-ac4b-bfa446c3a6bd', NULL, 5, 5, 'They traveled, and a terror of God was on the cities that were around them, and they didn''t pursue the sons of Jacob.'),
  ('0390e261-73d5-5424-a940-7abb44425e52', 'b0dd8c1d-e17b-5f57-ac4b-bfa446c3a6bd', NULL, 6, 6, 'So Jacob came to Luz (that is, Bethel), which is in the land of Canaan, he and all the people who were with him.'),
  ('120b2784-b7e7-5cb8-abbd-86f79a87d80a', 'b0dd8c1d-e17b-5f57-ac4b-bfa446c3a6bd', NULL, 7, 7, 'He built an altar there, and called the place El Beth El; because there God was revealed to him, when he fled from the face of his brother.'),
  ('e4978059-8322-5ec9-aa9a-a27476941c84', 'b0dd8c1d-e17b-5f57-ac4b-bfa446c3a6bd', NULL, 8, 8, 'Deborah, Rebekah''s nurse, died, and she was buried below Bethel under the oak; and its name was called Allon Bacuth.'),
  ('35c58bf6-b837-5fa8-a9e3-931cb047a41a', 'b0dd8c1d-e17b-5f57-ac4b-bfa446c3a6bd', NULL, 9, 9, 'God appeared to Jacob again, when he came from Paddan Aram, and blessed him.'),
  ('50398eef-cf6e-577f-a389-4ab57377f4c4', 'b0dd8c1d-e17b-5f57-ac4b-bfa446c3a6bd', NULL, 10, 10, 'God said to him, "Your name is Jacob. Your name shall not be Jacob any more, but your name will be Israel." He named him Israel.'),
  ('bfd74877-55eb-5f32-a144-73bb996856ac', 'b0dd8c1d-e17b-5f57-ac4b-bfa446c3a6bd', NULL, 11, 11, 'God said to him, "I am God Almighty. Be fruitful and multiply. A nation and a company of nations will be from you, and kings will come out of your body.'),
  ('72d1aef5-e607-5ee6-ad6a-eee42dacb35e', 'b0dd8c1d-e17b-5f57-ac4b-bfa446c3a6bd', NULL, 12, 12, 'The land which I gave to Abraham and Isaac, I will give it to you, and to your seed after you will I give the land."'),
  ('8f1cf17a-840f-5a8c-a790-d367eb4241c5', 'b0dd8c1d-e17b-5f57-ac4b-bfa446c3a6bd', NULL, 13, 13, 'God went up from him in the place where he spoke with him.'),
  ('0735aad3-2e18-55e6-ac3e-48c01aace6fa', 'b0dd8c1d-e17b-5f57-ac4b-bfa446c3a6bd', NULL, 14, 14, 'Jacob set up a pillar in the place where he spoke with him, a pillar of stone. He poured out a drink offering on it, and poured oil on it.'),
  ('6e469c59-ba8e-5fcc-aaee-ba66568ffb3f', 'b0dd8c1d-e17b-5f57-ac4b-bfa446c3a6bd', NULL, 15, 15, 'Jacob called the name of the place where God spoke with him "Bethel."'),
  ('5c191e9a-60b7-555f-afe0-d0eb3461b7b2', 'b0dd8c1d-e17b-5f57-ac4b-bfa446c3a6bd', NULL, 16, 16, 'They traveled from Bethel. There was still some distance to come to Ephrath, and Rachel travailed. She had hard labor.'),
  ('030a80c3-a5ce-573b-a7fe-81ff347a10f7', 'b0dd8c1d-e17b-5f57-ac4b-bfa446c3a6bd', NULL, 17, 17, 'When she was in hard labor, the midwife said to her, "Don''t be afraid, for now you will have another son."'),
  ('9d06650d-c497-5926-a0d8-72c4563fbc0a', 'b0dd8c1d-e17b-5f57-ac4b-bfa446c3a6bd', NULL, 18, 18, 'It happened, as her soul was departing (for she died), that she named him Benoni, but his father named him Benjamin.'),
  ('2685579c-4d68-5115-a81d-863bf9968861', 'b0dd8c1d-e17b-5f57-ac4b-bfa446c3a6bd', NULL, 19, 19, 'Rachel died, and was buried in the way to Ephrath (the same is Bethlehem).'),
  ('54c06efa-1fc4-5ce5-abec-485e835f0e44', 'b0dd8c1d-e17b-5f57-ac4b-bfa446c3a6bd', NULL, 20, 20, 'Jacob set up a pillar on her grave. The same is the Pillar of Rachel''s grave to this day.'),
  ('22282ea5-f96e-5341-a20e-73c9c2d5c975', 'b0dd8c1d-e17b-5f57-ac4b-bfa446c3a6bd', NULL, 21, 21, 'Israel traveled, and spread his tent beyond the tower of Eder.'),
  ('168789e7-c6d6-57a7-a33a-0efe6f4c3fff', 'b0dd8c1d-e17b-5f57-ac4b-bfa446c3a6bd', NULL, 22, 22, 'It happened, while Israel lived in that land, that Reuben went and lay with Bilhah, his father''s concubine, and Israel heard of it. Now the sons of Jacob were twelve.'),
  ('9527744a-9fe4-5f90-a16e-67ecb7dacc87', 'b0dd8c1d-e17b-5f57-ac4b-bfa446c3a6bd', NULL, 23, 23, 'The sons of Leah: Reuben (Jacob''s firstborn), Simeon, Levi, Judah, Issachar, and Zebulun.'),
  ('2958d616-0532-5e26-a2c3-c1604c92ecf8', 'b0dd8c1d-e17b-5f57-ac4b-bfa446c3a6bd', NULL, 24, 24, 'The sons of Rachel: Joseph and Benjamin.'),
  ('b1554eb6-a170-5034-a0ed-bfe5eb174ce6', 'b0dd8c1d-e17b-5f57-ac4b-bfa446c3a6bd', NULL, 25, 25, 'The sons of Bilhah (Rachel''s handmaid): Dan and Naphtali.'),
  ('1102bd37-1561-5178-a489-ee4a4eb33129', 'b0dd8c1d-e17b-5f57-ac4b-bfa446c3a6bd', NULL, 26, 26, 'The sons of Zilpah (Leah''s handmaid): Gad and Asher. These are the sons of Jacob, who were born to him in Paddan Aram.'),
  ('28de3703-5c55-56c9-ad14-64e582453f38', 'b0dd8c1d-e17b-5f57-ac4b-bfa446c3a6bd', NULL, 27, 27, 'Jacob came to Isaac his father, to Mamre, to Kiriath Arba (which is Hebron), where Abraham and Isaac lived as foreigners.'),
  ('3b9dca67-7f27-5768-a7ba-6fb92bd08a75', 'b0dd8c1d-e17b-5f57-ac4b-bfa446c3a6bd', NULL, 28, 28, 'The days of Isaac were one hundred eighty years.'),
  ('4d0de517-c217-52c6-a625-5aea16332b50', 'b0dd8c1d-e17b-5f57-ac4b-bfa446c3a6bd', NULL, 29, 29, 'Isaac gave up the spirit, and died, and was gathered to his people, old and full of days. Esau and Jacob, his sons, buried him.'),
  ('e8118a35-80f6-5ebb-acd4-3521674cb1a8', '30acd03e-306f-5ec1-abee-df23ff44214d', NULL, 1, 1, 'Now this is the history of the generations of Esau (that is, Edom).'),
  ('dc507e10-c573-5784-a700-6dec3fcb9cbf', '30acd03e-306f-5ec1-abee-df23ff44214d', NULL, 2, 2, 'Esau took his wives from the daughters of Canaan: Adah the daughter of Elon, the Hittite; and Oholibamah the daughter of Anah, the daughter of Zibeon, the Hivite;'),
  ('e8b26fcd-5969-5a9c-aa67-7401cb44f219', '30acd03e-306f-5ec1-abee-df23ff44214d', NULL, 3, 3, 'and Basemath, Ishmael''s daughter, sister of Nebaioth.'),
  ('3d054784-3829-5e67-aa7e-833e69e3b61b', '30acd03e-306f-5ec1-abee-df23ff44214d', NULL, 4, 4, 'Adah bore to Esau Eliphaz. Basemath bore Reuel.'),
  ('c438f538-5540-5aef-a22f-840df2e770d0', '30acd03e-306f-5ec1-abee-df23ff44214d', NULL, 5, 5, 'Oholibamah bore Jeush, Jalam, and Korah. These are the sons of Esau, who were born to him in the land of Canaan.'),
  ('e54a84fb-540b-5fab-a06e-76e888a1f697', '30acd03e-306f-5ec1-abee-df23ff44214d', NULL, 6, 6, 'Esau took his wives, his sons, his daughters, and all the members of his household, with his livestock, all his animals, and all his possessions, which he had gathered in the land of Canaan, and went into a land away from his brother Jacob.'),
  ('2f10aefd-01f4-5b4b-ae7c-aeba64cacf7c', '30acd03e-306f-5ec1-abee-df23ff44214d', NULL, 7, 7, 'For their substance was too great for them to dwell together, and the land of their travels couldn''t bear them because of their livestock.'),
  ('34602785-5ca3-5ec7-af34-2484ee38deb6', '30acd03e-306f-5ec1-abee-df23ff44214d', NULL, 8, 8, 'Esau lived in the hill country of Seir. Esau is Edom.'),
  ('9dfaf93d-9ae9-5c06-aee9-bc0990c5933d', '30acd03e-306f-5ec1-abee-df23ff44214d', NULL, 9, 9, 'This is the history of the generations of Esau the father of the Edomites in the hill country of Seir:'),
  ('219f7c06-0d49-5f80-a93e-a2015dcfa4b0', '30acd03e-306f-5ec1-abee-df23ff44214d', NULL, 10, 10, 'these are the names of Esau''s sons: Eliphaz, the son of Adah, the wife of Esau; and Reuel, the son of Basemath, the wife of Esau.'),
  ('8bd2287e-c6d3-5af0-a89d-35a2fd5a1e19', '30acd03e-306f-5ec1-abee-df23ff44214d', NULL, 11, 11, 'The sons of Eliphaz were Teman, Omar, Zepho, and Gatam, and Kenaz.'),
  ('7e701064-6581-5744-a48d-11f5ba0d6cea', '30acd03e-306f-5ec1-abee-df23ff44214d', NULL, 12, 12, 'Timna was concubine to Eliphaz, Esau''s son; and she bore to Eliphaz Amalek. These are the sons of Adah, Esau''s wife.'),
  ('af2079f5-8f5c-5470-a1ce-0ff291af1294', '30acd03e-306f-5ec1-abee-df23ff44214d', NULL, 13, 13, 'These are the sons of Reuel: Nahath, Zerah, Shammah, and Mizzah. These were the sons of Basemath, Esau''s wife.'),
  ('a123a304-4ea2-5bb1-aa12-9ad96389ef98', '30acd03e-306f-5ec1-abee-df23ff44214d', NULL, 14, 14, 'These were the sons of Oholibamah, the daughter of Anah, the daughter of Zibeon, Esau''s wife: she bore to Esau Jeush, Jalam, and Korah.'),
  ('1d659796-5f09-5078-ac07-54362a4f908c', '30acd03e-306f-5ec1-abee-df23ff44214d', NULL, 15, 15, 'These are the chiefs of the sons of Esau: the sons of Eliphaz the firstborn of Esau: chief Teman, chief Omar, chief Zepho, chief Kenaz,'),
  ('e21c1adf-a335-5a7a-a70e-453d6026445f', '30acd03e-306f-5ec1-abee-df23ff44214d', NULL, 16, 16, 'chief Korah, chief Gatam, chief Amalek: these are the chiefs who came of Eliphaz in the land of Edom; these are the sons of Adah.'),
  ('f9726944-b649-5b9c-a72b-0cd7bd85df42', '30acd03e-306f-5ec1-abee-df23ff44214d', NULL, 17, 17, 'These are the sons of Reuel, Esau''s son: chief Nahath, chief Zerah, chief Shammah, chief Mizzah: these are the chiefs who came of Reuel in the land of Edom; these are the sons of Basemath, Esau''s wife.'),
  ('9da0de9e-6ee9-559f-aa95-a9c9001a1487', '30acd03e-306f-5ec1-abee-df23ff44214d', NULL, 18, 18, 'These are the sons of Oholibamah, Esau''s wife: chief Jeush, chief Jalam, chief Korah: these are the chiefs who came of Oholibamah the daughter of Anah, Esau''s wife.'),
  ('493e933f-f229-5c21-a082-dc3bab28e189', '30acd03e-306f-5ec1-abee-df23ff44214d', NULL, 19, 19, 'These are the sons of Esau (that is, Edom), and these are their chiefs.'),
  ('12e2fcac-fdfc-5900-a470-00c4ed2e0690', '30acd03e-306f-5ec1-abee-df23ff44214d', NULL, 20, 20, 'These are the sons of Seir the Horite, the inhabitants of the land: Lotan, Shobal, Zibeon, Anah,'),
  ('6585527a-ce65-5d33-a55f-c35fd71d3fd5', '30acd03e-306f-5ec1-abee-df23ff44214d', NULL, 21, 21, 'Dishon, Ezer, and Dishan. These are the chiefs who came of the Horites, the children of Seir in the land of Edom.'),
  ('36b35845-e91c-56df-a4d8-abec4915199f', '30acd03e-306f-5ec1-abee-df23ff44214d', NULL, 22, 22, 'The children of Lotan were Hori and Heman. Lotan''s sister was Timna.'),
  ('678e736e-0aa0-5bbf-ab7b-e3d495c4d2d9', '30acd03e-306f-5ec1-abee-df23ff44214d', NULL, 23, 23, 'These are the children of Shobal: Alvan, Manahath, Ebal, Shepho, and Onam.'),
  ('45b03b07-fd9d-59e5-ab4c-57991e9247c8', '30acd03e-306f-5ec1-abee-df23ff44214d', NULL, 24, 24, 'These are the children of Zibeon: Aiah and Anah. This is Anah who found the hot springs in the wilderness, as he fed the donkeys of Zibeon his father.'),
  ('59c276f4-5720-5e45-ab48-cc4f74d7bb5d', '30acd03e-306f-5ec1-abee-df23ff44214d', NULL, 25, 25, 'These are the children of Anah: Dishon and Oholibamah, the daughter of Anah.'),
  ('0ca90448-dbce-58d0-a949-4e2602272eba', '30acd03e-306f-5ec1-abee-df23ff44214d', NULL, 26, 26, 'These are the children of Dishon: Hemdan, Eshban, Ithran, and Cheran.'),
  ('ca0aa599-39bc-5868-ae81-930606145b18', '30acd03e-306f-5ec1-abee-df23ff44214d', NULL, 27, 27, 'These are the children of Ezer: Bilhan, Zaavan, and Akan.'),
  ('2367f102-80ec-5e51-a954-777931d650bf', '30acd03e-306f-5ec1-abee-df23ff44214d', NULL, 28, 28, 'These are the children of Dishan: Uz and Aran.'),
  ('cf8eb55e-ecc5-5210-a55a-341e9ec560d4', '30acd03e-306f-5ec1-abee-df23ff44214d', NULL, 29, 29, 'These are the chiefs who came of the Horites: chief Lotan, chief Shobal, chief Zibeon, chief Anah,'),
  ('a85e60f6-fefc-5280-a22a-c0a12b71757b', '30acd03e-306f-5ec1-abee-df23ff44214d', NULL, 30, 30, 'chief Dishon, chief Ezer, and chief Dishan: these are the chiefs who came of the Horites, according to their chiefs in the land of Seir.'),
  ('8daf547e-6994-5f59-a949-fd55301c5618', '30acd03e-306f-5ec1-abee-df23ff44214d', NULL, 31, 31, 'These are the kings who reigned in the land of Edom, before any king reigned over the children of Israel.'),
  ('d2ea24a2-4ef9-5637-a7b0-983baecc1a67', '30acd03e-306f-5ec1-abee-df23ff44214d', NULL, 32, 32, 'Bela, the son of Beor, reigned in Edom. The name of his city was Dinhabah.'),
  ('f21cf673-39ed-5b3e-ab66-4dc3790b0beb', '30acd03e-306f-5ec1-abee-df23ff44214d', NULL, 33, 33, 'Bela died, and Jobab, the son of Zerah of Bozrah, reigned in his place.'),
  ('1b870016-ea33-5dd1-a299-97a6c69c9d94', '30acd03e-306f-5ec1-abee-df23ff44214d', NULL, 34, 34, 'Jobab died, and Husham of the land of the Temanites reigned in his place.'),
  ('7a0cb5ae-aa88-5d8f-a7c0-d14b06e16bb5', '30acd03e-306f-5ec1-abee-df23ff44214d', NULL, 35, 35, 'Husham died, and Hadad, the son of Bedad, who struck Midian in the field of Moab, reigned in his place. The name of his city was Avith.'),
  ('d1351a8d-10b4-5686-a49f-1c8648d36795', '30acd03e-306f-5ec1-abee-df23ff44214d', NULL, 36, 36, 'Hadad died, and Samlah of Masrekah reigned in his place.'),
  ('16fc54c3-50a3-5c1f-acc9-e3c23d4a1e76', '30acd03e-306f-5ec1-abee-df23ff44214d', NULL, 37, 37, 'Samlah died, and Shaul of Rehoboth by the river, reigned in his place.'),
  ('1a17779f-9f23-5ad5-a8f4-898a51855261', '30acd03e-306f-5ec1-abee-df23ff44214d', NULL, 38, 38, 'Shaul died, and Baal Hanan, the son of Achbor reigned in his place.'),
  ('f5c6e11f-15a0-5613-a444-a137035eadc5', '30acd03e-306f-5ec1-abee-df23ff44214d', NULL, 39, 39, 'Baal Hanan the son of Achbor died, and Hadar reigned in his place. The name of his city was Pau. His wife''s name was Mehetabel, the daughter of Matred, the daughter of Mezahab.'),
  ('12235f8e-72f2-582a-af3c-4b907e90eb8c', '30acd03e-306f-5ec1-abee-df23ff44214d', NULL, 40, 40, 'These are the names of the chiefs who came from Esau, according to their families, after their places, and by their names: chief Timna, chief Alvah, chief Jetheth,'),
  ('fb9ecd69-85cd-5236-a7ce-4fa4c870ef76', '30acd03e-306f-5ec1-abee-df23ff44214d', NULL, 41, 41, 'chief Oholibamah, chief Elah, chief Pinon,'),
  ('f62b776a-83c7-5b1c-a0d3-e23bcf23237e', '30acd03e-306f-5ec1-abee-df23ff44214d', NULL, 42, 42, 'chief Kenaz, chief Teman, chief Mibzar,'),
  ('21160f57-f686-5d1a-a8d4-4098e921a2e0', '30acd03e-306f-5ec1-abee-df23ff44214d', NULL, 43, 43, 'chief Magdiel, and chief Iram. These are the chiefs of Edom, according to their habitations in the land of their possession. This is Esau, the father of the Edomites.'),
  ('f12e2861-e3e1-59f9-a9e2-1c53509bae85', '1c521f48-6a67-5704-a692-3d3db4718fd8', NULL, 1, 1, 'Jacob lived in the land of his father''s travels, in the land of Canaan.'),
  ('61cf8a62-4d96-57d6-a89b-724d68cbbc56', '1c521f48-6a67-5704-a692-3d3db4718fd8', NULL, 2, 2, 'This is the history of the generations of Jacob. Joseph, being seventeen years old, was feeding the flock with his brothers. He was a boy with the sons of Bilhah and Zilpah, his father''s wives. Joseph brought an evil report of them to their father.'),
  ('918bbe9c-8c9a-56ef-a624-a94c82d9bfbe', '1c521f48-6a67-5704-a692-3d3db4718fd8', NULL, 3, 3, 'Now Israel loved Joseph more than all his children, because he was the son of his old age, and he made him a coat of many colors.'),
  ('9685150a-218b-5703-a39a-a05b56bbdfe5', '1c521f48-6a67-5704-a692-3d3db4718fd8', NULL, 4, 4, 'His brothers saw that their father loved him more than all his brothers, and they hated him, and couldn''t speak peaceably to him.'),
  ('8803b9ee-a827-5cf8-a393-9e9887d84481', '1c521f48-6a67-5704-a692-3d3db4718fd8', NULL, 5, 5, 'Joseph dreamed a dream, and he told it to his brothers, and they hated him all the more.'),
  ('5800c515-5212-58b3-aaf4-59bc69378ed1', '1c521f48-6a67-5704-a692-3d3db4718fd8', NULL, 6, 6, 'He said to them, "Please hear this dream which I have dreamed:'),
  ('a84f80a6-1a82-56e4-a780-b5b95ec87857', '1c521f48-6a67-5704-a692-3d3db4718fd8', NULL, 7, 7, 'for behold, we were binding sheaves in the field, and behold, my sheaf arose and also stood upright; and behold, your sheaves came around, and bowed down to my sheaf."'),
  ('0f2e5e21-1c35-5203-a4cd-15af4acb4c22', '1c521f48-6a67-5704-a692-3d3db4718fd8', NULL, 8, 8, 'His brothers said to him, "Will you indeed reign over us? Or will you indeed have dominion over us?" They hated him all the more for his dreams and for his words.'),
  ('2e41b981-7b7c-5c2c-a07a-ab119486b52f', '1c521f48-6a67-5704-a692-3d3db4718fd8', NULL, 9, 9, 'He dreamed yet another dream, and told it to his brothers, and said, "Behold, I have dreamed yet another dream: and behold, the sun and the moon and eleven stars bowed down to me."'),
  ('41305b3f-645a-553d-ae72-635aab00743d', '1c521f48-6a67-5704-a692-3d3db4718fd8', NULL, 10, 10, 'He told it to his father and to his brothers. His father rebuked him, and said to him, "What is this dream that you have dreamed? Will I and your mother and your brothers indeed come to bow ourselves down to you to the earth?"'),
  ('07658076-d251-5ebb-a9c3-7982b7618015', '1c521f48-6a67-5704-a692-3d3db4718fd8', NULL, 11, 11, 'His brothers envied him, but his father kept this saying in mind.'),
  ('3068046f-1065-5711-ae02-e3b8c6b2c5ee', '1c521f48-6a67-5704-a692-3d3db4718fd8', NULL, 12, 12, 'His brothers went to feed their father''s flock in Shechem.'),
  ('3abb3958-bf6b-54bf-a1ea-f045e28d1881', '1c521f48-6a67-5704-a692-3d3db4718fd8', NULL, 13, 13, 'Israel said to Joseph, "Aren''t your brothers feeding the flock in Shechem? Come, and I will send you to them." He said to him, "Here I am."'),
  ('a5442127-2d25-5ebc-a523-9acbf2f8960b', '1c521f48-6a67-5704-a692-3d3db4718fd8', NULL, 14, 14, 'He said to him, "Go now, see whether it is well with your brothers, and well with the flock; and bring me word again." So he sent him out of the valley of Hebron, and he came to Shechem.'),
  ('2f8fc223-01e2-591b-a85e-90165a28fdca', '1c521f48-6a67-5704-a692-3d3db4718fd8', NULL, 15, 15, 'A certain man found him, and behold, he was wandering in the field. The man asked him, "What are you looking for?"'),
  ('0c0ba81d-1b6d-54cd-a7ca-ece367a6f39a', '1c521f48-6a67-5704-a692-3d3db4718fd8', NULL, 16, 16, 'He said, "I am looking for my brothers. Tell me, please, where they are feeding the flock."'),
  ('e7fa6221-29eb-59f2-a0ed-b914bdcdc931', '1c521f48-6a67-5704-a692-3d3db4718fd8', NULL, 17, 17, 'The man said, "They have left here, for I heard them say, ''Let us go to Dothan.''" Joseph went after his brothers, and found them in Dothan.'),
  ('7bb724ef-cfc8-56d8-a6fc-e8b47edba1eb', '1c521f48-6a67-5704-a692-3d3db4718fd8', NULL, 18, 18, 'They saw him afar off, and before he came near to them, they conspired against him to kill him.'),
  ('67ea8376-9b70-5a1f-a7aa-520067af1d1b', '1c521f48-6a67-5704-a692-3d3db4718fd8', NULL, 19, 19, 'They said one to another, "Behold, this dreamer comes.'),
  ('cdd2944f-6dea-5b49-ab81-45a0fa3173ae', '1c521f48-6a67-5704-a692-3d3db4718fd8', NULL, 20, 20, 'Come now therefore, and let''s kill him, and cast him into one of the pits, and we will say, ''An evil animal has devoured him.'' We will see what will become of his dreams."'),
  ('6e934b8d-b720-505e-a3db-6e9138ffc192', '1c521f48-6a67-5704-a692-3d3db4718fd8', NULL, 21, 21, 'Reuben heard it, and delivered him out of their hand, and said, "Let''s not take his life."'),
  ('d993d563-4382-5b1e-a8aa-cfa8a4b174aa', '1c521f48-6a67-5704-a692-3d3db4718fd8', NULL, 22, 22, 'Reuben said to them, "Shed no blood. Throw him into this pit that is in the wilderness, but lay no hand on him"--that he might deliver him out of their hand, to restore him to his father.'),
  ('211e1066-e142-5649-a801-dd3a9950806e', '1c521f48-6a67-5704-a692-3d3db4718fd8', NULL, 23, 23, 'It happened, when Joseph came to his brothers, that they stripped Joseph of his coat, the coat of many colors that was on him;'),
  ('a897f6f3-4bb3-50e8-aab8-8c7dcd3b55e3', '1c521f48-6a67-5704-a692-3d3db4718fd8', NULL, 24, 24, 'and they took him, and threw him into the pit. The pit was empty. There was no water in it.'),
  ('12073fb3-dcad-5944-a877-15ab2369fe94', '1c521f48-6a67-5704-a692-3d3db4718fd8', NULL, 25, 25, 'They sat down to eat bread, and they lifted up their eyes and looked, and saw a caravan of Ishmaelites was coming from Gilead, with their camels bearing spices and balm and myrrh, going to carry it down to Egypt.'),
  ('bfa92ddf-468a-580f-aded-100d662ffd19', '1c521f48-6a67-5704-a692-3d3db4718fd8', NULL, 26, 26, 'Judah said to his brothers, "What profit is it if we kill our brother and conceal his blood?'),
  ('206a277a-9193-5e2a-a92b-75c7fb933511', '1c521f48-6a67-5704-a692-3d3db4718fd8', NULL, 27, 27, 'Come, and let''s sell him to the Ishmaelites, and not let our hand be on him; for he is our brother, our flesh." His brothers listened to him.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('6008a6f4-d8a1-5169-a56e-d28f34078624', '1c521f48-6a67-5704-a692-3d3db4718fd8', NULL, 28, 28, 'Midianites who were merchants passed by, and they drew and lifted up Joseph out of the pit, and sold Joseph to the Ishmaelites for twenty pieces of silver. They brought Joseph into Egypt.'),
  ('1a630c48-6b66-5987-a093-5204d785d390', '1c521f48-6a67-5704-a692-3d3db4718fd8', NULL, 29, 29, 'Reuben returned to the pit; and saw that Joseph wasn''t in the pit; and he tore his clothes.'),
  ('e737f3e2-98cd-5ef8-add4-e07364d64892', '1c521f48-6a67-5704-a692-3d3db4718fd8', NULL, 30, 30, 'He returned to his brothers, and said, "The child is no more; and I, where will I go?"'),
  ('a3e46979-2ef7-5741-ae7c-f6aed4b8d4da', '1c521f48-6a67-5704-a692-3d3db4718fd8', NULL, 31, 31, 'They took Joseph''s coat, and killed a male goat, and dipped the coat in the blood.'),
  ('44dabdb1-ec8f-5268-a4f5-f92ff36f6582', '1c521f48-6a67-5704-a692-3d3db4718fd8', NULL, 32, 32, 'They took the coat of many colors, and they brought it to their father, and said, "We have found this. Examine it, now, whether it is your son''s coat or not."'),
  ('31db8fd7-b1ff-53fe-a3d2-b8e011920213', '1c521f48-6a67-5704-a692-3d3db4718fd8', NULL, 33, 33, 'He recognized it, and said, "It is my son''s coat. An evil animal has devoured him. Joseph is without doubt torn in pieces."'),
  ('e9346d30-9fde-54d0-a199-af8b8ee64eee', '1c521f48-6a67-5704-a692-3d3db4718fd8', NULL, 34, 34, 'Jacob tore his clothes, and put sackcloth on his waist, and mourned for his son many days.'),
  ('709a62e6-2964-5d48-a07b-7aebe9e4331f', '1c521f48-6a67-5704-a692-3d3db4718fd8', NULL, 35, 35, 'All his sons and all his daughters rose up to comfort him, but he refused to be comforted. He said, "For I will go down to Sheol to my son mourning." His father wept for him.'),
  ('b98a6c05-d09b-511e-aa6c-942b7520b25e', '1c521f48-6a67-5704-a692-3d3db4718fd8', NULL, 36, 36, 'The Midianites sold him into Egypt to Potiphar, an officer of Pharaoh''s, the captain of the guard.'),
  ('d05f5cb4-fa8c-5875-a85a-be72a3700122', '7daf3407-3437-5148-ab04-f754d50ddcd5', NULL, 1, 1, 'It happened at that time, that Judah went down from his brothers, and visited a certain Adullamite, whose name was Hirah.'),
  ('5c235e7c-661a-5198-ae94-a8ef69956c8f', '7daf3407-3437-5148-ab04-f754d50ddcd5', NULL, 2, 2, 'Judah saw there a daughter of a certain Canaanite whose name was Shua. He took her, and went in to her.'),
  ('28fa6192-4599-51de-a859-f024f25b63da', '7daf3407-3437-5148-ab04-f754d50ddcd5', NULL, 3, 3, 'She conceived, and bore a son; and he named him Er.'),
  ('ba5edb20-e892-5db0-a7f9-34fc5ac23d47', '7daf3407-3437-5148-ab04-f754d50ddcd5', NULL, 4, 4, 'She conceived again, and bore a son; and she named him Onan.'),
  ('c86fe074-fe7a-54be-aa83-161a1fd474d6', '7daf3407-3437-5148-ab04-f754d50ddcd5', NULL, 5, 5, 'She yet again bore a son, and named him Shelah: and he was at Chezib, when she bore him.'),
  ('98764136-9d08-5f0d-a2c6-231a40565c54', '7daf3407-3437-5148-ab04-f754d50ddcd5', NULL, 6, 6, 'Judah took a wife for Er, his firstborn, and her name was Tamar.'),
  ('71229c19-ff33-5d3f-a226-6071ad8404d9', '7daf3407-3437-5148-ab04-f754d50ddcd5', NULL, 7, 7, 'Er, Judah''s firstborn, was wicked in the sight of Yahweh. Yahweh killed him.'),
  ('bfb9d755-9010-5771-a70f-a433efb78f45', '7daf3407-3437-5148-ab04-f754d50ddcd5', NULL, 8, 8, 'Judah said to Onan, "Go in to your brother''s wife, and perform the duty of a husband''s brother to her, and raise up seed to your brother."'),
  ('c0bb7653-07eb-5c52-adfe-a42ca8f5c074', '7daf3407-3437-5148-ab04-f754d50ddcd5', NULL, 9, 9, 'Onan knew that the seed wouldn''t be his; and it happened, when he went in to his brother''s wife, that he spilled it on the ground, lest he should give seed to his brother.'),
  ('a22cc6d1-942e-5c56-a73d-eb1a164c5ea4', '7daf3407-3437-5148-ab04-f754d50ddcd5', NULL, 10, 10, 'The thing which he did was evil in the sight of Yahweh, and he killed him also.'),
  ('10dcd477-cbac-531d-ab80-889ed7ec9a80', '7daf3407-3437-5148-ab04-f754d50ddcd5', NULL, 11, 11, 'Then Judah said to Tamar, his daughter-in-law, "Remain a widow in your father''s house, until Shelah, my son, is grown up;" for he said, "Lest he also die, like his brothers." Tamar went and lived in her father''s house.'),
  ('cf417e2c-b9b2-52b3-a8fb-c223d35d036b', '7daf3407-3437-5148-ab04-f754d50ddcd5', NULL, 12, 12, 'After many days, Shua''s daughter, the wife of Judah, died. Judah was comforted, and went up to his sheepshearers to Timnah, he and his friend Hirah, the Adullamite.'),
  ('9304fb17-8902-5e6b-aeca-9f4c9f3b2102', '7daf3407-3437-5148-ab04-f754d50ddcd5', NULL, 13, 13, 'It was told Tamar, saying, "Behold, your father-in-law is going up to Timnah to shear his sheep."'),
  ('5e9e9857-4dd0-55d5-a7a9-d554b5f7e14a', '7daf3407-3437-5148-ab04-f754d50ddcd5', NULL, 14, 14, 'She took off of her the garments of her widowhood, and covered herself with her veil, and wrapped herself, and sat in the gate of Enaim, which is by the way to Timnah; for she saw that Shelah was grown up, and she wasn''t given to him as a wife.'),
  ('b3821b69-7ce8-5e5a-a1d4-efd149b35948', '7daf3407-3437-5148-ab04-f754d50ddcd5', NULL, 15, 15, 'When Judah saw her, he thought that she was a prostitute, for she had covered her face.'),
  ('8f36fd60-699c-5cd9-a9cc-31418c60dd3c', '7daf3407-3437-5148-ab04-f754d50ddcd5', NULL, 16, 16, 'He turned to her by the way, and said, "Please come, let me come in to you," for he didn''t know that she was his daughter-in-law. She said, "What will you give me, that you may come in to me?"'),
  ('ed0e20a6-5ec6-5b56-a365-8ef8d0aa580b', '7daf3407-3437-5148-ab04-f754d50ddcd5', NULL, 17, 17, 'He said, "I will send you a young goat from the flock." She said, "Will you give me a pledge, until you send it?"'),
  ('cd4cd4d7-018c-5a76-a78c-c0a938962a67', '7daf3407-3437-5148-ab04-f754d50ddcd5', NULL, 18, 18, 'He said, "What pledge will I give you?" She said, "Your signet and your cord, and your staff that is in your hand." He gave them to her, and came in to her, and she conceived by him.'),
  ('379eb770-0e42-5bda-abae-255949257fe6', '7daf3407-3437-5148-ab04-f754d50ddcd5', NULL, 19, 19, 'She arose, and went away, and put off her veil from her, and put on the garments of her widowhood.'),
  ('4166ed3c-09f4-5e0e-acd7-576fe806c5fb', '7daf3407-3437-5148-ab04-f754d50ddcd5', NULL, 20, 20, 'Judah sent the young goat by the hand of his friend, the Adullamite, to receive the pledge from the woman''s hand, but he didn''t find her.'),
  ('07533687-0227-5dbc-a777-6ce0851f91b7', '7daf3407-3437-5148-ab04-f754d50ddcd5', NULL, 21, 21, 'Then he asked the men of her place, saying, "Where is the prostitute, that was at Enaim by the road?" They said, "There has been no prostitute here."'),
  ('109940f7-02a1-56dd-abe4-d84a358df947', '7daf3407-3437-5148-ab04-f754d50ddcd5', NULL, 22, 22, 'He returned to Judah, and said, "I haven''t found her; and also the men of the place said, ''There has been no prostitute here.''"'),
  ('cbc6cc49-a6dd-576c-a266-ca22205857cd', '7daf3407-3437-5148-ab04-f754d50ddcd5', NULL, 23, 23, 'Judah said, "Let her keep it, lest we be shamed. Behold, I sent this young goat, and you haven''t found her."'),
  ('c310ccaf-82d9-577a-a048-50cdb426e714', '7daf3407-3437-5148-ab04-f754d50ddcd5', NULL, 24, 24, 'It happened about three months later, that it was told Judah, saying, "Tamar, your daughter-in-law, has played the prostitute; and moreover, behold, she is with child by prostitution." Judah said, "Bring her forth, and let her be burnt."'),
  ('52d5d2e5-9baf-5368-abad-1179779918cf', '7daf3407-3437-5148-ab04-f754d50ddcd5', NULL, 25, 25, 'When she was brought forth, she sent to her father-in-law, saying, "By the man, whose these are, I am with child." She also said, "Please discern whose are these--the signet, and the cords, and the staff."'),
  ('5e05af4d-a892-5d80-aa73-03a6ed0c764f', '7daf3407-3437-5148-ab04-f754d50ddcd5', NULL, 26, 26, 'Judah acknowledged them, and said, "She is more righteous than I, because I didn''t give her to Shelah, my son." He knew her again no more.'),
  ('3edd6d86-e67d-5eb4-acb2-5eef20c8a50e', '7daf3407-3437-5148-ab04-f754d50ddcd5', NULL, 27, 27, 'It happened in the time of her travail, that behold, twins were in her womb.'),
  ('d49dc742-f696-59ca-a584-70b08b906a58', '7daf3407-3437-5148-ab04-f754d50ddcd5', NULL, 28, 28, 'When she travailed, one put out a hand, and the midwife took and tied a scarlet thread on his hand, saying, "This came out first."'),
  ('56825d7b-d4d3-5327-aac5-59e63920d9d6', '7daf3407-3437-5148-ab04-f754d50ddcd5', NULL, 29, 29, 'It happened, as he drew back his hand, that behold, his brother came out, and she said, "Why have you made a breach for yourself?" Therefore his name was called Perez.'),
  ('a816f7e1-85da-5d22-aaf5-a089580ad8aa', '7daf3407-3437-5148-ab04-f754d50ddcd5', NULL, 30, 30, 'Afterward his brother came out, that had the scarlet thread on his hand, and his name was called Zerah.'),
  ('9910f24d-d54f-5d36-a46b-d219a7595e24', '3a4f2b3a-ef92-50b2-a62f-e2833fc9d365', NULL, 1, 1, 'Joseph was brought down to Egypt. Potiphar, an officer of Pharaoh''s, the captain of the guard, an Egyptian, bought him from the hand of the Ishmaelites that had brought him down there.'),
  ('49cb29f3-17e0-5f17-a167-388609c8c434', '3a4f2b3a-ef92-50b2-a62f-e2833fc9d365', NULL, 2, 2, 'Yahweh was with Joseph, and he was a prosperous man. He was in the house of his master the Egyptian.'),
  ('b918087b-ec3a-5cef-ad6e-af22ecc86180', '3a4f2b3a-ef92-50b2-a62f-e2833fc9d365', NULL, 3, 3, 'His master saw that Yahweh was with him, and that Yahweh made all that he did prosper in his hand.'),
  ('718d6359-9435-5170-a8b5-78da0ee9e526', '3a4f2b3a-ef92-50b2-a62f-e2833fc9d365', NULL, 4, 4, 'Joseph found favor in his sight. He ministered to him, and he made him overseer over his house, and all that he had he put into his hand.'),
  ('d88c8987-4532-5cc9-a7ff-262b44ad8809', '3a4f2b3a-ef92-50b2-a62f-e2833fc9d365', NULL, 5, 5, 'It happened from the time that he made him overseer in his house, and over all that he had, that Yahweh blessed the Egyptian''s house for Joseph''s sake; and the blessing of Yahweh was on all that he had, in the house and in the field.'),
  ('43821475-a5ad-5a5d-a338-74372c9cd24b', '3a4f2b3a-ef92-50b2-a62f-e2833fc9d365', NULL, 6, 6, 'He left all that he had in Joseph''s hand. He didn''t concern himself with anything, except for the food which he ate. Joseph was well-built and handsome.'),
  ('88ffc002-099b-5aaa-a881-4cc600ce5a5e', '3a4f2b3a-ef92-50b2-a62f-e2833fc9d365', NULL, 7, 7, 'It happened after these things, that his master''s wife cast her eyes on Joseph; and she said, "Lie with me."'),
  ('3b6d2724-00ce-51f2-a197-c2d5c91144cd', '3a4f2b3a-ef92-50b2-a62f-e2833fc9d365', NULL, 8, 8, 'But he refused, and said to his master''s wife, "Behold, my master doesn''t know what is with me in the house, and he has put all that he has into my hand.'),
  ('ae2f368f-a304-55fa-ad01-c85e5b0b1869', '3a4f2b3a-ef92-50b2-a62f-e2833fc9d365', NULL, 9, 9, 'He isn''t greater in this house than I, neither has he kept back anything from me but you, because you are his wife. How then can I do this great wickedness, and sin against God?"'),
  ('05cdfe2f-ce6f-58dd-a7a8-909ce5748ffb', '3a4f2b3a-ef92-50b2-a62f-e2833fc9d365', NULL, 10, 10, 'As she spoke to Joseph day by day, he didn''t listen to her, to lie by her, or to be with her.'),
  ('4377834c-ae90-5de6-a501-83dd72b35c93', '3a4f2b3a-ef92-50b2-a62f-e2833fc9d365', NULL, 11, 11, 'About this time, he went into the house to do his work, and there were none of the men of the house inside.'),
  ('f9cfa7c8-5aac-57ba-a9c3-68e614766237', '3a4f2b3a-ef92-50b2-a62f-e2833fc9d365', NULL, 12, 12, 'She caught him by his garment, saying, "Lie with me!" He left his garment in her hand, and ran outside.'),
  ('e2be86bc-60c5-55f9-ac0a-c415c36b8366', '3a4f2b3a-ef92-50b2-a62f-e2833fc9d365', NULL, 13, 13, 'When she saw that he had left his garment in her hand, and had run outside,'),
  ('6789f51f-3df7-53ee-a1b5-17b6ae48a347', '3a4f2b3a-ef92-50b2-a62f-e2833fc9d365', NULL, 14, 14, 'she called to the men of her house, and spoke to them, saying, "Behold, he has brought in a Hebrew to us to mock us. He came in to me to lie with me, and I cried with a loud voice.'),
  ('6d837789-73a9-526a-a643-e7da1072f84d', '3a4f2b3a-ef92-50b2-a62f-e2833fc9d365', NULL, 15, 15, 'It happened, when he heard that I lifted up my voice and cried, that he left his garment by me, and ran outside."'),
  ('ad95df87-daef-5fd2-a4a3-a310e8277ceb', '3a4f2b3a-ef92-50b2-a62f-e2833fc9d365', NULL, 16, 16, 'She laid up his garment by her, until his master came home.'),
  ('642e7f89-f49e-591d-a8a1-8ce155e12f79', '3a4f2b3a-ef92-50b2-a62f-e2833fc9d365', NULL, 17, 17, 'She spoke to him according to these words, saying, "The Hebrew servant, whom you have brought to us, came in to me to mock me,'),
  ('6863753b-09f1-5d79-ab5a-6eeb43c97020', '3a4f2b3a-ef92-50b2-a62f-e2833fc9d365', NULL, 18, 18, 'and it happened, as I lifted up my voice and cried, that he left his garment by me, and ran outside."'),
  ('2b354f42-da6a-5dca-a761-2c7963c86ac5', '3a4f2b3a-ef92-50b2-a62f-e2833fc9d365', NULL, 19, 19, 'It happened, when his master heard the words of his wife, which she spoke to him, saying, "This is what your servant did to me," that his wrath was kindled.'),
  ('948038fa-7617-5291-a7b4-47e761e56576', '3a4f2b3a-ef92-50b2-a62f-e2833fc9d365', NULL, 20, 20, 'Joseph''s master took him, and put him into the prison, the place where the king''s prisoners were bound, and he was there in custody.'),
  ('6578fe00-33bd-5126-a67c-5b007a930e2e', '3a4f2b3a-ef92-50b2-a62f-e2833fc9d365', NULL, 21, 21, 'But Yahweh was with Joseph, and showed kindness to him, and gave him favor in the sight of the keeper of the prison.'),
  ('4b430072-e43e-5986-a0cb-140a415e5d5e', '3a4f2b3a-ef92-50b2-a62f-e2833fc9d365', NULL, 22, 22, 'The keeper of the prison committed to Joseph''s hand all the prisoners who were in the prison. Whatever they did there, he was responsible for it.'),
  ('fcfd1933-36b0-543a-a030-e3791b4a1395', '3a4f2b3a-ef92-50b2-a62f-e2833fc9d365', NULL, 23, 23, 'The keeper of the prison didn''t look after anything that was under his hand, because Yahweh was with him; and that which he did, Yahweh made it prosper.'),
  ('6a81a886-81db-5c28-a287-2a0673a07648', 'bf6cfda0-89d5-597b-a46a-894b5ebaed17', NULL, 1, 1, 'It happened after these things, that the butler of the king of Egypt and his baker offended their lord, the king of Egypt.'),
  ('e19e46a4-5692-5b74-aa99-fd02930d1c4c', 'bf6cfda0-89d5-597b-a46a-894b5ebaed17', NULL, 2, 2, 'Pharaoh was angry with his two officers, the chief cupbearer and the chief baker.'),
  ('9b1955ec-93d9-53e8-abf3-e032cd0cf500', 'bf6cfda0-89d5-597b-a46a-894b5ebaed17', NULL, 3, 3, 'He put them in custody in the house of the captain of the guard, into the prison, the place where Joseph was bound.'),
  ('4c047ba8-9d99-5811-a5cc-ea9cd5698e93', 'bf6cfda0-89d5-597b-a46a-894b5ebaed17', NULL, 4, 4, 'The captain of the guard assigned them to Joseph, and he took care of them. They stayed in prison many days.'),
  ('5cfb9471-3e44-5df9-a5db-9c189cf7478d', 'bf6cfda0-89d5-597b-a46a-894b5ebaed17', NULL, 5, 5, 'They both dreamed a dream, each man his dream, in one night, each man according to the interpretation of his dream, the cupbearer and the baker of the king of Egypt, who were bound in the prison.'),
  ('383a6861-47aa-54ae-a14d-aba3ad826c23', 'bf6cfda0-89d5-597b-a46a-894b5ebaed17', NULL, 6, 6, 'Joseph came in to them in the morning, and saw them, and saw that they were sad.'),
  ('5e7e442c-1f0e-5189-a137-8897afa3066c', 'bf6cfda0-89d5-597b-a46a-894b5ebaed17', NULL, 7, 7, 'He asked Pharaoh''s officers who were with him in custody in his master''s house, saying, "Why do you look so sad today?"'),
  ('21720c06-c9d1-5fa3-ac0e-75b247a34075', 'bf6cfda0-89d5-597b-a46a-894b5ebaed17', NULL, 8, 8, 'They said to him, "We have dreamed a dream, and there is no one who can interpret it." Joseph said to them, "Don''t interpretations belong to God? Please tell it to me."'),
  ('a5d55a32-81ca-5741-a453-3e4fea94b3eb', 'bf6cfda0-89d5-597b-a46a-894b5ebaed17', NULL, 9, 9, 'The chief cupbearer told his dream to Joseph, and said to him, "In my dream, behold, a vine was in front of me,'),
  ('24866474-037b-59ed-acce-c4d708376af6', 'bf6cfda0-89d5-597b-a46a-894b5ebaed17', NULL, 10, 10, 'and in the vine were three branches. It was as though it budded, its blossoms shot forth, and its clusters brought forth ripe grapes.'),
  ('c7aa4b00-8348-57c7-af09-bbbc62090b5f', 'bf6cfda0-89d5-597b-a46a-894b5ebaed17', NULL, 11, 11, 'Pharaoh''s cup was in my hand; and I took the grapes, and pressed them into Pharaoh''s cup, and I gave the cup into Pharaoh''s hand."'),
  ('8c931c3e-5da1-5e54-adc4-57fa1badc501', 'bf6cfda0-89d5-597b-a46a-894b5ebaed17', NULL, 12, 12, 'Joseph said to him, "This is its interpretation: the three branches are three days.'),
  ('b3a03c5e-47c3-51eb-afeb-9f04c0ff3606', 'bf6cfda0-89d5-597b-a46a-894b5ebaed17', NULL, 13, 13, 'Within three more days, Pharaoh will lift up your head, and restore you to your office. You will give Pharaoh''s cup into his hand, the way you did when you were his cupbearer.'),
  ('5ea6df6d-ffc0-570d-a66b-4ba662aec6ff', 'bf6cfda0-89d5-597b-a46a-894b5ebaed17', NULL, 14, 14, 'But remember me when it will be well with you, and please show kindness to me, and make mention of me to Pharaoh, and bring me out of this house.'),
  ('b39b54ed-209a-5a19-ab88-2e784f88b206', 'bf6cfda0-89d5-597b-a46a-894b5ebaed17', NULL, 15, 15, 'For indeed, I was stolen away out of the land of the Hebrews, and here also have I done nothing that they should put me into the dungeon."'),
  ('e40de4ec-316a-5521-a636-dbb4ffe5a787', 'bf6cfda0-89d5-597b-a46a-894b5ebaed17', NULL, 16, 16, 'When the chief baker saw that the interpretation was good, he said to Joseph, "I also was in my dream, and behold, three baskets of white bread were on my head.'),
  ('5bfe850e-e519-56dd-a705-fce7d775aeb6', 'bf6cfda0-89d5-597b-a46a-894b5ebaed17', NULL, 17, 17, 'In the uppermost basket there was all kinds of baked food for Pharaoh, and the birds ate them out of the basket on my head."'),
  ('9b60ea15-a9fa-599e-af60-1bce19a7b281', 'bf6cfda0-89d5-597b-a46a-894b5ebaed17', NULL, 18, 18, 'Joseph answered, "This is its interpretation. The three baskets are three days.'),
  ('93658dbc-9564-5300-ade8-7e5d62f2b469', 'bf6cfda0-89d5-597b-a46a-894b5ebaed17', NULL, 19, 19, 'Within three more days, Pharaoh will lift up your head from off you, and will hang you on a tree; and the birds will eat your flesh from off you."'),
  ('e720f964-4dbc-51a8-a519-259ec954202f', 'bf6cfda0-89d5-597b-a46a-894b5ebaed17', NULL, 20, 20, 'It happened the third day, which was Pharaoh''s birthday, that he made a feast for all his servants, and he lifted up the head of the chief cupbearer and the head of the chief baker among his servants.'),
  ('4b8a1313-ba49-5c99-a57d-c1bbd0e04080', 'bf6cfda0-89d5-597b-a46a-894b5ebaed17', NULL, 21, 21, 'He restored the chief cupbearer to his position again, and he gave the cup into Pharaoh''s hand;'),
  ('01ea2c8f-40f8-5cfd-aa0f-976b1a4b544d', 'bf6cfda0-89d5-597b-a46a-894b5ebaed17', NULL, 22, 22, 'but he hanged the chief baker, as Joseph had interpreted to them.'),
  ('c818f949-1f26-57aa-ad0d-2e8d2bcd523f', 'bf6cfda0-89d5-597b-a46a-894b5ebaed17', NULL, 23, 23, 'Yet the chief cupbearer didn''t remember Joseph, but forgot him.'),
  ('cc22e9ec-a1a5-5597-a8be-5d11c771755a', '2def259b-d184-59e7-aa85-f469f0044d9e', NULL, 1, 1, 'It happened at the end of two full years, that Pharaoh dreamed: and behold, he stood by the river.'),
  ('bdfe4b63-2aac-5480-a53b-a1d36c09f67e', '2def259b-d184-59e7-aa85-f469f0044d9e', NULL, 2, 2, 'Behold, there came up out of the river seven cattle, sleek and fat, and they fed in the marsh grass.'),
  ('233d4e42-03d1-59ea-af61-e316368e53bb', '2def259b-d184-59e7-aa85-f469f0044d9e', NULL, 3, 3, 'Behold, seven other cattle came up after them out of the river, ugly and thin, and stood by the other cattle on the brink of the river.'),
  ('25716075-b6b7-59a3-a5c5-9c2f423af4e8', '2def259b-d184-59e7-aa85-f469f0044d9e', NULL, 4, 4, 'The ugly and thin cattle ate up the seven sleek and fat cattle. So Pharaoh awoke.'),
  ('5f972710-bddb-51c5-abb5-8b0ac03dfdcd', '2def259b-d184-59e7-aa85-f469f0044d9e', NULL, 5, 5, 'He slept and dreamed a second time: and behold, seven heads of grain came up on one stalk, healthy and good.'),
  ('03d3f1e5-0c4a-53e7-a4d3-7f98a7d70b7d', '2def259b-d184-59e7-aa85-f469f0044d9e', NULL, 6, 6, 'Behold, seven heads of grain, thin and blasted with the east wind, sprung up after them.'),
  ('28daeae5-791d-5ea7-ac41-755af203c35b', '2def259b-d184-59e7-aa85-f469f0044d9e', NULL, 7, 7, 'The thin heads of grain swallowed up the seven healthy and full ears. Pharaoh awoke, and behold, it was a dream.'),
  ('cc02a462-e038-5972-a786-979644d07d12', '2def259b-d184-59e7-aa85-f469f0044d9e', NULL, 8, 8, 'It happened in the morning that his spirit was troubled, and he sent and called for all of Egypt''s magicians and wise men. Pharaoh told them his dreams, but there was no one who could interpret them to Pharaoh.'),
  ('89e4f43c-15b4-55ab-ae98-37a22053eb9c', '2def259b-d184-59e7-aa85-f469f0044d9e', NULL, 9, 9, 'Then the chief cupbearer spoke to Pharaoh, saying, "I remember my faults today.'),
  ('9ea2c3b3-5fcc-5a5a-aeb2-7942e73db24a', '2def259b-d184-59e7-aa85-f469f0044d9e', NULL, 10, 10, 'Pharaoh was angry with his servants, and put me in custody in the house of the captain of the guard, me and the chief baker.'),
  ('32181587-44da-5af9-a7c7-284912e53e77', '2def259b-d184-59e7-aa85-f469f0044d9e', NULL, 11, 11, 'We dreamed a dream in one night, I and he. We dreamed each man according to the interpretation of his dream.'),
  ('9ed11e9a-5753-5e50-a9a9-2eea0fe2246b', '2def259b-d184-59e7-aa85-f469f0044d9e', NULL, 12, 12, 'There was with us there a young man, a Hebrew, servant to the captain of the guard, and we told him, and he interpreted to us our dreams. To each man according to his dream he interpreted.'),
  ('8a1bd70c-4496-5883-a6fb-250e0f01c641', '2def259b-d184-59e7-aa85-f469f0044d9e', NULL, 13, 13, 'It happened, as he interpreted to us, so it was: he restored me to my office, and he hanged him."'),
  ('d724ebaa-0b20-5ad5-a64a-33f95588af7e', '2def259b-d184-59e7-aa85-f469f0044d9e', NULL, 14, 14, 'Then Pharaoh sent and called Joseph, and they brought him hastily out of the dungeon. He shaved himself, changed his clothing, and came in to Pharaoh.'),
  ('ea59fa53-9097-571d-ab06-f7721483a01a', '2def259b-d184-59e7-aa85-f469f0044d9e', NULL, 15, 15, 'Pharaoh said to Joseph, "I have dreamed a dream, and there is no one who can interpret it. I have heard it said of you, that when you hear a dream you can interpret it."'),
  ('922cafa5-1ee2-56e4-a600-988c3bd9d7c6', '2def259b-d184-59e7-aa85-f469f0044d9e', NULL, 16, 16, 'Joseph answered Pharaoh, saying, "It isn''t in me. God will give Pharaoh an answer of peace."'),
  ('eb276b91-2704-5230-a5de-b2258778251b', '2def259b-d184-59e7-aa85-f469f0044d9e', NULL, 17, 17, 'Pharaoh spoke to Joseph, "In my dream, behold, I stood on the brink of the river:'),
  ('e61a8e4e-60ac-57be-a994-6c2e62d244f5', '2def259b-d184-59e7-aa85-f469f0044d9e', NULL, 18, 18, 'and behold, there came up out of the river seven cattle, fat and sleek. They fed in the marsh grass,'),
  ('037545a8-eb66-5583-ad66-387b28b25aad', '2def259b-d184-59e7-aa85-f469f0044d9e', NULL, 19, 19, 'and behold, seven other cattle came up after them, poor and very ugly and thin, such as I never saw in all the land of Egypt for ugliness.'),
  ('57f21942-90fc-55ab-a26f-595aa2545066', '2def259b-d184-59e7-aa85-f469f0044d9e', NULL, 20, 20, 'The thin and ugly cattle ate up the first seven fat cattle,'),
  ('d56d8a73-2f2c-522a-ac67-c16e0dbb38ed', '2def259b-d184-59e7-aa85-f469f0044d9e', NULL, 21, 21, 'and when they had eaten them up, it couldn''t be known that they had eaten them, but they were still ugly, as at the beginning. So I awoke.'),
  ('1fb8fc82-5ed0-51d9-a269-cea6f1f83cb3', '2def259b-d184-59e7-aa85-f469f0044d9e', NULL, 22, 22, 'I saw in my dream, and behold, seven heads of grain came up on one stalk, full and good:'),
  ('c72d60a0-646d-5219-aaf5-f8c3502b590f', '2def259b-d184-59e7-aa85-f469f0044d9e', NULL, 23, 23, 'and behold, seven heads of grain, withered, thin, and blasted with the east wind, sprung up after them.'),
  ('b9e963e1-38d8-52ce-afa1-4d01f410037a', '2def259b-d184-59e7-aa85-f469f0044d9e', NULL, 24, 24, 'The thin heads of grain swallowed up the seven good heads of grain. I told it to the magicians, but there was no one who could explain it to me."'),
  ('aa585876-9573-54ee-ae82-e597bb7ce37a', '2def259b-d184-59e7-aa85-f469f0044d9e', NULL, 25, 25, 'Joseph said to Pharaoh, "The dream of Pharaoh is one. What God is about to do he has declared to Pharaoh.'),
  ('ab79af12-01b2-528c-acb5-5ade5f6a678d', '2def259b-d184-59e7-aa85-f469f0044d9e', NULL, 26, 26, 'The seven good cattle are seven years; and the seven good heads of grain are seven years. The dream is one.'),
  ('11020349-a6e2-5cbb-a216-1b33020d8b5e', '2def259b-d184-59e7-aa85-f469f0044d9e', NULL, 27, 27, 'The seven thin and ugly cattle that came up after them are seven years, and also the seven empty heads of grain blasted with the east wind; they will be seven years of famine.'),
  ('8b5fcdb1-e70d-510b-a9b9-76790b1a47e6', '2def259b-d184-59e7-aa85-f469f0044d9e', NULL, 28, 28, 'That is the thing which I spoke to Pharaoh. What God is about to do he has shown to Pharaoh.'),
  ('a000619c-9ec0-5eb3-a657-fe7dd079ce45', '2def259b-d184-59e7-aa85-f469f0044d9e', NULL, 29, 29, 'Behold, there come seven years of great plenty throughout all the land of Egypt.'),
  ('f2ce0819-6514-5826-ac57-f8af5b5c7b1f', '2def259b-d184-59e7-aa85-f469f0044d9e', NULL, 30, 30, 'There will arise after them seven years of famine, and all the plenty will be forgotten in the land of Egypt. The famine will consume the land,'),
  ('b355526c-54d3-5dee-a719-0bd4af33514f', '2def259b-d184-59e7-aa85-f469f0044d9e', NULL, 31, 31, 'and the plenty will not be known in the land by reason of that famine which follows; for it will be very grievous.'),
  ('a6f4ea99-2707-5fdf-a2af-f0c5d4564c0d', '2def259b-d184-59e7-aa85-f469f0044d9e', NULL, 32, 32, 'The dream was doubled to Pharaoh, because the thing is established by God, and God will shortly bring it to pass.'),
  ('585c1d19-0673-50ff-a7ee-3e587680a82d', '2def259b-d184-59e7-aa85-f469f0044d9e', NULL, 33, 33, '"Now therefore let Pharaoh look for a discreet and wise man, and set him over the land of Egypt.'),
  ('5a20010b-e107-5830-ad75-ebf28010e999', '2def259b-d184-59e7-aa85-f469f0044d9e', NULL, 34, 34, 'Let Pharaoh do this, and let him appoint overseers over the land, and take up the fifth part of the land of Egypt''s produce in the seven plenteous years.'),
  ('49c5aa62-c1af-5347-a2f5-cc5fc376819e', '2def259b-d184-59e7-aa85-f469f0044d9e', NULL, 35, 35, 'Let them gather all the food of these good years that come, and lay up grain under the hand of Pharaoh for food in the cities, and let them keep it.'),
  ('0d9d5fdf-906c-5cd0-a602-1fa22d4ca9cf', '2def259b-d184-59e7-aa85-f469f0044d9e', NULL, 36, 36, 'The food will be for a store to the land against the seven years of famine, which will be in the land of Egypt; that the land not perish through the famine."'),
  ('b94beb06-b86b-5f2c-abd5-bcbe7a185cf7', '2def259b-d184-59e7-aa85-f469f0044d9e', NULL, 37, 37, 'The thing was good in the eyes of Pharaoh, and in the eyes of all his servants.'),
  ('4398b322-3964-5517-a7b2-5be9dd5c2efd', '2def259b-d184-59e7-aa85-f469f0044d9e', NULL, 38, 38, 'Pharaoh said to his servants, "Can we find such a one as this, a man in whom is the Spirit of God?"'),
  ('934bbf73-ac8b-5ed3-aecb-855c65736810', '2def259b-d184-59e7-aa85-f469f0044d9e', NULL, 39, 39, 'Pharaoh said to Joseph, "Because God has shown you all of this, there is none so discreet and wise as you.'),
  ('461f9e58-e4f3-5539-aa9c-13bf867a1a03', '2def259b-d184-59e7-aa85-f469f0044d9e', NULL, 40, 40, 'You shall be over my house, and according to your word will all my people be ruled. Only in the throne I will be greater than you."'),
  ('ad949a72-1c64-5107-a325-05c0316902a7', '2def259b-d184-59e7-aa85-f469f0044d9e', NULL, 41, 41, 'Pharaoh said to Joseph, "Behold, I have set you over all the land of Egypt."'),
  ('b05f7161-0470-5a9b-a21a-324b968b7e9d', '2def259b-d184-59e7-aa85-f469f0044d9e', NULL, 42, 42, 'Pharaoh took off his signet ring from his hand, and put it on Joseph''s hand, and arrayed him in robes of fine linen, and put a gold chain about his neck,'),
  ('2499a6d3-f3d3-598f-a2e7-a1ca1817dfe0', '2def259b-d184-59e7-aa85-f469f0044d9e', NULL, 43, 43, 'and he made him to ride in the second chariot which he had. They cried before him, "Bow the knee!" He set him over all the land of Egypt.'),
  ('f4b7b60e-c5b0-58e6-a497-ddb849698193', '2def259b-d184-59e7-aa85-f469f0044d9e', NULL, 44, 44, 'Pharaoh said to Joseph, "I am Pharaoh, and without you shall no man lift up his hand or his foot in all the land of Egypt."'),
  ('ac96d2e3-f33c-553a-af84-fee427f95d82', '2def259b-d184-59e7-aa85-f469f0044d9e', NULL, 45, 45, 'Pharaoh called Joseph''s name Zaphenath-Paneah; and he gave him Asenath, the daughter of Potiphera priest of On as a wife. Joseph went out over the land of Egypt.'),
  ('3650e09e-f5a0-508e-a09a-230409f5c86a', '2def259b-d184-59e7-aa85-f469f0044d9e', NULL, 46, 46, 'Joseph was thirty years old when he stood before Pharaoh king of Egypt. Joseph went out from the presence of Pharaoh, and went throughout all the land of Egypt.'),
  ('03b79708-5839-55e9-ad9c-68e09e1ecc1d', '2def259b-d184-59e7-aa85-f469f0044d9e', NULL, 47, 47, 'In the seven plenteous years the earth brought forth abundantly.'),
  ('846c8a24-b223-55a0-a9bf-2872ad7e32ac', '2def259b-d184-59e7-aa85-f469f0044d9e', NULL, 48, 48, 'He gathered up all the food of the seven years which were in the land of Egypt, and laid up the food in the cities: the food of the field, which was around every city, he laid up in the same.'),
  ('cb43b854-1799-5ca5-af62-08822097a5d9', '2def259b-d184-59e7-aa85-f469f0044d9e', NULL, 49, 49, 'Joseph laid up grain as the sand of the sea, very much, until he stopped counting, for it was without number.'),
  ('f6134433-f851-5137-a4ac-ac2868e38576', '2def259b-d184-59e7-aa85-f469f0044d9e', NULL, 50, 50, 'To Joseph were born two sons before the year of famine came, whom Asenath, the daughter of Potiphera priest of On, bore to him.'),
  ('45a7cd5e-e223-54ca-a334-02da5b39d68c', '2def259b-d184-59e7-aa85-f469f0044d9e', NULL, 51, 51, 'Joseph called the name of the firstborn Manasseh, "For," he said, "God has made me forget all my toil, and all my father''s house."'),
  ('7bd44abb-3be4-5aeb-a8ee-ef233a1bc2e1', '2def259b-d184-59e7-aa85-f469f0044d9e', NULL, 52, 52, 'The name of the second, he called Ephraim: "For God has made me fruitful in the land of my affliction."'),
  ('5745cc05-a754-57b6-aae8-b430d0374156', '2def259b-d184-59e7-aa85-f469f0044d9e', NULL, 53, 53, 'The seven years of plenty, that were in the land of Egypt, came to an end.'),
  ('c4e65a17-31c3-58b0-aeea-d1ca403ef658', '2def259b-d184-59e7-aa85-f469f0044d9e', NULL, 54, 54, 'The seven years of famine began to come, just as Joseph had said. There was famine in all lands, but in all the land of Egypt there was bread.'),
  ('0c77fc5c-d097-58b4-a840-41f4a863f138', '2def259b-d184-59e7-aa85-f469f0044d9e', NULL, 55, 55, 'When all the land of Egypt was famished, the people cried to Pharaoh for bread, and Pharaoh said to all the Egyptians, "Go to Joseph. What he says to you, do."'),
  ('046f1e5f-b27a-567f-a53f-17fe61be2c46', '2def259b-d184-59e7-aa85-f469f0044d9e', NULL, 56, 56, 'The famine was over all the surface of the earth. Joseph opened all the store houses, and sold to the Egyptians. The famine was severe in the land of Egypt.'),
  ('b1b08fe7-d8d3-5073-a5ce-f83ae9482cfe', '2def259b-d184-59e7-aa85-f469f0044d9e', NULL, 57, 57, 'All countries came into Egypt, to Joseph, to buy grain, because the famine was severe in all the earth.'),
  ('bba0d537-13f9-5046-acfb-cf4afc7d982e', '8b424cd8-3db7-5491-a85c-feb05b6a4e38', NULL, 1, 1, 'Now Jacob saw that there was grain in Egypt, and Jacob said to his sons, "Why do you look at one another?"'),
  ('9f2daa7a-3ee2-5750-a7c2-9d99df3f73d4', '8b424cd8-3db7-5491-a85c-feb05b6a4e38', NULL, 2, 2, 'He said, "Behold, I have heard that there is grain in Egypt. Go down there, and buy for us from there, so that we may live, and not die."'),
  ('b326c09d-15d7-57b5-a5d7-a061cad9a352', '8b424cd8-3db7-5491-a85c-feb05b6a4e38', NULL, 3, 3, 'Joseph''s ten brothers went down to buy grain from Egypt.'),
  ('bf5daf0d-f5dd-5bbb-a2b3-c46b21e0a952', '8b424cd8-3db7-5491-a85c-feb05b6a4e38', NULL, 4, 4, 'But Jacob didn''t send Benjamin, Joseph''s brother, with his brothers; for he said, "Lest perhaps harm happen to him."'),
  ('aea3ae4e-91e0-5c05-af55-514c9aaadaf3', '8b424cd8-3db7-5491-a85c-feb05b6a4e38', NULL, 5, 5, 'The sons of Israel came to buy among those who came, for the famine was in the land of Canaan.'),
  ('f846b9b0-ee61-5bc8-a28e-29854bbdbcc8', '8b424cd8-3db7-5491-a85c-feb05b6a4e38', NULL, 6, 6, 'Joseph was the governor over the land. It was he who sold to all the people of the land. Joseph''s brothers came, and bowed themselves down to him with their faces to the earth.'),
  ('78344db4-abd1-5c52-a38c-30d06116386b', '8b424cd8-3db7-5491-a85c-feb05b6a4e38', NULL, 7, 7, 'Joseph saw his brothers, and he recognized them, but acted like a stranger to them, and spoke roughly with them. He said to them, "Where did you come from?" They said, "From the land of Canaan to buy food."'),
  ('b2fd8549-e511-52f1-a4d3-a1e35dbc5c5c', '8b424cd8-3db7-5491-a85c-feb05b6a4e38', NULL, 8, 8, 'Joseph recognized his brothers, but they didn''t recognize him.'),
  ('e879c3ab-ae3c-5c77-af43-0c078afab738', '8b424cd8-3db7-5491-a85c-feb05b6a4e38', NULL, 9, 9, 'Joseph remembered the dreams which he dreamed about them, and said to them, "You are spies! You have come to see the nakedness of the land."'),
  ('d306f74f-d328-529b-abe3-de2726eac73c', '8b424cd8-3db7-5491-a85c-feb05b6a4e38', NULL, 10, 10, 'They said to him, "No, my lord, but your servants have come to buy food.'),
  ('3fd2b55f-f53f-5c55-ab86-0f8f26807709', '8b424cd8-3db7-5491-a85c-feb05b6a4e38', NULL, 11, 11, 'We are all one man''s sons; we are honest men. Your servants are not spies."'),
  ('95e830df-df18-5f89-a169-69b2f3cac85d', '8b424cd8-3db7-5491-a85c-feb05b6a4e38', NULL, 12, 12, 'He said to them, "No, but you have come to see the nakedness of the land!"'),
  ('eecd53cf-bc01-5dea-a496-5e1319df1bef', '8b424cd8-3db7-5491-a85c-feb05b6a4e38', NULL, 13, 13, 'They said, "We, your servants, are twelve brothers, the sons of one man in the land of Canaan; and behold, the youngest is this day with our father, and one is no more."'),
  ('17a7e3fd-53b8-5be4-ad09-68e112c28554', '8b424cd8-3db7-5491-a85c-feb05b6a4e38', NULL, 14, 14, 'Joseph said to them, "It is like I told you, saying, ''You are spies!'''),
  ('072f7ea5-4339-5946-a3f3-cace0075dad6', '8b424cd8-3db7-5491-a85c-feb05b6a4e38', NULL, 15, 15, 'By this you shall be tested. By the life of Pharaoh, you shall not go forth from here, unless your youngest brother comes here.'),
  ('9d66d1a9-5da2-57af-ae9c-3bf42be6747f', '8b424cd8-3db7-5491-a85c-feb05b6a4e38', NULL, 16, 16, 'Send one of you, and let him get your brother, and you shall be bound, that your words may be tested, whether there is truth in you, or else by the life of Pharaoh surely you are spies."'),
  ('b0ab97ef-653a-55a2-a9a7-fe7c784b47a5', '8b424cd8-3db7-5491-a85c-feb05b6a4e38', NULL, 17, 17, 'He put them all together into custody for three days.'),
  ('76a2268d-2b92-5014-a09f-fe550e4d2ac8', '8b424cd8-3db7-5491-a85c-feb05b6a4e38', NULL, 18, 18, 'Joseph said to them the third day, "Do this, and live, for I fear God.'),
  ('f2800283-6079-5fe0-a607-8deab4169cb1', '8b424cd8-3db7-5491-a85c-feb05b6a4e38', NULL, 19, 19, 'If you are honest men, then let one of your brothers be bound in your prison; but you go, carry grain for the famine of your houses.'),
  ('1fbf0d50-deda-5e30-a9af-1e3295440314', '8b424cd8-3db7-5491-a85c-feb05b6a4e38', NULL, 20, 20, 'Bring your youngest brother to me; so will your words be verified, and you won''t die." They did so.'),
  ('656b3f94-0440-5a9a-a91e-4987348d9f4e', '8b424cd8-3db7-5491-a85c-feb05b6a4e38', NULL, 21, 21, 'They said one to another, "We are certainly guilty concerning our brother, in that we saw the distress of his soul, when he begged us, and we wouldn''t listen. Therefore this distress has come upon us."'),
  ('af74e08e-5491-5cdc-a83a-245b400a686f', '8b424cd8-3db7-5491-a85c-feb05b6a4e38', NULL, 22, 22, 'Reuben answered them, saying, "Didn''t I tell you, saying, ''Don''t sin against the child,'' and you wouldn''t listen? Therefore also, behold, his blood is required."'),
  ('d6626574-4752-52b2-a365-28895d4301d1', '8b424cd8-3db7-5491-a85c-feb05b6a4e38', NULL, 23, 23, 'They didn''t know that Joseph understood them; for there was an interpreter between them.'),
  ('34b07741-0362-5f9e-a164-402d68fdb3bf', '8b424cd8-3db7-5491-a85c-feb05b6a4e38', NULL, 24, 24, 'He turned himself away from them, and wept. Then he returned to them, and spoke to them, and took Simeon from among them, and bound him before their eyes.'),
  ('94e9240f-d36a-53cb-aad3-6713f75f83eb', '8b424cd8-3db7-5491-a85c-feb05b6a4e38', NULL, 25, 25, 'Then Joseph gave a command to fill their bags with grain, and to restore each man''s money into his sack, and to give them food for the way. So it was done to them.'),
  ('095b4cca-2f99-5cc7-a244-69055f7b45ad', '8b424cd8-3db7-5491-a85c-feb05b6a4e38', NULL, 26, 26, 'They loaded their donkeys with their grain, and departed from there.'),
  ('c9992c82-7496-5261-a03f-30c321532bfd', '8b424cd8-3db7-5491-a85c-feb05b6a4e38', NULL, 27, 27, 'As one of them opened his sack to give his donkey food in the lodging place, he saw his money. Behold, it was in the mouth of his sack.'),
  ('499f2f77-064a-52b9-af02-2e222111872e', '8b424cd8-3db7-5491-a85c-feb05b6a4e38', NULL, 28, 28, 'He said to his brothers, "My money is restored! Behold, it is in my sack!" Their hearts failed them, and they turned trembling one to another, saying, "What is this that God has done to us?"'),
  ('e9bf6aa4-9fc8-5709-ae27-faf92de62e4b', '8b424cd8-3db7-5491-a85c-feb05b6a4e38', NULL, 29, 29, 'They came to Jacob their father, to the land of Canaan, and told him all that had happened to them, saying,'),
  ('5c57232c-1b00-545c-a1db-bfdb8145e7ad', '8b424cd8-3db7-5491-a85c-feb05b6a4e38', NULL, 30, 30, '"The man, the lord of the land, spoke roughly with us, and took us for spies of the country.'),
  ('5d4399d7-d1bf-50f3-a463-d3b366e3410b', '8b424cd8-3db7-5491-a85c-feb05b6a4e38', NULL, 31, 31, 'We said to him, ''We are honest men. We are no spies.'),
  ('17d0ed5a-89c9-56d2-a73e-1ad92a3f6c49', '8b424cd8-3db7-5491-a85c-feb05b6a4e38', NULL, 32, 32, 'We are twelve brothers, sons of our father; one is no more, and the youngest is this day with our father in the land of Canaan.'''),
  ('b22ad585-f8e3-5ce8-a07f-6176a4753781', '8b424cd8-3db7-5491-a85c-feb05b6a4e38', NULL, 33, 33, 'The man, the lord of the land, said to us, ''By this I will know that you are honest men: leave one of your brothers with me, and take grain for the famine of your houses, and go your way.'),
  ('04f6a77e-ced1-50cf-a01e-a378c3fd4537', '8b424cd8-3db7-5491-a85c-feb05b6a4e38', NULL, 34, 34, 'Bring your youngest brother to me. Then I will know that you are not spies, but that you are honest men. So I will deliver your brother to you, and you shall trade in the land.''"'),
  ('8aba7c07-4331-5ea7-a768-77a2b0909237', '8b424cd8-3db7-5491-a85c-feb05b6a4e38', NULL, 35, 35, 'It happened as they emptied their sacks, that behold, each man''s bundle of money was in his sack. When they and their father saw their bundles of money, they were afraid.'),
  ('16cdbf18-dfb5-5a51-a922-de2e43029127', '8b424cd8-3db7-5491-a85c-feb05b6a4e38', NULL, 36, 36, 'Jacob, their father, said to them, "You have bereaved me of my children! Joseph is no more, Simeon is no more, and you want to take Benjamin away. All these things are against me."'),
  ('a6496689-e0fb-5acc-a47a-11cd8a0d42dd', '8b424cd8-3db7-5491-a85c-feb05b6a4e38', NULL, 37, 37, 'Reuben spoke to his father, saying, "Kill my two sons, if I don''t bring him to you. Entrust him to my care, and I will bring him to you again."'),
  ('4eff1769-7ba3-558d-a348-632b26229a40', '8b424cd8-3db7-5491-a85c-feb05b6a4e38', NULL, 38, 38, 'He said, "My son shall not go down with you; for his brother is dead, and he only is left. If harm happens to him along the way in which you go, then you will bring down my gray hairs with sorrow to Sheol."'),
  ('84af4b37-d055-5282-a018-f73a83249805', '668ef3b5-7d1d-5248-a250-30d64db78603', NULL, 1, 1, 'The famine was severe in the land.'),
  ('b38f21b9-42b9-5f99-a905-efb8fab7c553', '668ef3b5-7d1d-5248-a250-30d64db78603', NULL, 2, 2, 'It happened, when they had eaten up the grain which they had brought out of Egypt, their father said to them, "Go again, buy us a little more food."'),
  ('74787a27-0f19-5635-ad9d-eda4a1132df8', '668ef3b5-7d1d-5248-a250-30d64db78603', NULL, 3, 3, 'Judah spoke to him, saying, "The man solemnly warned us, saying, ''You shall not see my face, unless your brother is with you.'''),
  ('e7069bb1-44ad-53d2-a411-7c36ff59ab33', '668ef3b5-7d1d-5248-a250-30d64db78603', NULL, 4, 4, 'If you''ll send our brother with us, we''ll go down and buy you food,'),
  ('395b409c-ed1e-5d49-a6a1-dc5dd007b20a', '668ef3b5-7d1d-5248-a250-30d64db78603', NULL, 5, 5, 'but if you''ll not send him, we''ll not go down, for the man said to us, ''You shall not see my face, unless your brother is with you.''"'),
  ('951fb1c6-09c0-5a54-ac5f-675b4e2f4a54', '668ef3b5-7d1d-5248-a250-30d64db78603', NULL, 6, 6, 'Israel said, "Why did you treat me so badly, telling the man that you had another brother?"'),
  ('5377a4dd-5eb3-57b0-a348-64a3bc600e1f', '668ef3b5-7d1d-5248-a250-30d64db78603', NULL, 7, 7, 'They said, "The man asked directly concerning ourselves, and concerning our relatives, saying, ''Is your father still alive? Have you another brother?'' We just answered his questions. Is there any way we could know that he would say, ''Bring your brother down?''"'),
  ('01599b20-e513-5033-afb6-a5baddf78b2f', '668ef3b5-7d1d-5248-a250-30d64db78603', NULL, 8, 8, 'Judah said to Israel, his father, "Send the boy with me, and we''ll get up and go, so that we may live, and not die, both we, and you, and also our little ones.'),
  ('968fd9b5-0bee-5de1-a15f-1ef16909b7da', '668ef3b5-7d1d-5248-a250-30d64db78603', NULL, 9, 9, 'I''ll be collateral for him. From my hand will you require him. If I don''t bring him to you, and set him before you, then let me bear the blame forever,'),
  ('5232d18f-a20e-5568-ab88-a2a38a2737e1', '668ef3b5-7d1d-5248-a250-30d64db78603', NULL, 10, 10, 'for if we hadn''t delayed, surely we would have returned a second time by now."'),
  ('8b286ce6-efe7-5b85-a368-4295aac6659b', '668ef3b5-7d1d-5248-a250-30d64db78603', NULL, 11, 11, 'Their father, Israel, said to them, "If it must be so, then do this. Take from the choice fruits of the land in your bags, and carry down a present for the man, a little balm, a little honey, spices and myrrh, nuts, and almonds;'),
  ('c0d6c942-cf46-5430-a884-47955f03a40f', '668ef3b5-7d1d-5248-a250-30d64db78603', NULL, 12, 12, 'and take double money in your hand, and take back the money that was returned in the mouth of your sacks. Perhaps it was an oversight.'),
  ('4e205584-23c1-58c7-a56c-862ae5d5f99e', '668ef3b5-7d1d-5248-a250-30d64db78603', NULL, 13, 13, 'Take your brother also, get up, and return to the man.'),
  ('f0f1b5a5-bacf-5cfa-acad-87877d6f53b7', '668ef3b5-7d1d-5248-a250-30d64db78603', NULL, 14, 14, 'May God Almighty give you mercy before the man, that he may release to you your other brother and Benjamin. If I am bereaved of my children, I am bereaved."'),
  ('c7bca446-5ba8-52a2-a052-dc102e2d88f9', '668ef3b5-7d1d-5248-a250-30d64db78603', NULL, 15, 15, 'The men took that present, and they took double money in their hand, and Benjamin; and got up, went down to Egypt, and stood before Joseph.'),
  ('7a24ccd4-6368-5992-a8e7-ea7dd1ef477a', '668ef3b5-7d1d-5248-a250-30d64db78603', NULL, 16, 16, 'When Joseph saw Benjamin with them, he said to the steward of his house, "Bring the men into the house, and butcher an animal, and prepare; for the men will dine with me at noon."'),
  ('538d3af0-1408-51ad-aad8-468e69db754c', '668ef3b5-7d1d-5248-a250-30d64db78603', NULL, 17, 17, 'The man did as Joseph commanded, and the man brought the men to Joseph''s house.'),
  ('9fa9590f-deb4-5998-a5c3-de0a24a512b9', '668ef3b5-7d1d-5248-a250-30d64db78603', NULL, 18, 18, 'The men were afraid, because they were brought to Joseph''s house; and they said, "Because of the money that was returned in our sacks at the first time, we''re brought in; that he may seek occasion against us, attack us, and seize us as slaves, along with our donkeys."'),
  ('f05f5968-cfc3-5084-a4f0-94e4f385f238', '668ef3b5-7d1d-5248-a250-30d64db78603', NULL, 19, 19, 'They came near to the steward of Joseph''s house, and they spoke to him at the door of the house,'),
  ('641318c4-8a34-5e1c-ab4d-d48a6e74ee19', '668ef3b5-7d1d-5248-a250-30d64db78603', NULL, 20, 20, 'and said, "Oh, my lord, we indeed came down the first time to buy food.'),
  ('b8fb30fe-6074-5547-a8c0-bddbd565491d', '668ef3b5-7d1d-5248-a250-30d64db78603', NULL, 21, 21, 'When we came to the lodging place, we opened our sacks, and behold, each man''s money was in the mouth of his sack, our money in full weight. We have brought it back in our hand.'),
  ('670b3a60-a3da-586a-a897-810d86174d0e', '668ef3b5-7d1d-5248-a250-30d64db78603', NULL, 22, 22, 'We have brought down other money in our hand to buy food. We don''t know who put our money in our sacks."'),
  ('5116132c-ce69-5e79-af7c-7b212a692e53', '668ef3b5-7d1d-5248-a250-30d64db78603', NULL, 23, 23, 'He said, "Peace be to you. Don''t be afraid. Your God, and the God of your father, has given you treasure in your sacks. I received your money." He brought Simeon out to them.'),
  ('68888f37-8014-59d6-acde-fad18c127b54', '668ef3b5-7d1d-5248-a250-30d64db78603', NULL, 24, 24, 'The man brought the men into Joseph''s house, and gave them water, and they washed their feet. He gave their donkeys fodder.'),
  ('ab697741-e0e1-52c5-a5c1-66253298c087', '668ef3b5-7d1d-5248-a250-30d64db78603', NULL, 25, 25, 'They prepared the present for Joseph''s coming at noon, for they heard that they should eat bread there.'),
  ('03ee9227-5d96-56f7-ac1c-bbc651d307d6', '668ef3b5-7d1d-5248-a250-30d64db78603', NULL, 26, 26, 'When Joseph came home, they brought him the present which was in their hand into the house, and bowed themselves down to him to the earth.'),
  ('36434711-4029-5364-aef4-e52e5933c5c6', '668ef3b5-7d1d-5248-a250-30d64db78603', NULL, 27, 27, 'He asked them of their welfare, and said, "Is your father well, the old man of whom you spoke? Is he yet alive?"'),
  ('36933ff1-fadc-523d-a43a-8f40fa90f98e', '668ef3b5-7d1d-5248-a250-30d64db78603', NULL, 28, 28, 'They said, "Your servant, our father, is well. He is still alive." They bowed the head, and did homage.'),
  ('e26ec488-2431-5f0b-a982-261088150880', '668ef3b5-7d1d-5248-a250-30d64db78603', NULL, 29, 29, 'He lifted up his eyes, and saw Benjamin, his brother, his mother''s son, and said, "Is this your youngest brother, of whom you spoke to me?" He said, "God be gracious to you, my son."'),
  ('38f52f96-75f0-5fc5-aac7-61d28cb57f11', '668ef3b5-7d1d-5248-a250-30d64db78603', NULL, 30, 30, 'Joseph hurried, for his heart yearned over his brother; and he sought a place to weep. He entered into his room, and wept there.'),
  ('70ae95fe-bcbb-562f-a374-208bb614f765', '668ef3b5-7d1d-5248-a250-30d64db78603', NULL, 31, 31, 'He washed his face, and came out. He controlled himself, and said, "Serve the meal."'),
  ('2023b1eb-260f-596a-aab5-33542e52ba49', '668ef3b5-7d1d-5248-a250-30d64db78603', NULL, 32, 32, 'They served him by himself, and them by themselves, and the Egyptians, that ate with him, by themselves, because the Egyptians don''t eat bread with the Hebrews, for that is an abomination to the Egyptians.'),
  ('48e6725e-703d-55d8-aa36-1e97f93187e3', '668ef3b5-7d1d-5248-a250-30d64db78603', NULL, 33, 33, 'They sat before him, the firstborn according to his birthright, and the youngest according to his youth, and the men marveled one with another.'),
  ('0b209957-ff01-5326-a5f9-382c4c1dead2', '668ef3b5-7d1d-5248-a250-30d64db78603', NULL, 34, 34, 'He sent portions to them from before him, but Benjamin''s portion was five times as much as any of theirs. They drank, and were merry with him.'),
  ('d948ca10-dbeb-515f-a61e-4f19d914a6dd', '379778f2-771b-5fd0-ac7b-6395ac186a89', NULL, 1, 1, 'He commanded the steward of his house, saying, "Fill the men''s sacks with food, as much as they can carry, and put each man''s money in his sack''s mouth.'),
  ('b4c4803c-70f9-564f-a562-654713c9c56f', '379778f2-771b-5fd0-ac7b-6395ac186a89', NULL, 2, 2, 'Put my cup, the silver cup, in the sack''s mouth of the youngest, with his grain money." He did according to the word that Joseph had spoken.'),
  ('ab814eca-3a36-5c22-abaa-be57ebd9637e', '379778f2-771b-5fd0-ac7b-6395ac186a89', NULL, 3, 3, 'As soon as the morning was light, the men were sent away, they and their donkeys.'),
  ('83b2befe-5b18-58a2-a992-104fd7af5d7e', '379778f2-771b-5fd0-ac7b-6395ac186a89', NULL, 4, 4, 'When they had gone out of the city, and were not yet far off, Joseph said to his steward, "Up, follow after the men. When you overtake them, ask them, ''Why have you rewarded evil for good?'),
  ('139d516e-6b6c-5f87-a572-60b3abc64f14', '379778f2-771b-5fd0-ac7b-6395ac186a89', NULL, 5, 5, 'Isn''t this that from which my lord drinks, and by which he indeed divines? You have done evil in so doing.''"'),
  ('c7fdd7d8-9a6d-5adf-a9cd-ef679150d70e', '379778f2-771b-5fd0-ac7b-6395ac186a89', NULL, 6, 6, 'He overtook them, and he spoke these words to them.'),
  ('a11002b3-73e3-5aa0-a4c7-4968696e873d', '379778f2-771b-5fd0-ac7b-6395ac186a89', NULL, 7, 7, 'They said to him, "Why does my lord speak such words as these? Far be it from your servants that they should do such a thing!'),
  ('261d0d98-8cd9-57dc-a013-11f075ca2b08', '379778f2-771b-5fd0-ac7b-6395ac186a89', NULL, 8, 8, 'Behold, the money, which we found in our sacks'' mouths, we brought again to you out of the land of Canaan. How then should we steal silver or gold out of your lord''s house?'),
  ('1371c903-a9af-5ea4-a01f-aa1b3ea7165e', '379778f2-771b-5fd0-ac7b-6395ac186a89', NULL, 9, 9, 'With whoever of your servants it be found, let him die, and we also will be my lord''s bondservants."'),
  ('6b27ebbd-441b-5f4b-a638-af23627625ac', '379778f2-771b-5fd0-ac7b-6395ac186a89', NULL, 10, 10, 'He said, "Now also let it be according to your words: he with whom it is found will be my bondservant; and you will be blameless."'),
  ('11e134ae-d4cf-5a31-a52f-180d924f9e0e', '379778f2-771b-5fd0-ac7b-6395ac186a89', NULL, 11, 11, 'Then they hurried, and each man took his sack down to the ground, and each man opened his sack.'),
  ('da5c402e-254c-5d47-a639-e393eb24e1d0', '379778f2-771b-5fd0-ac7b-6395ac186a89', NULL, 12, 12, 'He searched, beginning with the eldest, and ending at the youngest. The cup was found in Benjamin''s sack.'),
  ('2eccc172-ab24-5f36-a95b-9541695f26fd', '379778f2-771b-5fd0-ac7b-6395ac186a89', NULL, 13, 13, 'Then they tore their clothes, and each man loaded his donkey, and returned to the city.'),
  ('9f3c86c2-67b4-5f9c-a5da-4b0944a4264e', '379778f2-771b-5fd0-ac7b-6395ac186a89', NULL, 14, 14, 'Judah and his brothers came to Joseph''s house, and he was still there. They fell on the ground before him.'),
  ('a0b43b28-954e-5a23-a053-54d82ea82965', '379778f2-771b-5fd0-ac7b-6395ac186a89', NULL, 15, 15, 'Joseph said to them, "What deed is this that you have done? Don''t you know that such a man as I can indeed divine?"'),
  ('472a8f01-e442-5bf7-a0db-0956adfd401c', '379778f2-771b-5fd0-ac7b-6395ac186a89', NULL, 16, 16, 'Judah said, "What will we tell my lord? What will we speak? Or how will we clear ourselves? God has found out the iniquity of your servants. Behold, we are my lord''s bondservants, both we, and he also in whose hand the cup is found."'),
  ('cb08de78-c238-596e-a87a-875a5b1f0660', '379778f2-771b-5fd0-ac7b-6395ac186a89', NULL, 17, 17, 'He said, "Far be it from me that I should do so. The man in whose hand the cup is found, he will be my bondservant; but as for you, go up in peace to your father."'),
  ('1fadb36d-fc66-5f19-a221-86c8237ddc5a', '379778f2-771b-5fd0-ac7b-6395ac186a89', NULL, 18, 18, 'Then Judah came near to him, and said, "Oh, my lord, please let your servant speak a word in my lord''s ears, and don''t let your anger burn against your servant; for you are even as Pharaoh.'),
  ('e3449444-be8e-5918-a3dd-a4c33f247d84', '379778f2-771b-5fd0-ac7b-6395ac186a89', NULL, 19, 19, 'My lord asked his servants, saying, ''Have you a father, or a brother?'''),
  ('a5eb94dc-248d-54fc-a7a6-36809bec1c80', '379778f2-771b-5fd0-ac7b-6395ac186a89', NULL, 20, 20, 'We said to my lord, ''We have a father, an old man, and a child of his old age, a little one; and his brother is dead, and he alone is left of his mother; and his father loves him.'''),
  ('c89fa513-47b3-59ec-ae69-f9382e093ff7', '379778f2-771b-5fd0-ac7b-6395ac186a89', NULL, 21, 21, 'You said to your servants, ''Bring him down to me, that I may set my eyes on him.'''),
  ('d52445f1-2c23-5839-add2-09f8f9bd76b5', '379778f2-771b-5fd0-ac7b-6395ac186a89', NULL, 22, 22, 'We said to my lord, ''The boy can''t leave his father: for if he should leave his father, his father would die.'''),
  ('941a3176-02c8-5b7f-a877-a65d62f033a5', '379778f2-771b-5fd0-ac7b-6395ac186a89', NULL, 23, 23, 'You said to your servants, ''Unless your youngest brother comes down with you, you will see my face no more.'''),
  ('e63fd0a4-753c-5442-ac45-eb144e2b9494', '379778f2-771b-5fd0-ac7b-6395ac186a89', NULL, 24, 24, 'It happened when we came up to your servant my father, we told him the words of my lord.'),
  ('0e5b5560-dcde-5b52-aa2f-96893c61c180', '379778f2-771b-5fd0-ac7b-6395ac186a89', NULL, 25, 25, 'Our father said, ''Go again, buy us a little food.'''),
  ('b493d5b1-3688-58e9-aab7-55361e88552a', '379778f2-771b-5fd0-ac7b-6395ac186a89', NULL, 26, 26, 'We said, ''We can''t go down. If our youngest brother is with us, then we will go down: for we may not see the man''s face, unless our youngest brother is with us.'''),
  ('be1efebb-1550-5e95-af15-aadc9fcfc3bf', '379778f2-771b-5fd0-ac7b-6395ac186a89', NULL, 27, 27, 'Your servant, my father, said to us, ''You know that my wife bore me two sons:'),
  ('50ce1906-32ad-52b2-a7c4-bcf6c9c19571', '379778f2-771b-5fd0-ac7b-6395ac186a89', NULL, 28, 28, 'and the one went out from me, and I said, "Surely he is torn in pieces;" and I haven''t seen him since.'),
  ('a6ff82ad-2063-53bc-aa84-3c5acffab76b', '379778f2-771b-5fd0-ac7b-6395ac186a89', NULL, 29, 29, 'If you take this one also from me, and harm happens to him, you will bring down my gray hairs with sorrow to Sheol.'''),
  ('f9928092-ea17-58d8-ae87-d1aff14f4653', '379778f2-771b-5fd0-ac7b-6395ac186a89', NULL, 30, 30, 'Now therefore when I come to your servant my father, and the boy is not with us; since his life is bound up in the boy''s life;'),
  ('892d2cfb-c454-5b12-ac3a-20786dab3fc3', '379778f2-771b-5fd0-ac7b-6395ac186a89', NULL, 31, 31, 'it will happen, when he sees that the boy is no more, that he will die. Your servants will bring down the gray hairs of your servant, our father, with sorrow to Sheol.'),
  ('8cae5246-a992-5304-a1b4-0e7ae7c9f20f', '379778f2-771b-5fd0-ac7b-6395ac186a89', NULL, 32, 32, 'For your servant became collateral for the boy to my father, saying, ''If I don''t bring him to you, then I will bear the blame to my father forever.'''),
  ('4ab67468-ad78-5002-a4a2-6c64f54f5a40', '379778f2-771b-5fd0-ac7b-6395ac186a89', NULL, 33, 33, 'Now therefore, please let your servant stay instead of the boy, a bondservant to my lord; and let the boy go up with his brothers.'),
  ('eb87ae95-f136-5484-a994-a6de24e8235b', '379778f2-771b-5fd0-ac7b-6395ac186a89', NULL, 34, 34, 'For how will I go up to my father, if the boy isn''t with me?--lest I see the evil that will come on my father."'),
  ('12c2fee7-531b-55b9-a4c3-7ac6d69decc2', 'b0696a24-b231-5d94-a9b4-57e9bf58cd67', NULL, 1, 1, 'Then Joseph couldn''t control himself before all those who stood before him, and he cried, "Cause everyone to go out from me!" No one else stood with him, while Joseph made himself known to his brothers.'),
  ('c9bce6a1-fd9b-5d6e-a518-d8a80e394719', 'b0696a24-b231-5d94-a9b4-57e9bf58cd67', NULL, 2, 2, 'He wept aloud. The Egyptians heard, and the house of Pharaoh heard.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('b81576f5-edfc-5a02-a358-73d17755635b', 'b0696a24-b231-5d94-a9b4-57e9bf58cd67', NULL, 3, 3, 'Joseph said to his brothers, "I am Joseph! Does my father still live?" His brothers couldn''t answer him; for they were terrified at his presence.'),
  ('41a0de28-2b43-5391-ac2c-184819bcf7b6', 'b0696a24-b231-5d94-a9b4-57e9bf58cd67', NULL, 4, 4, 'Joseph said to his brothers, "Come near to me, please." They came near. "He said, I am Joseph, your brother, whom you sold into Egypt.'),
  ('6c33b4ed-4fff-5162-ad57-cdeac6de60a1', 'b0696a24-b231-5d94-a9b4-57e9bf58cd67', NULL, 5, 5, 'Now don''t be grieved, nor angry with yourselves, that you sold me here, for God sent me before you to preserve life.'),
  ('98ef4852-cb42-5f50-a35a-6d63f206ccdd', 'b0696a24-b231-5d94-a9b4-57e9bf58cd67', NULL, 6, 6, 'For these two years the famine has been in the land, and there are yet five years, in which there will be neither plowing nor harvest.'),
  ('2694a306-2c5b-5fa6-a064-200c6930fa42', 'b0696a24-b231-5d94-a9b4-57e9bf58cd67', NULL, 7, 7, 'God sent me before you to preserve for you a remnant in the earth, and to save you alive by a great deliverance.'),
  ('b1c947de-e45d-512c-af36-fdeb49088caf', 'b0696a24-b231-5d94-a9b4-57e9bf58cd67', NULL, 8, 8, 'So now it wasn''t you who sent me here, but God, and he has made me a father to Pharaoh, lord of all his house, and ruler over all the land of Egypt.'),
  ('4406f894-d512-5e3e-aa3e-16fef9370e37', 'b0696a24-b231-5d94-a9b4-57e9bf58cd67', NULL, 9, 9, 'Hurry, and go up to my father, and tell him, ''This is what your son Joseph says, "God has made me lord of all Egypt. Come down to me. Don''t wait.'),
  ('cde56414-c28e-5ca2-a7b7-6bdaae4c35d1', 'b0696a24-b231-5d94-a9b4-57e9bf58cd67', NULL, 10, 10, 'You shall dwell in the land of Goshen, and you will be near to me, you, your children, your children''s children, your flocks, your herds, and all that you have.'),
  ('4c13c982-c986-5a01-ab9b-b13661090bbc', 'b0696a24-b231-5d94-a9b4-57e9bf58cd67', NULL, 11, 11, 'There I will nourish you; for there are yet five years of famine; lest you come to poverty, you, and your household, and all that you have."'''),
  ('9dd4c75e-94dc-5180-a821-8daeabfa60ab', 'b0696a24-b231-5d94-a9b4-57e9bf58cd67', NULL, 12, 12, 'Behold, your eyes see, and the eyes of my brother Benjamin, that it is my mouth that speaks to you.'),
  ('19b42db7-9c36-5bee-ad1d-ac362c90b4d6', 'b0696a24-b231-5d94-a9b4-57e9bf58cd67', NULL, 13, 13, 'You shall tell my father of all my glory in Egypt, and of all that you have seen. You shall hurry and bring my father down here."'),
  ('6cfcb82b-80a2-56fe-a1df-5e595b80afee', 'b0696a24-b231-5d94-a9b4-57e9bf58cd67', NULL, 14, 14, 'He fell on his brother Benjamin''s neck, and wept, and Benjamin wept on his neck.'),
  ('1f006b92-780e-5683-a7d8-868eb2cd013a', 'b0696a24-b231-5d94-a9b4-57e9bf58cd67', NULL, 15, 15, 'He kissed all his brothers, and wept on them. After that his brothers talked with him.'),
  ('ea84dfad-b143-57c0-af4b-1fa80eb3fc8f', 'b0696a24-b231-5d94-a9b4-57e9bf58cd67', NULL, 16, 16, 'The report of it was heard in Pharaoh''s house, saying, "Joseph''s brothers have come." It pleased Pharaoh well, and his servants.'),
  ('ab587a2f-84c7-5663-a660-5108b1a82421', 'b0696a24-b231-5d94-a9b4-57e9bf58cd67', NULL, 17, 17, 'Pharaoh said to Joseph, "Tell your brothers, ''Do this. Load your animals, and go, travel to the land of Canaan.'),
  ('54ab1726-8eda-573d-a8e0-f0e0d0cbd880', 'b0696a24-b231-5d94-a9b4-57e9bf58cd67', NULL, 18, 18, 'Take your father and your households, and come to me, and I will give you the good of the land of Egypt, and you will eat the fat of the land.'''),
  ('381d1a79-c2b2-5602-ab7e-c9ea3717a2ee', 'b0696a24-b231-5d94-a9b4-57e9bf58cd67', NULL, 19, 19, 'Now you are commanded: do this. Take wagons out of the land of Egypt for your little ones, and for your wives, and bring your father, and come.'),
  ('7964ef28-4983-5e62-a61b-1ae7277562ca', 'b0696a24-b231-5d94-a9b4-57e9bf58cd67', NULL, 20, 20, 'Also, don''t concern yourselves about your belongings, for the good of all of the land of Egypt is yours."'),
  ('5115cb1b-0693-56ff-a432-3361e311bb5e', 'b0696a24-b231-5d94-a9b4-57e9bf58cd67', NULL, 21, 21, 'The sons of Israel did so. Joseph gave them wagons, according to the commandment of Pharaoh, and gave them provision for the way.'),
  ('653072e9-2a6e-5351-a026-1eec88dd196c', 'b0696a24-b231-5d94-a9b4-57e9bf58cd67', NULL, 22, 22, 'He gave each one of them changes of clothing, but to Benjamin he gave three hundred pieces of silver and five changes of clothing.'),
  ('cd3efdd1-7007-52be-adcd-306f804d592a', 'b0696a24-b231-5d94-a9b4-57e9bf58cd67', NULL, 23, 23, 'He sent the following to his father: ten donkeys loaded with the good things of Egypt, and ten female donkeys loaded with grain and bread and provision for his father by the way.'),
  ('d8a39333-7eb8-5ccf-af01-60dc8d735235', 'b0696a24-b231-5d94-a9b4-57e9bf58cd67', NULL, 24, 24, 'So he sent his brothers away, and they departed. He said to them, "See that you don''t quarrel on the way."'),
  ('da6507e8-47c2-5cec-a491-2179a185d52c', 'b0696a24-b231-5d94-a9b4-57e9bf58cd67', NULL, 25, 25, 'They went up out of Egypt, and came into the land of Canaan, to Jacob their father.'),
  ('3afaec2b-1b44-5c53-a19a-822d1846b59f', 'b0696a24-b231-5d94-a9b4-57e9bf58cd67', NULL, 26, 26, 'They told him, saying, "Joseph is still alive, and he is ruler over all the land of Egypt." His heart fainted, for he didn''t believe them.'),
  ('f8d853ad-237c-58f1-ad0a-d72ce47de35a', 'b0696a24-b231-5d94-a9b4-57e9bf58cd67', NULL, 27, 27, 'They told him all the words of Joseph, which he had said to them. When he saw the wagons which Joseph had sent to carry him, the spirit of Jacob, their father, revived.'),
  ('2bd4835a-603a-539b-a5e7-9c8f200021f8', 'b0696a24-b231-5d94-a9b4-57e9bf58cd67', NULL, 28, 28, 'Israel said, "It is enough. Joseph my son is still alive. I will go and see him before I die."'),
  ('dfb63567-3666-5f6b-a589-7870746b6926', '9e87616e-89c6-5fbf-ad5f-9e23e0f8bf61', NULL, 1, 1, 'Israel traveled with all that he had, and came to Beersheba, and offered sacrifices to the God of his father, Isaac.'),
  ('fed364f9-006d-5ce2-a271-03b5964e5c8e', '9e87616e-89c6-5fbf-ad5f-9e23e0f8bf61', NULL, 2, 2, 'God spoke to Israel in the visions of the night, and said, "Jacob, Jacob!" He said, "Here I am."'),
  ('5073cab0-b2d0-57c2-ac9f-8c955f2df486', '9e87616e-89c6-5fbf-ad5f-9e23e0f8bf61', NULL, 3, 3, 'He said, "I am God, the God of your father. Don''t be afraid to go down into Egypt, for there I will make of you a great nation.'),
  ('a6ac49e9-4155-5278-aca8-d3219363f72d', '9e87616e-89c6-5fbf-ad5f-9e23e0f8bf61', NULL, 4, 4, 'I will go down with you into Egypt. I will also surely bring you up again. Joseph will close your eyes."'),
  ('d25a06e3-813f-5463-a4ea-326be997a01b', '9e87616e-89c6-5fbf-ad5f-9e23e0f8bf61', NULL, 5, 5, 'Jacob rose up from Beersheba, and the sons of Israel carried Jacob, their father, their little ones, and their wives, in the wagons which Pharaoh had sent to carry him.'),
  ('d6e29e2f-8d41-5c6f-a5ea-4cf9f9e770f6', '9e87616e-89c6-5fbf-ad5f-9e23e0f8bf61', NULL, 6, 6, 'They took their livestock, and their goods, which they had gotten in the land of Canaan, and came into Egypt--Jacob, and all his seed with him,'),
  ('9a2fec79-f7dc-5e1f-a71d-647c4967801a', '9e87616e-89c6-5fbf-ad5f-9e23e0f8bf61', NULL, 7, 7, 'his sons, and his sons'' sons with him, his daughters, and his sons'' daughters, and he brought all his seed with him into Egypt.'),
  ('40169e7c-5f24-5d74-a333-4563ae5e781f', '9e87616e-89c6-5fbf-ad5f-9e23e0f8bf61', NULL, 8, 8, 'These are the names of the children of Israel, who came into Egypt, Jacob and his sons: Reuben, Jacob''s firstborn.'),
  ('25462bd0-2cc0-5eff-aea1-080b9d2b16ec', '9e87616e-89c6-5fbf-ad5f-9e23e0f8bf61', NULL, 9, 9, 'The sons of Reuben: Hanoch, Pallu, Hezron, and Carmi.'),
  ('71b114ae-a28e-5b7c-a034-129dbf17fbd5', '9e87616e-89c6-5fbf-ad5f-9e23e0f8bf61', NULL, 10, 10, 'The sons of Simeon: Jemuel, Jamin, Ohad, Jachin, Zohar, and Shaul the son of a Canaanite woman.'),
  ('c968649d-cd1e-5f18-a1bd-ca791da0de18', '9e87616e-89c6-5fbf-ad5f-9e23e0f8bf61', NULL, 11, 11, 'The sons of Levi: Gershon, Kohath, and Merari.'),
  ('853336a9-1289-5990-a733-1881d4f72f9d', '9e87616e-89c6-5fbf-ad5f-9e23e0f8bf61', NULL, 12, 12, 'The sons of Judah: Er, Onan, Shelah, Perez, and Zerah; but Er and Onan died in the land of Canaan. The sons of Perez were Hezron and Hamul.'),
  ('cc75b6fa-9994-5dc2-a966-827065b23dac', '9e87616e-89c6-5fbf-ad5f-9e23e0f8bf61', NULL, 13, 13, 'The sons of Issachar: Tola, Puvah, Iob, and Shimron.'),
  ('e0ce7fb2-c97a-5530-a879-2166aedd3c47', '9e87616e-89c6-5fbf-ad5f-9e23e0f8bf61', NULL, 14, 14, 'The sons of Zebulun: Sered, Elon, and Jahleel.'),
  ('57126ff6-9303-5759-a318-d4a9b181b99c', '9e87616e-89c6-5fbf-ad5f-9e23e0f8bf61', NULL, 15, 15, 'These are the sons of Leah, whom she bore to Jacob in Paddan Aram, with his daughter Dinah. All the souls of his sons and his daughters were thirty-three.'),
  ('49d15aec-895d-5283-a617-3f45de569e4f', '9e87616e-89c6-5fbf-ad5f-9e23e0f8bf61', NULL, 16, 16, 'The sons of Gad: Ziphion, Haggi, Shuni, Ezbon, Eri, Arodi, and Areli.'),
  ('24c098a0-acfb-51d6-a1c3-c153de172679', '9e87616e-89c6-5fbf-ad5f-9e23e0f8bf61', NULL, 17, 17, 'The sons of Asher: Imnah, Ishvah, Ishvi, Beriah, and Serah their sister. The sons of Beriah: Heber and Malchiel.'),
  ('271a6acf-23c3-5386-a37e-389770c8df20', '9e87616e-89c6-5fbf-ad5f-9e23e0f8bf61', NULL, 18, 18, 'These are the sons of Zilpah, whom Laban gave to Leah, his daughter, and these she bore to Jacob, even sixteen souls.'),
  ('d2dffd93-f460-5eaa-a7cf-01e6cfb3d129', '9e87616e-89c6-5fbf-ad5f-9e23e0f8bf61', NULL, 19, 19, 'The sons of Rachel, Jacob''s wife: Joseph and Benjamin.'),
  ('2465a0f6-71ae-58fb-a747-dbda9987ecf8', '9e87616e-89c6-5fbf-ad5f-9e23e0f8bf61', NULL, 20, 20, 'To Joseph in the land of Egypt were born Manasseh and Ephraim, whom Asenath, the daughter of Potiphera, priest of On, bore to him.'),
  ('cc5ecd5c-722c-54b4-a948-08b9471ea4fe', '9e87616e-89c6-5fbf-ad5f-9e23e0f8bf61', NULL, 21, 21, 'The sons of Benjamin: Bela, Becher, Ashbel, Gera, Naaman, Ehi, Rosh, Muppim, Huppim, and Ard.'),
  ('5f2a1fc9-a15e-5cfd-acaa-5c8fe79565a2', '9e87616e-89c6-5fbf-ad5f-9e23e0f8bf61', NULL, 22, 22, 'These are the sons of Rachel, who were born to Jacob: all the souls were fourteen.'),
  ('60a0f86d-91aa-5ac6-a3f3-9b9ce1affdd6', '9e87616e-89c6-5fbf-ad5f-9e23e0f8bf61', NULL, 23, 23, 'The son of Dan: Hushim.'),
  ('71e555fd-1852-5407-aa75-0092449e7858', '9e87616e-89c6-5fbf-ad5f-9e23e0f8bf61', NULL, 24, 24, 'The sons of Naphtali: Jahzeel, Guni, Jezer, and Shillem.'),
  ('1cf5a59d-8376-53db-ae0b-7bb938610f13', '9e87616e-89c6-5fbf-ad5f-9e23e0f8bf61', NULL, 25, 25, 'These are the sons of Bilhah, whom Laban gave to Rachel, his daughter, and these she bore to Jacob: all the souls were seven.'),
  ('d852fb23-7e29-57cd-ac50-36a960f611fe', '9e87616e-89c6-5fbf-ad5f-9e23e0f8bf61', NULL, 26, 26, 'All the souls who came with Jacob into Egypt, who were his direct descendants, besides Jacob''s sons'' wives, all the souls were sixty-six.'),
  ('22ebc070-dda4-5e68-a4fb-1365d22ee4cb', '9e87616e-89c6-5fbf-ad5f-9e23e0f8bf61', NULL, 27, 27, 'The sons of Joseph, who were born to him in Egypt, were two souls. All the souls of the house of Jacob, who came into Egypt, were seventy.'),
  ('e9543fbf-52c7-583e-a847-45b1aa631312', '9e87616e-89c6-5fbf-ad5f-9e23e0f8bf61', NULL, 28, 28, 'He sent Judah before him to Joseph, to show the way before him to Goshen, and they came into the land of Goshen.'),
  ('1ea3be48-0d5d-55a4-a73e-9e9cd098a1cc', '9e87616e-89c6-5fbf-ad5f-9e23e0f8bf61', NULL, 29, 29, 'Joseph prepared his chariot, and went up to meet Israel, his father, in Goshen. He presented himself to him, and fell on his neck, and wept on his neck a good while.'),
  ('3e668f64-7103-5c18-a42a-913362301fa8', '9e87616e-89c6-5fbf-ad5f-9e23e0f8bf61', NULL, 30, 30, 'Israel said to Joseph, "Now let me die, since I have seen your face, that you are still alive."'),
  ('cc34420c-19ca-5973-a385-7668e4696850', '9e87616e-89c6-5fbf-ad5f-9e23e0f8bf61', NULL, 31, 31, 'Joseph said to his brothers, and to his father''s house, "I will go up, and speak with Pharaoh, and will tell him, ''My brothers, and my father''s house, who were in the land of Canaan, have come to me.'),
  ('9af76e85-039d-5617-a681-697083356ead', '9e87616e-89c6-5fbf-ad5f-9e23e0f8bf61', NULL, 32, 32, 'These men are shepherds, for they have been keepers of livestock, and they have brought their flocks, and their herds, and all that they have.'''),
  ('aacc1394-ee2e-5b0d-a444-c4b70f7bce0a', '9e87616e-89c6-5fbf-ad5f-9e23e0f8bf61', NULL, 33, 33, 'It will happen, when Pharaoh summons you, and will say, ''What is your occupation?'''),
  ('d744fb7f-5094-511c-a0b8-a8518e528d05', '9e87616e-89c6-5fbf-ad5f-9e23e0f8bf61', NULL, 34, 34, 'that you shall say, ''Your servants have been keepers of livestock from our youth even until now, both we, and our fathers:'' that you may dwell in the land of Goshen; for every shepherd is an abomination to the Egyptians."'),
  ('33cf5168-8943-52db-ab4b-4fee6a2ef9d3', 'eaf2268a-ac06-5dcc-ae02-2cb5d6f619e0', NULL, 1, 1, 'Then Joseph went in and told Pharaoh, and said, "My father and my brothers, with their flocks, their herds, and all that they own, have come out of the land of Canaan; and behold, they are in the land of Goshen."'),
  ('11c4d960-d482-5685-af2d-61f6a1fa5e62', 'eaf2268a-ac06-5dcc-ae02-2cb5d6f619e0', NULL, 2, 2, 'From among his brothers he took five men, and presented them to Pharaoh.'),
  ('56b2e4ca-586e-5994-a07f-166a4bcd0e97', 'eaf2268a-ac06-5dcc-ae02-2cb5d6f619e0', NULL, 3, 3, 'Pharaoh said to his brothers, "What is your occupation?" They said to Pharaoh, "Your servants are shepherds, both we, and our fathers."'),
  ('6324b8f1-565c-5bc7-a21d-bcae64b085c7', 'eaf2268a-ac06-5dcc-ae02-2cb5d6f619e0', NULL, 4, 4, 'They said to Pharaoh, "We have come to live as foreigners in the land, for there is no pasture for your servants'' flocks. For the famine is severe in the land of Canaan. Now therefore, please let your servants dwell in the land of Goshen."'),
  ('b800f237-7ff9-5853-ad83-75e71c057e3c', 'eaf2268a-ac06-5dcc-ae02-2cb5d6f619e0', NULL, 5, 5, 'Pharaoh spoke to Joseph, saying, "Your father and your brothers have come to you.'),
  ('e8e3afc0-1462-5e73-aae9-969772555524', 'eaf2268a-ac06-5dcc-ae02-2cb5d6f619e0', NULL, 6, 6, 'The land of Egypt is before you. Make your father and your brothers dwell in the best of the land. Let them dwell in the land of Goshen. If you know any able men among them, then put them in charge of my livestock."'),
  ('7139e79a-e7fd-5efd-a2bc-e6eceb81ebca', 'eaf2268a-ac06-5dcc-ae02-2cb5d6f619e0', NULL, 7, 7, 'Joseph brought in Jacob, his father, and set him before Pharaoh, and Jacob blessed Pharaoh.'),
  ('51b87ddf-51b5-5bff-ab6b-5534435ea54e', 'eaf2268a-ac06-5dcc-ae02-2cb5d6f619e0', NULL, 8, 8, 'Pharaoh said to Jacob, "How many are the days of the years of your life?"'),
  ('412abdc3-b74f-59ed-aa15-b43d0f6811df', 'eaf2268a-ac06-5dcc-ae02-2cb5d6f619e0', NULL, 9, 9, 'Jacob said to Pharaoh, "The days of the years of my pilgrimage are one hundred thirty years. Few and evil have been the days of the years of my life, and they have not attained to the days of the years of the life of my fathers in the days of their pilgrimage."'),
  ('0ff1f735-b01e-507f-af7c-b97b045ab00d', 'eaf2268a-ac06-5dcc-ae02-2cb5d6f619e0', NULL, 10, 10, 'Jacob blessed Pharaoh, and went out from the presence of Pharaoh.'),
  ('222b060d-f0a5-5cbd-a017-4cd1a3cab9e2', 'eaf2268a-ac06-5dcc-ae02-2cb5d6f619e0', NULL, 11, 11, 'Joseph placed his father and his brothers, and gave them a possession in the land of Egypt, in the best of the land, in the land of Rameses, as Pharaoh had commanded.'),
  ('70064d55-cc95-5687-a511-5b48a715e967', 'eaf2268a-ac06-5dcc-ae02-2cb5d6f619e0', NULL, 12, 12, 'Joseph nourished his father, his brothers, and all of his father''s household, with bread, according to their families.'),
  ('2e3650c6-06e6-5179-a821-0832f438c29f', 'eaf2268a-ac06-5dcc-ae02-2cb5d6f619e0', NULL, 13, 13, 'There was no bread in all the land; for the famine was very severe, so that the land of Egypt and the land of Canaan fainted by reason of the famine.'),
  ('f39468db-290a-584f-a14b-94f6014779cf', 'eaf2268a-ac06-5dcc-ae02-2cb5d6f619e0', NULL, 14, 14, 'Joseph gathered up all the money that was found in the land of Egypt, and in the land of Canaan, for the grain which they bought: and Joseph brought the money into Pharaoh''s house.'),
  ('e8413835-d2d4-55df-a160-18269d610d4e', 'eaf2268a-ac06-5dcc-ae02-2cb5d6f619e0', NULL, 15, 15, 'When the money was all spent in the land of Egypt, and in the land of Canaan, all the Egyptians came to Joseph, and said, "Give us bread, for why should we die in your presence? For our money fails."'),
  ('3e3bbc67-1dd7-57b4-a5a4-7b16258c4645', 'eaf2268a-ac06-5dcc-ae02-2cb5d6f619e0', NULL, 16, 16, 'Joseph said, "Give me your livestock; and I will give you food for your livestock, if your money is gone."'),
  ('590ff216-f18d-549d-a1b1-2c92f7ffd06d', 'eaf2268a-ac06-5dcc-ae02-2cb5d6f619e0', NULL, 17, 17, 'They brought their livestock to Joseph, and Joseph gave them bread in exchange for the horses, and for the flocks, and for the herds, and for the donkeys: and he fed them with bread in exchange for all their livestock for that year.'),
  ('6eb3fd45-f2e0-5f9c-a05f-19aef220ebbb', 'eaf2268a-ac06-5dcc-ae02-2cb5d6f619e0', NULL, 18, 18, 'When that year was ended, they came to him the second year, and said to him, "We will not hide from my lord how our money is all spent, and the herds of livestock are my lord''s. There is nothing left in the sight of my lord, but our bodies, and our lands.'),
  ('84d5c1f5-48fc-5ca8-ad14-f0824985e529', 'eaf2268a-ac06-5dcc-ae02-2cb5d6f619e0', NULL, 19, 19, 'Why should we die before your eyes, both we and our land? Buy us and our land for bread, and we and our land will be servants to Pharaoh. Give us seed, that we may live, and not die, and that the land won''t be desolate."'),
  ('91372159-2a8d-5d2c-af17-bbf991d537bb', 'eaf2268a-ac06-5dcc-ae02-2cb5d6f619e0', NULL, 20, 20, 'So Joseph bought all the land of Egypt for Pharaoh, for every man of the Egyptians sold his field, because the famine was severe on them, and the land became Pharaoh''s.'),
  ('f197ae16-5902-5bfa-aab7-ce6cb34b69dd', 'eaf2268a-ac06-5dcc-ae02-2cb5d6f619e0', NULL, 21, 21, 'As for the people, he moved them to the cities from one end of the border of Egypt even to the other end of it.'),
  ('8242dbd5-bf9d-537c-a0b9-b74a54f3cdfe', 'eaf2268a-ac06-5dcc-ae02-2cb5d6f619e0', NULL, 22, 22, 'Only he didn''t buy the land of the priests, for the priests had a portion from Pharaoh, and ate their portion which Pharaoh gave them. That is why they didn''t sell their land.'),
  ('e0c9e679-0391-5454-a6c7-d28fc80d5449', 'eaf2268a-ac06-5dcc-ae02-2cb5d6f619e0', NULL, 23, 23, 'Then Joseph said to the people, "Behold, I have bought you and your land today for Pharaoh. Behold, here is seed for you, and you shall sow the land.'),
  ('d13672d3-4ae3-5757-a5ac-d2beee6fad6d', 'eaf2268a-ac06-5dcc-ae02-2cb5d6f619e0', NULL, 24, 24, 'It will happen at the harvests, that you shall give a fifth to Pharaoh, and four parts will be your own, for seed of the field, for your food, for them of your households, and for food for your little ones."'),
  ('21fa8970-169d-52b9-abfe-d756a6e33b31', 'eaf2268a-ac06-5dcc-ae02-2cb5d6f619e0', NULL, 25, 25, 'They said, "You have saved our lives! Let us find favor in the sight of my lord, and we will be Pharaoh''s servants."'),
  ('8e8ff5f2-a594-5e48-a6ad-cded40fd4b20', 'eaf2268a-ac06-5dcc-ae02-2cb5d6f619e0', NULL, 26, 26, 'Joseph made it a statute concerning the land of Egypt to this day, that Pharaoh should have the fifth. Only the land of the priests alone didn''t become Pharaoh''s.'),
  ('c25882d5-dacd-5429-aaa5-d537c6c39b56', 'eaf2268a-ac06-5dcc-ae02-2cb5d6f619e0', NULL, 27, 27, 'Israel lived in the land of Egypt, in the land of Goshen; and they got themselves possessions therein, and were fruitful, and multiplied exceedingly.'),
  ('ba0d6661-0e79-57a6-a6ea-2df90c413e59', 'eaf2268a-ac06-5dcc-ae02-2cb5d6f619e0', NULL, 28, 28, 'Jacob lived in the land of Egypt seventeen years. So the days of Jacob, the years of his life, were one hundred forty-seven years.'),
  ('921c5c3b-e9d9-59a8-ab4e-b57017208f63', 'eaf2268a-ac06-5dcc-ae02-2cb5d6f619e0', NULL, 29, 29, 'The time drew near that Israel must die, and he called his son Joseph, and said to him, "If now I have found favor in your sight, please put your hand under my thigh, and deal kindly and truly with me. Please don''t bury me in Egypt,'),
  ('03370f05-1e2d-5556-afa0-1dc38d17a3de', 'eaf2268a-ac06-5dcc-ae02-2cb5d6f619e0', NULL, 30, 30, 'but when I sleep with my fathers, you shall carry me out of Egypt, and bury me in their burying place." He said, "I will do as you have said."'),
  ('d6cea626-98d4-572d-a907-6950ee2d5a59', 'eaf2268a-ac06-5dcc-ae02-2cb5d6f619e0', NULL, 31, 31, 'He said, "Swear to me," and he swore to him. Israel bowed himself on the bed''s head.'),
  ('03ccdb37-6ca3-552e-a411-989d49e1b8a8', 'd3589994-6f14-526f-ac95-b1267d286516', NULL, 1, 1, 'It happened after these things, that someone said to Joseph, "Behold, your father is sick." He took with him his two sons, Manasseh and Ephraim.'),
  ('3dfae6d1-cf53-5509-af0d-656e1116148e', 'd3589994-6f14-526f-ac95-b1267d286516', NULL, 2, 2, 'Someone told Jacob, and said, "Behold, your son Joseph comes to you," and Israel strengthened himself, and sat on the bed.'),
  ('994fb12a-43f4-520a-a4f6-5263301b534c', 'd3589994-6f14-526f-ac95-b1267d286516', NULL, 3, 3, 'Jacob said to Joseph, "God Almighty appeared to me at Luz in the land of Canaan, and blessed me,'),
  ('9f3854b9-db22-52f3-aa7e-eb6d82762bb0', 'd3589994-6f14-526f-ac95-b1267d286516', NULL, 4, 4, 'and said to me, ''Behold, I will make you fruitful, and multiply you, and I will make of you a company of peoples, and will give this land to your seed after you for an everlasting possession.'''),
  ('74b0efef-81c0-5902-a19a-59efe67d4612', 'd3589994-6f14-526f-ac95-b1267d286516', NULL, 5, 5, 'Now your two sons, who were born to you in the land of Egypt before I came to you into Egypt, are mine; Ephraim and Manasseh, even as Reuben and Simeon, will be mine.'),
  ('9ccc1f68-749b-557b-a26f-516d1c20cb4b', 'd3589994-6f14-526f-ac95-b1267d286516', NULL, 6, 6, 'Your issue, who you become the father of after them, will be yours. They will be called after the name of their brothers in their inheritance.'),
  ('f7f9d3b6-c068-54f9-a76e-255e55e08055', 'd3589994-6f14-526f-ac95-b1267d286516', NULL, 7, 7, 'As for me, when I came from Paddan, Rachel died by me in the land of Canaan in the way, when there was still some distance to come to Ephrath, and I buried her there in the way to Ephrath (the same is Bethlehem)."'),
  ('f865da32-d42a-5a8e-a62b-c718de6947aa', 'd3589994-6f14-526f-ac95-b1267d286516', NULL, 8, 8, 'Israel saw Joseph''s sons, and said, "Who are these?"'),
  ('89d575fa-94e1-5798-a4b5-489d6bb2a0a3', 'd3589994-6f14-526f-ac95-b1267d286516', NULL, 9, 9, 'Joseph said to his father, "They are my sons, whom God has given me here." He said, "Please bring them to me, and I will bless them."'),
  ('e679a4aa-357a-5e77-ac0d-e52d949dbc22', 'd3589994-6f14-526f-ac95-b1267d286516', NULL, 10, 10, 'Now the eyes of Israel were dim for age, so that he couldn''t see. He brought them near to him; and he kissed them, and embraced them.'),
  ('0112ee71-9b54-52c1-afee-cd2325bade3b', 'd3589994-6f14-526f-ac95-b1267d286516', NULL, 11, 11, 'Israel said to Joseph, "I didn''t think I would see your face, and behold, God has let me see your seed also."'),
  ('36d2c8a0-f7b6-569e-a89b-17310e2448a1', 'd3589994-6f14-526f-ac95-b1267d286516', NULL, 12, 12, 'Joseph brought them out from between his knees, and he bowed himself with his face to the earth.'),
  ('a704e879-4027-5006-a406-043885a4d66b', 'd3589994-6f14-526f-ac95-b1267d286516', NULL, 13, 13, 'Joseph took them both, Ephraim in his right hand toward Israel''s left hand, and Manasseh in his left hand toward Israel''s right hand, and brought them near to him.'),
  ('b9cf05d9-a958-52a8-a974-21b7df76cd62', 'd3589994-6f14-526f-ac95-b1267d286516', NULL, 14, 14, 'Israel stretched out his right hand, and laid it on Ephraim''s head, who was the younger, and his left hand on Manasseh''s head, guiding his hands knowingly, for Manasseh was the firstborn.'),
  ('b63d6d37-a784-522c-a344-ee2a7bd553a9', 'd3589994-6f14-526f-ac95-b1267d286516', NULL, 15, 15, 'He blessed Joseph, and said, "The God before whom my fathers Abraham and Isaac did walk, the God who has fed me all my life long to this day,'),
  ('76e867ab-17d0-58e6-ad0b-fab93ed01c5d', 'd3589994-6f14-526f-ac95-b1267d286516', NULL, 16, 16, 'the angel who has redeemed me from all evil, bless the lads, and let my name be named on them, and the name of my fathers Abraham and Isaac. Let them grow into a multitude in the midst of the earth."'),
  ('cffb9f36-751b-5e11-a59e-71823e2657e6', 'd3589994-6f14-526f-ac95-b1267d286516', NULL, 17, 17, 'When Joseph saw that his father laid his right hand on the head of Ephraim, it displeased him. He held up his father''s hand, to remove it from Ephraim''s head to Manasseh''s head.'),
  ('3e1cdae1-d678-56dc-a172-4b41974ef90a', 'd3589994-6f14-526f-ac95-b1267d286516', NULL, 18, 18, 'Joseph said to his father, "Not so, my father; for this is the firstborn; put your right hand on his head."'),
  ('3ff055a9-d7b0-5256-af37-3775d32d4f9d', 'd3589994-6f14-526f-ac95-b1267d286516', NULL, 19, 19, 'His father refused, and said, "I know, my son, I know. He also will become a people, and he also will be great. However, his younger brother will be greater than he, and his seed will become a multitude of nations."'),
  ('9de93c64-eaee-5b4a-a38a-73b4f89ad275', 'd3589994-6f14-526f-ac95-b1267d286516', NULL, 20, 20, 'He blessed them that day, saying, "In you will Israel bless, saying, ''God make you as Ephraim and as Manasseh''" He set Ephraim before Manasseh.'),
  ('63cdc970-db09-59d1-ac63-9bda881f0c72', 'd3589994-6f14-526f-ac95-b1267d286516', NULL, 21, 21, 'Israel said to Joseph, "Behold, I am dying, but God will be with you, and bring you again to the land of your fathers.'),
  ('04ca98b0-08fc-5278-a272-72b54e231439', 'd3589994-6f14-526f-ac95-b1267d286516', NULL, 22, 22, 'Moreover I have given to you one portion above your brothers, which I took out of the hand of the Amorite with my sword and with my bow."'),
  ('7cdfc082-2c96-50d2-aeda-cf3cafe1a50c', '2308072a-0e35-59ad-a06b-e040a9107fa4', NULL, 1, 1, 'Jacob called to his sons, and said: "Gather yourselves together, that I may tell you that which will happen to you in the days to come.'),
  ('92b8719a-a189-5beb-a84e-318827bf2689', '2308072a-0e35-59ad-a06b-e040a9107fa4', NULL, 2, 2, 'Assemble yourselves, and hear, you sons of Jacob. Listen to Israel, your father.'),
  ('601a1734-852a-5eae-a2f7-07cc8d2a5d0a', '2308072a-0e35-59ad-a06b-e040a9107fa4', NULL, 3, 3, '"Reuben, you are my firstborn, my might, and the beginning of my strength; excelling in dignity, and excelling in power.'),
  ('2f212a11-6912-5846-aa87-5c0476d4d483', '2308072a-0e35-59ad-a06b-e040a9107fa4', NULL, 4, 4, 'Boiling over as water, you shall not excel; because you went up to your father''s bed, then defiled it. He went up to my couch.'),
  ('3c7f49d3-262d-5554-ac04-b7632eb16468', '2308072a-0e35-59ad-a06b-e040a9107fa4', NULL, 5, 5, '"Simeon and Levi are brothers. Their swords are weapons of violence.'),
  ('596c25a9-b222-5820-abb9-4a195c3508ee', '2308072a-0e35-59ad-a06b-e040a9107fa4', NULL, 6, 6, 'My soul, don''t come into their council. My glory, don''t be united to their assembly; for in their anger they killed men. In their self-will they hamstrung cattle.'),
  ('88fb4ddf-7364-50c9-a380-d4e424f267be', '2308072a-0e35-59ad-a06b-e040a9107fa4', NULL, 7, 7, 'Cursed be their anger, for it was fierce; and their wrath, for it was cruel. I will divide them in Jacob, and scatter them in Israel.'),
  ('4fe1776d-02e7-5c0a-a952-be7f18188281', '2308072a-0e35-59ad-a06b-e040a9107fa4', NULL, 8, 8, '"Judah, your brothers will praise you. Your hand will be on the neck of your enemies. Your father''s sons will bow down before you.'),
  ('30b1790a-a425-54b9-af90-68977f6fdc00', '2308072a-0e35-59ad-a06b-e040a9107fa4', NULL, 9, 9, 'Judah is a lion''s cub. From the prey, my son, you have gone up. He stooped down, he crouched as a lion, as a lioness. Who will rouse him up?'),
  ('950bd752-d9a3-51c5-a55c-72b76b1a0b5c', '2308072a-0e35-59ad-a06b-e040a9107fa4', NULL, 10, 10, 'The scepter will not depart from Judah, nor the ruler''s staff from between his feet, until he comes to whom it belongs. To him will the obedience of the peoples be.'),
  ('1abc3b42-f59b-5a02-ae02-98a89074eaf0', '2308072a-0e35-59ad-a06b-e040a9107fa4', NULL, 11, 11, 'Binding his foal to the vine, his donkey''s colt to the choice vine; he has washed his garments in wine, his robes in the blood of grapes.'),
  ('8a671740-5a19-5eee-a4b7-5201e27cbcd3', '2308072a-0e35-59ad-a06b-e040a9107fa4', NULL, 12, 12, 'His eyes will be red with wine, his teeth white with milk.'),
  ('1f85b493-84bd-550c-a984-7d4e8c7e9005', '2308072a-0e35-59ad-a06b-e040a9107fa4', NULL, 13, 13, '"Zebulun will dwell at the haven of the sea. He will be for a haven of ships. His border will be on Sidon.'),
  ('fe4713a8-ca83-5b1f-a934-7a8641531c8f', '2308072a-0e35-59ad-a06b-e040a9107fa4', NULL, 14, 14, '"Issachar is a strong donkey, lying down between the saddlebags.'),
  ('5fa0ecf8-41f1-5fb1-ad70-0e013b491ac7', '2308072a-0e35-59ad-a06b-e040a9107fa4', NULL, 15, 15, 'He saw a resting place, that it was good, the land, that it was pleasant. He bows his shoulder to the burden, and becomes a servant doing forced labor.'),
  ('2f80a634-486a-505d-a1a3-db35b4b4a66a', '2308072a-0e35-59ad-a06b-e040a9107fa4', NULL, 16, 16, '"Dan will judge his people, as one of the tribes of Israel.'),
  ('bf4d6d18-5588-5657-ae52-7130bb9bc7af', '2308072a-0e35-59ad-a06b-e040a9107fa4', NULL, 17, 17, 'Dan will be a serpent in the way, an adder in the path, That bites the horse''s heels, so that his rider falls backward.'),
  ('c3c8b4c5-a05f-5ba9-a820-3e149fbccf5c', '2308072a-0e35-59ad-a06b-e040a9107fa4', NULL, 18, 18, 'I have waited for your salvation, Yahweh.'),
  ('30186343-1d9d-548b-aef4-a11bd2e69a63', '2308072a-0e35-59ad-a06b-e040a9107fa4', NULL, 19, 19, '"A troop will press on Gad, but he will press on their heel.'),
  ('ac812c24-b001-5cd2-a363-1e01e85cc837', '2308072a-0e35-59ad-a06b-e040a9107fa4', NULL, 20, 20, '"Asher''s food will be rich. He will yield royal dainties.'),
  ('1a456034-7b40-50c8-a48b-408a7b9beadb', '2308072a-0e35-59ad-a06b-e040a9107fa4', NULL, 21, 21, '"Naphtali is a doe set free, who bears beautiful fawns.'),
  ('0f79dc06-b0da-58ae-a2c2-350575516810', '2308072a-0e35-59ad-a06b-e040a9107fa4', NULL, 22, 22, '"Joseph is a fruitful vine, a fruitful vine by a spring. His branches run over the wall.'),
  ('43bd3b59-bae1-577d-afe2-03741725d947', '2308072a-0e35-59ad-a06b-e040a9107fa4', NULL, 23, 23, 'The archers have severely grieved him, shot at him, and persecute him:'),
  ('f16ae7bb-191e-5d88-a0e2-b3578c49017e', '2308072a-0e35-59ad-a06b-e040a9107fa4', NULL, 24, 24, 'But his bow remained strong. The arms of his hands were made strong, by the hands of the Mighty One of Jacob, (from there is the shepherd, the stone of Israel),'),
  ('aa894af6-4980-58cd-a4be-4b62416727c2', '2308072a-0e35-59ad-a06b-e040a9107fa4', NULL, 25, 25, 'even by the God of your father, who will help you; by the Almighty, who will bless you, with blessings of heaven above, blessings of the deep that lies below, blessings of the breasts, and of the womb.'),
  ('0f234589-2564-5db2-a2a4-af3d12856602', '2308072a-0e35-59ad-a06b-e040a9107fa4', NULL, 26, 26, 'The blessings of your father have prevailed above the blessings of your ancestors, above the boundaries of the ancient hills. They will be on the head of Joseph, on the crown of the head of him who is separated from his brothers.'),
  ('9df707b8-09bd-5d34-a2a3-de7cf8d11dc3', '2308072a-0e35-59ad-a06b-e040a9107fa4', NULL, 27, 27, '"Benjamin is a ravenous wolf. In the morning he will devour the prey. At evening he will divide the spoil."'),
  ('47092c0e-0ac8-51be-a042-40636bdb36f1', '2308072a-0e35-59ad-a06b-e040a9107fa4', NULL, 28, 28, 'All these are the twelve tribes of Israel, and this is what their father spoke to them and blessed them. He blessed everyone according to his blessing.'),
  ('efb70b58-9f6b-5fbc-ae16-301eeea1c2b5', '2308072a-0e35-59ad-a06b-e040a9107fa4', NULL, 29, 29, 'He instructed them, and said to them, "I am to be gathered to my people. Bury me with my fathers in the cave that is in the field of Ephron the Hittite,'),
  ('131e2bd3-e7bb-5487-ae72-ee841c1ad63a', '2308072a-0e35-59ad-a06b-e040a9107fa4', NULL, 30, 30, 'in the cave that is in the field of Machpelah, which is before Mamre, in the land of Canaan, which Abraham bought with the field from Ephron the Hittite as a burial place.'),
  ('8e87829a-1fff-5af4-ae0b-d855c08d2c57', '2308072a-0e35-59ad-a06b-e040a9107fa4', NULL, 31, 31, 'There they buried Abraham and Sarah, his wife. There they buried Isaac and Rebekah, his wife, and there I buried Leah:'),
  ('0ee465b9-7854-50cf-a188-d066f0505118', '2308072a-0e35-59ad-a06b-e040a9107fa4', NULL, 32, 32, 'the field and the cave that is therein, which was purchased from the children of Heth."'),
  ('b0d393b9-8a70-510c-ae5b-e13cc26d8162', '2308072a-0e35-59ad-a06b-e040a9107fa4', NULL, 33, 33, 'When Jacob made an end of charging his sons, he gathered up his feet into the bed, and yielded up the spirit, and was gathered to his people.'),
  ('31327b6f-2f96-54fe-a6b6-50f8ab3dcd1c', '3d3cad4e-24ed-58d8-a295-eca10901bdd3', NULL, 1, 1, 'Joseph fell on his father''s face, wept on him, and kissed him.'),
  ('2c09fd98-e88a-5d8e-a7d3-85316b545f37', '3d3cad4e-24ed-58d8-a295-eca10901bdd3', NULL, 2, 2, 'Joseph commanded his servants, the physicians, to embalm his father; and the physicians embalmed Israel.'),
  ('21094bfd-692f-527b-a6c7-25f15bd0d1ca', '3d3cad4e-24ed-58d8-a295-eca10901bdd3', NULL, 3, 3, 'Forty days were fulfilled for him, for that is how many the days it takes to embalm. The Egyptians wept for him for seventy days.'),
  ('5a39a203-96d7-5b0d-aabd-9094bb937fba', '3d3cad4e-24ed-58d8-a295-eca10901bdd3', NULL, 4, 4, 'When the days of weeping for him were past, Joseph spoke to the house of Pharaoh, saying, "If now I have found favor in your eyes, please speak in the ears of Pharaoh, saying,'),
  ('ae9c63a3-f308-56f0-a6ef-a9f188ee94d3', '3d3cad4e-24ed-58d8-a295-eca10901bdd3', NULL, 5, 5, '''My father made me swear, saying, "Behold, I am dying. Bury me in my grave which I have dug for myself in the land of Canaan." Now therefore, please let me go up and bury my father, and I will come again.''"'),
  ('aaec8ed9-fcd6-5b54-a65a-cf3022c60e4d', '3d3cad4e-24ed-58d8-a295-eca10901bdd3', NULL, 6, 6, 'Pharaoh said, "Go up, and bury your father, just like he made you swear."'),
  ('f520c0af-0592-56e9-a466-5497303f3282', '3d3cad4e-24ed-58d8-a295-eca10901bdd3', NULL, 7, 7, 'Joseph went up to bury his father; and with him went up all the servants of Pharaoh, the elders of his house, all the elders of the land of Egypt,'),
  ('ccacabfb-59f5-52c8-a535-7185e05252cf', '3d3cad4e-24ed-58d8-a295-eca10901bdd3', NULL, 8, 8, 'all the house of Joseph, his brothers, and his father''s house. Only their little ones, their flocks, and their herds, they left in the land of Goshen.'),
  ('e1a65544-087e-5d34-aebe-8f97a95f3b34', '3d3cad4e-24ed-58d8-a295-eca10901bdd3', NULL, 9, 9, 'There went up with him both chariots and horsemen. It was a very great company.'),
  ('37daa341-a12f-574e-a962-da8dbf440de5', '3d3cad4e-24ed-58d8-a295-eca10901bdd3', NULL, 10, 10, 'They came to the threshing floor of Atad, which is beyond the Jordan, and there they lamented with a very great and severe lamentation. He mourned for his father seven days.'),
  ('611920d8-a3c4-59e9-a7cf-b86fcdb67dc7', '3d3cad4e-24ed-58d8-a295-eca10901bdd3', NULL, 11, 11, 'When the inhabitants of the land, the Canaanites, saw the mourning in the floor of Atad, they said, "This is a grievous mourning by the Egyptians." Therefore, its name was called Abel Mizraim, which is beyond the Jordan.'),
  ('6b5a888e-01f9-512f-a3d6-379d39ce4373', '3d3cad4e-24ed-58d8-a295-eca10901bdd3', NULL, 12, 12, 'His sons did to him just as he commanded them,'),
  ('5029e142-c911-565d-a5a7-b695f0bf2650', '3d3cad4e-24ed-58d8-a295-eca10901bdd3', NULL, 13, 13, 'for his sons carried him into the land of Canaan, and buried him in the cave of the field of Machpelah, which Abraham bought with the field, for a possession of a burial site, from Ephron the Hittite, before Mamre.'),
  ('879c9935-84ec-545c-a094-0c0e0a45cd57', '3d3cad4e-24ed-58d8-a295-eca10901bdd3', NULL, 14, 14, 'Joseph returned into Egypt--he, and his brothers, and all that went up with him to bury his father, after he had buried his father.'),
  ('4b51d0bc-5b43-5c98-a244-116a85e0205c', '3d3cad4e-24ed-58d8-a295-eca10901bdd3', NULL, 15, 15, 'When Joseph''s brothers saw that their father was dead, they said, "It may be that Joseph will hate us, and will fully pay us back for all of the evil which we did to him."'),
  ('7dc72de8-18c7-532f-a0ce-1e4f94e34d21', '3d3cad4e-24ed-58d8-a295-eca10901bdd3', NULL, 16, 16, 'They sent a message to Joseph, saying, "Your father commanded before he died, saying,'),
  ('76c478fd-3c0c-5db1-a546-9876189fb386', '3d3cad4e-24ed-58d8-a295-eca10901bdd3', NULL, 17, 17, '''You shall tell Joseph, "Now please forgive the disobedience of your brothers, and their sin, because they did evil to you."'' Now, please forgive the disobedience of the servants of the God of your father." Joseph wept when they spoke to him.'),
  ('69b1029e-b29f-5445-a980-259691131f89', '3d3cad4e-24ed-58d8-a295-eca10901bdd3', NULL, 18, 18, 'His brothers also went and fell down before his face; and they said, "Behold, we are your servants."'),
  ('c25677f8-0cd1-5182-a911-8ecdae07164b', '3d3cad4e-24ed-58d8-a295-eca10901bdd3', NULL, 19, 19, 'Joseph said to them, "Don''t be afraid, for am I in the place of God?'),
  ('6f1b9090-fabe-5ff6-adda-7c5c1b82bd8e', '3d3cad4e-24ed-58d8-a295-eca10901bdd3', NULL, 20, 20, 'As for you, you meant evil against me, but God meant it for good, to bring to pass, as it is this day, to save many people alive.'),
  ('0fad79f4-a261-576d-a645-7be4ea73ae69', '3d3cad4e-24ed-58d8-a295-eca10901bdd3', NULL, 21, 21, 'Now therefore don''t be afraid. I will nourish you and your little ones." He comforted them, and spoke kindly to them.'),
  ('2dcf8264-0dde-5a19-a20e-dd792dc6be3a', '3d3cad4e-24ed-58d8-a295-eca10901bdd3', NULL, 22, 22, 'Joseph lived in Egypt, he, and his father''s house. Joseph lived one hundred ten years.'),
  ('3e5dd32b-6bc7-57ea-a9a0-9fc1d705afbb', '3d3cad4e-24ed-58d8-a295-eca10901bdd3', NULL, 23, 23, 'Joseph saw Ephraim''s children to the third generation. The children also of Machir, the son of Manasseh, were born on Joseph''s knees.'),
  ('d73fbdfd-262f-55bf-a474-a5a41b0ee015', '3d3cad4e-24ed-58d8-a295-eca10901bdd3', NULL, 24, 24, 'Joseph said to his brothers, "I am dying, but God will surely visit you, and bring you up out of this land to the land which he swore to Abraham, to Isaac, and to Jacob."'),
  ('641733f9-cb8a-54cb-a9f9-ec6a07628ce0', '3d3cad4e-24ed-58d8-a295-eca10901bdd3', NULL, 25, 25, 'Joseph took an oath of the children of Israel, saying, "God will surely visit you, and you shall carry up my bones from here."'),
  ('108fa03d-be9d-52d4-a11d-0de093a92c03', '3d3cad4e-24ed-58d8-a295-eca10901bdd3', NULL, 26, 26, 'So Joseph died, being one hundred ten years old, and they embalmed him, and he was put in a coffin in Egypt.'),
  ('0f95fe39-5f01-5c23-ab29-c4093a7a8b18', '6e703c50-de6f-5a1e-a4de-88d48c9ea799', NULL, 1, 1, 'Now these are the names of the sons of Israel, who came into Egypt (every man and his household came with Jacob):'),
  ('a4f456ec-0702-5b25-a620-40b20d7fe639', '6e703c50-de6f-5a1e-a4de-88d48c9ea799', NULL, 2, 2, 'Reuben, Simeon, Levi, and Judah,'),
  ('7494699a-0254-5f61-a363-82854ee773fe', '6e703c50-de6f-5a1e-a4de-88d48c9ea799', NULL, 3, 3, 'Issachar, Zebulun, and Benjamin,'),
  ('34b2d660-6eea-5c20-aced-e1c8f1a61666', '6e703c50-de6f-5a1e-a4de-88d48c9ea799', NULL, 4, 4, 'Dan and Naphtali, Gad and Asher.'),
  ('dda9bf1d-0eb9-5805-a895-161e8d324b26', '6e703c50-de6f-5a1e-a4de-88d48c9ea799', NULL, 5, 5, 'All the souls who came out of Jacob''s body were seventy souls, and Joseph was in Egypt already.'),
  ('a425250a-212c-5b64-aa3c-7eabd10e4062', '6e703c50-de6f-5a1e-a4de-88d48c9ea799', NULL, 6, 6, 'Joseph died, as did all his brothers, and all that generation.'),
  ('f1fa2c76-6363-5c71-aad0-d93e17f0d7fa', '6e703c50-de6f-5a1e-a4de-88d48c9ea799', NULL, 7, 7, 'The children of Israel were fruitful, and increased abundantly, and multiplied, and grew exceedingly mighty; and the land was filled with them.'),
  ('3874c6f5-e803-58c6-a805-ac985d2b4a82', '6e703c50-de6f-5a1e-a4de-88d48c9ea799', NULL, 8, 8, 'Now there arose a new king over Egypt, who didn''t know Joseph.'),
  ('608814d5-2ab5-5a6a-ae40-c01cc6924863', '6e703c50-de6f-5a1e-a4de-88d48c9ea799', NULL, 9, 9, 'He said to his people, "Behold, the people of the children of Israel are more and mightier than we.'),
  ('1a2468fe-05a7-5351-afb7-8bdf166bfae8', '6e703c50-de6f-5a1e-a4de-88d48c9ea799', NULL, 10, 10, 'Come, let us deal wisely with them, lest they multiply, and it happen that when any war breaks out, they also join themselves to our enemies, and fight against us, and escape out of the land."'),
  ('c04a325a-3aa3-5d7d-afae-990652265729', '6e703c50-de6f-5a1e-a4de-88d48c9ea799', NULL, 11, 11, 'Therefore they set taskmasters over them to afflict them with their burdens. They built storage cities for Pharaoh: Pithom and Raamses.'),
  ('8dfc1bca-1665-57fb-a554-311304feb956', '6e703c50-de6f-5a1e-a4de-88d48c9ea799', NULL, 12, 12, 'But the more they afflicted them, the more they multiplied and the more they spread out. They were grieved because of the children of Israel.'),
  ('f139797f-2d3e-5e81-abe5-fea757a45541', '6e703c50-de6f-5a1e-a4de-88d48c9ea799', NULL, 13, 13, 'The Egyptians ruthlessly made the children of Israel serve,'),
  ('74eb8ff9-85e7-5aec-ac8b-6e843c939925', '6e703c50-de6f-5a1e-a4de-88d48c9ea799', NULL, 14, 14, 'and they made their lives bitter with hard service, in mortar and in brick, and in all kinds of service in the field, all their service, in which they ruthlessly made them serve.'),
  ('2c4c8e10-864f-5f20-af45-3f4f7a86ec8a', '6e703c50-de6f-5a1e-a4de-88d48c9ea799', NULL, 15, 15, 'The king of Egypt spoke to the Hebrew midwives, of whom the name of the one was Shiphrah, and the name of the other Puah,'),
  ('e78bf6a4-bc63-5dc7-aafd-84d9386baa4c', '6e703c50-de6f-5a1e-a4de-88d48c9ea799', NULL, 16, 16, 'and he said, "When you perform the duty of a midwife to the Hebrew women, and see them on the birth stool; if it is a son, then you shall kill him; but if it is a daughter, then she shall live."'),
  ('4d4254d4-f4ed-5815-a92a-e076a106057f', '6e703c50-de6f-5a1e-a4de-88d48c9ea799', NULL, 17, 17, 'But the midwives feared God, and didn''t do what the king of Egypt commanded them, but saved the baby boys alive.'),
  ('0b0519ad-ceb0-5d53-a902-2b61b8bbd9e2', '6e703c50-de6f-5a1e-a4de-88d48c9ea799', NULL, 18, 18, 'The king of Egypt called for the midwives, and said to them, "Why have you done this thing, and have saved the boys alive?"'),
  ('dc688700-ca24-57ee-a310-9ee859954a67', '6e703c50-de6f-5a1e-a4de-88d48c9ea799', NULL, 19, 19, 'The midwives said to Pharaoh, "Because the Hebrew women aren''t like the Egyptian women; for they are vigorous, and give birth before the midwife comes to them."'),
  ('d45a6943-b2dd-5719-a441-1e45db916933', '6e703c50-de6f-5a1e-a4de-88d48c9ea799', NULL, 20, 20, 'God dealt well with the midwives, and the people multiplied, and grew very mighty.'),
  ('6025b47f-9364-5f22-ad9a-7d1dd8b8b49a', '6e703c50-de6f-5a1e-a4de-88d48c9ea799', NULL, 21, 21, 'It happened, because the midwives feared God, that he gave them families.'),
  ('d2411cf8-6e87-5f14-a6eb-db971b8dfef6', '6e703c50-de6f-5a1e-a4de-88d48c9ea799', NULL, 22, 22, 'Pharaoh commanded all his people, saying, "You shall cast every son who is born into the river, and every daughter you shall save alive."'),
  ('ff4c5c40-30a6-5720-a3cd-cafac3532676', '2e0c76eb-ff39-5d63-a9fe-f64f5a80d518', NULL, 1, 1, 'A man of the house of Levi went and took a daughter of Levi as his wife.'),
  ('78004021-07d3-5a54-af84-87039909654c', '2e0c76eb-ff39-5d63-a9fe-f64f5a80d518', NULL, 2, 2, 'The woman conceived, and bore a son. When she saw that he was a fine child, she hid him three months.'),
  ('497ac28e-9354-51e7-a733-17129f56b7e8', '2e0c76eb-ff39-5d63-a9fe-f64f5a80d518', NULL, 3, 3, 'When she could no longer hide him, she took a papyrus basket for him, and coated it with tar and with pitch. She put the child in it, and laid it in the reeds by the river''s bank.'),
  ('4f8301c5-474b-54ce-aae6-7129f87536d8', '2e0c76eb-ff39-5d63-a9fe-f64f5a80d518', NULL, 4, 4, 'His sister stood far off, to see what would be done to him.'),
  ('a74ac418-63e3-55b2-ae24-e3b24d4e5bd8', '2e0c76eb-ff39-5d63-a9fe-f64f5a80d518', NULL, 5, 5, 'Pharaoh''s daughter came down to bathe at the river. Her maidens walked along by the riverside. She saw the basket among the reeds, and sent her handmaid to get it.'),
  ('32bbf1bb-388b-5b4e-a366-700c797304cb', '2e0c76eb-ff39-5d63-a9fe-f64f5a80d518', NULL, 6, 6, 'She opened it, and saw the child, and behold, the baby cried. She had compassion on him, and said, "This is one of the Hebrews'' children."'),
  ('13d937d6-07d9-5c0d-ae47-e29eea82a50e', '2e0c76eb-ff39-5d63-a9fe-f64f5a80d518', NULL, 7, 7, 'Then his sister said to Pharaoh''s daughter, "Should I go and call a nurse for you from the Hebrew women, that she may nurse the child for you?"'),
  ('240c81d1-6b6a-52de-a663-7b7f7e852df9', '2e0c76eb-ff39-5d63-a9fe-f64f5a80d518', NULL, 8, 8, 'Pharaoh''s daughter said to her, "Go." The maiden went and called the child''s mother.'),
  ('bbbd4ab2-5361-5562-a649-2ac9f80bfa1d', '2e0c76eb-ff39-5d63-a9fe-f64f5a80d518', NULL, 9, 9, 'Pharaoh''s daughter said to her, "Take this child away, and nurse him for me, and I will give you your wages." The woman took the child, and nursed it.'),
  ('b31a38f5-dd8c-5d49-a797-283204b35ddd', '2e0c76eb-ff39-5d63-a9fe-f64f5a80d518', NULL, 10, 10, 'The child grew, and she brought him to Pharaoh''s daughter, and he became her son. She named him Moses, and said, "Because I drew him out of the water."'),
  ('6a6d4198-d7e1-563b-a4df-02623ef68d42', '2e0c76eb-ff39-5d63-a9fe-f64f5a80d518', NULL, 11, 11, 'It happened in those days, when Moses had grown up, that he went out to his brothers, and looked at their burdens. He saw an Egyptian striking a Hebrew, one of his brothers.'),
  ('f38cf09f-9280-54ce-aa94-d398ea8c1e9a', '2e0c76eb-ff39-5d63-a9fe-f64f5a80d518', NULL, 12, 12, 'He looked this way and that way, and when he saw that there was no one, he killed the Egyptian, and hid him in the sand.'),
  ('a7ca2b89-6e2f-529d-a322-d9fb36312097', '2e0c76eb-ff39-5d63-a9fe-f64f5a80d518', NULL, 13, 13, 'He went out the second day, and behold, two men of the Hebrews were fighting with each other. He said to him who did the wrong, "Why do you strike your fellow?"'),
  ('82c52f3e-517a-5c1a-a5dd-87ccbc4ebf36', '2e0c76eb-ff39-5d63-a9fe-f64f5a80d518', NULL, 14, 14, 'He said, "Who made you a prince and a judge over us? Do you plan to kill me, as you killed the Egyptian?" Moses was afraid, and said, "Surely this thing is known."'),
  ('21a5f82f-a60a-54a7-a11a-359bc65b1a5a', '2e0c76eb-ff39-5d63-a9fe-f64f5a80d518', NULL, 15, 15, 'Now when Pharaoh heard this thing, he sought to kill Moses. But Moses fled from the face of Pharaoh, and lived in the land of Midian, and he sat down by a well.'),
  ('a64b48ea-b8b0-53ea-aa34-e40c1f93d1d6', '2e0c76eb-ff39-5d63-a9fe-f64f5a80d518', NULL, 16, 16, 'Now the priest of Midian had seven daughters. They came and drew water, and filled the troughs to water their father''s flock.'),
  ('726e0524-dd18-52db-a85a-7f7da5dcbf1d', '2e0c76eb-ff39-5d63-a9fe-f64f5a80d518', NULL, 17, 17, 'The shepherds came and drove them away; but Moses stood up and helped them, and watered their flock.'),
  ('717ab46a-ffd7-59bc-a866-9939be545fdd', '2e0c76eb-ff39-5d63-a9fe-f64f5a80d518', NULL, 18, 18, 'When they came to Reuel, their father, he said, "How is it that you have returned so early today?"'),
  ('705bc931-fc98-5475-a321-aaceeaa21c3f', '2e0c76eb-ff39-5d63-a9fe-f64f5a80d518', NULL, 19, 19, 'They said, "An Egyptian delivered us out of the hand of the shepherds, and moreover he drew water for us, and watered the flock."'),
  ('cda7c5b7-12bb-5c03-a3e6-abc78e43e18b', '2e0c76eb-ff39-5d63-a9fe-f64f5a80d518', NULL, 20, 20, 'He said to his daughters, "Where is he? Why is it that you have left the man? Call him, that he may eat bread."'),
  ('48e355d5-8b18-52c7-a2fd-c07c4f0c90bc', '2e0c76eb-ff39-5d63-a9fe-f64f5a80d518', NULL, 21, 21, 'Moses was content to dwell with the man. He gave Moses Zipporah, his daughter.'),
  ('517a6615-9cb2-5243-ac31-9cc3e4198206', '2e0c76eb-ff39-5d63-a9fe-f64f5a80d518', NULL, 22, 22, 'She bore a son, and he named him Gershom, for he said, "I have lived as a foreigner in a foreign land."'),
  ('0dc9e603-2e14-5704-a780-92a82c0f2c8a', '2e0c76eb-ff39-5d63-a9fe-f64f5a80d518', NULL, 23, 23, 'It happened in the course of those many days, that the king of Egypt died, and the children of Israel sighed because of the bondage, and they cried, and their cry came up to God because of the bondage.'),
  ('31524d16-eda1-5548-a3fe-6a3dfff73f26', '2e0c76eb-ff39-5d63-a9fe-f64f5a80d518', NULL, 24, 24, 'God heard their groaning, and God remembered his covenant with Abraham, with Isaac, and with Jacob.'),
  ('59bc7c68-0fbf-58e6-ade3-cb528d971268', '2e0c76eb-ff39-5d63-a9fe-f64f5a80d518', NULL, 25, 25, 'God saw the children of Israel, and God was concerned about them.'),
  ('ebc05fd9-b95d-5570-a91f-cb9e92834d57', '2b593f7c-76ec-51ed-a877-12685f340cf0', NULL, 1, 1, 'Now Moses was keeping the flock of Jethro, his father-in-law, the priest of Midian, and he led the flock to the back of the wilderness, and came to God''s mountain, to Horeb.'),
  ('89b4ab2d-7a93-5f1c-a46c-3e2dcebeab76', '2b593f7c-76ec-51ed-a877-12685f340cf0', NULL, 2, 2, 'The angel of Yahweh appeared to him in a flame of fire out of the midst of a bush. He looked, and behold, the bush burned with fire, and the bush was not consumed.'),
  ('13c4bce6-2a24-535c-a904-279c3d0d1878', '2b593f7c-76ec-51ed-a877-12685f340cf0', NULL, 3, 3, 'Moses said, "I will turn aside now, and see this great sight, why the bush is not burnt."'),
  ('230f89bf-0ee0-5ffa-a2d5-58f4dfe6894f', '2b593f7c-76ec-51ed-a877-12685f340cf0', NULL, 4, 4, 'When Yahweh saw that he turned aside to see, God called to him out of the midst of the bush, and said, "Moses! Moses!" He said, "Here I am."'),
  ('581c9a20-0ba5-5771-a861-8b54dc4df7d9', '2b593f7c-76ec-51ed-a877-12685f340cf0', NULL, 5, 5, 'He said, "Don''t come close. Take your sandals off of your feet, for the place you are standing on is holy ground."'),
  ('f9f55d30-97cf-5678-a214-2f283560c406', '2b593f7c-76ec-51ed-a877-12685f340cf0', NULL, 6, 6, 'Moreover he said, "I am the God of your father, the God of Abraham, the God of Isaac, and the God of Jacob." Moses hid his face; for he was afraid to look at God.'),
  ('c97a4069-81c7-571e-afca-5b2964b50d55', '2b593f7c-76ec-51ed-a877-12685f340cf0', NULL, 7, 7, 'Yahweh said, "I have surely seen the affliction of my people who are in Egypt, and have heard their cry because of their taskmasters, for I know their sorrows.'),
  ('7516f5bf-46c3-53db-a1c2-b25e94989939', '2b593f7c-76ec-51ed-a877-12685f340cf0', NULL, 8, 8, 'I have come down to deliver them out of the hand of the Egyptians, and to bring them up out of that land to a good and large land, to a land flowing with milk and honey; to the place of the Canaanite, the Hittite, the Amorite, the Perizzite, the Hivite, and the Jebusite.'),
  ('ea746c1e-bfb8-509e-a32c-5822509c4c27', '2b593f7c-76ec-51ed-a877-12685f340cf0', NULL, 9, 9, 'Now, behold, the cry of the children of Israel has come to me. Moreover I have seen the oppression with which the Egyptians oppress them.'),
  ('6c8a572c-5fc8-5577-ad0c-f17fe3d1a1d3', '2b593f7c-76ec-51ed-a877-12685f340cf0', NULL, 10, 10, 'Come now therefore, and I will send you to Pharaoh, that you may bring forth my people, the children of Israel, out of Egypt."'),
  ('222128b5-4f0b-5469-aedf-4271189202d6', '2b593f7c-76ec-51ed-a877-12685f340cf0', NULL, 11, 11, 'Moses said to God, "Who am I, that I should go to Pharaoh, and that I should bring forth the children of Israel out of Egypt?"'),
  ('b6b1080d-8e3d-55fe-a5a0-4a6423f1a069', '2b593f7c-76ec-51ed-a877-12685f340cf0', NULL, 12, 12, 'He said, "Certainly I will be with you. This will be the token to you, that I have sent you: when you have brought forth the people out of Egypt, you shall serve God on this mountain."'),
  ('edf4fde1-7781-5e35-acba-5ada3f91dc9d', '2b593f7c-76ec-51ed-a877-12685f340cf0', NULL, 13, 13, 'Moses said to God, "Behold, when I come to the children of Israel, and tell them, ''The God of your fathers has sent me to you;'' and they ask me, ''What is his name?'' What should I tell them?"'),
  ('27f0fe35-0a1a-5d68-a0fa-f7c1bfee172c', '2b593f7c-76ec-51ed-a877-12685f340cf0', NULL, 14, 14, 'God said to Moses, "I AM WHO I AM," and he said, "You shall tell the children of Israel this: ''I AM has sent me to you.''"'),
  ('25e4d018-aa0f-50d1-a080-2cd6550bbd49', '2b593f7c-76ec-51ed-a877-12685f340cf0', NULL, 15, 15, 'God said moreover to Moses, "You shall tell the children of Israel this, ''Yahweh, the God of your fathers, the God of Abraham, the God of Isaac, and the God of Jacob, has sent me to you.'' This is my name forever, and this is my memorial to all generations.'),
  ('e4be2231-54fd-5441-a784-57f184554556', '2b593f7c-76ec-51ed-a877-12685f340cf0', NULL, 16, 16, 'Go, and gather the elders of Israel together, and tell them, ''Yahweh, the God of your fathers, the God of Abraham, of Isaac, and of Jacob, has appeared to me, saying, "I have surely visited you, and seen that which is done to you in Egypt;'),
  ('2e9cbf54-33d6-5e5f-ab86-1ac73e770279', '2b593f7c-76ec-51ed-a877-12685f340cf0', NULL, 17, 17, 'and I have said, I will bring you up out of the affliction of Egypt to the land of the Canaanite, the Hittite, the Amorite, the Perizzite, the Hivite, and the Jebusite, to a land flowing with milk and honey."'''),
  ('367a8cbb-20a9-5906-a3f6-a5403638db34', '2b593f7c-76ec-51ed-a877-12685f340cf0', NULL, 18, 18, 'They will listen to your voice, and you shall come, you and the elders of Israel, to the king of Egypt, and you shall tell him, ''Yahweh, the God of the Hebrews, has met with us. Now please let us go three days'' journey into the wilderness, that we may sacrifice to Yahweh, our God.'''),
  ('624f726d-030e-57da-ae85-5c8de4367213', '2b593f7c-76ec-51ed-a877-12685f340cf0', NULL, 19, 19, 'I know that the king of Egypt won''t give you permission to go, no, not by a mighty hand.'),
  ('0d6cf840-4acc-5069-a84e-4cfcf948a4dc', '2b593f7c-76ec-51ed-a877-12685f340cf0', NULL, 20, 20, 'I will put forth my hand and strike Egypt with all my wonders which I will do in its midst, and after that he will let you go.'),
  ('dcbdba90-acb8-5cbd-aeee-8f57b8683925', '2b593f7c-76ec-51ed-a877-12685f340cf0', NULL, 21, 21, 'I will give this people favor in the sight of the Egyptians, and it will happen that when you go, you shall not go empty-handed.'),
  ('284097ed-85e9-5ef0-af8c-9991494e8a92', '2b593f7c-76ec-51ed-a877-12685f340cf0', NULL, 22, 22, 'But every woman shall ask of her neighbor, and of her who visits her house, jewels of silver, jewels of gold, and clothing; and you shall put them on your sons, and on your daughters. You shall plunder the Egyptians."'),
  ('08335c59-3a52-5168-a748-41b8dd6b60a4', 'adfab075-8409-5e14-a4b5-1ae1d32b30a0', NULL, 1, 1, 'Moses answered, "But, behold, they will not believe me, nor listen to my voice; for they will say, ''Yahweh has not appeared to you.''"'),
  ('652bda9c-5596-5703-a7e9-6cafe4f85435', 'adfab075-8409-5e14-a4b5-1ae1d32b30a0', NULL, 2, 2, 'Yahweh said to him, "What is that in your hand?" He said, "A rod."'),
  ('01360ce3-29dc-5901-a9f2-31a61601fc66', 'adfab075-8409-5e14-a4b5-1ae1d32b30a0', NULL, 3, 3, 'He said, "Throw it on the ground." He threw it on the ground, and it became a snake; and Moses ran away from it.'),
  ('3451d0e4-7166-5a34-ab9b-91034aae66f9', 'adfab075-8409-5e14-a4b5-1ae1d32b30a0', NULL, 4, 4, 'Yahweh said to Moses, "Put forth your hand, and take it by the tail." He put forth his hand, and laid hold of it, and it became a rod in his hand.'),
  ('56bbda57-d534-534d-a726-2a5d696355cc', 'adfab075-8409-5e14-a4b5-1ae1d32b30a0', NULL, 5, 5, '"That they may believe that Yahweh, the God of their fathers, the God of Abraham, the God of Isaac, and the God of Jacob, has appeared to you."'),
  ('317eeefb-5ed3-5a8a-a63a-70be8d4bbf3d', 'adfab075-8409-5e14-a4b5-1ae1d32b30a0', NULL, 6, 6, 'Yahweh said furthermore to him, "Now put your hand inside your cloak." He put his hand inside his cloak, and when he took it out, behold, his hand was leprous, as white as snow.'),
  ('51df72bb-6139-58fd-a7df-021c54245490', 'adfab075-8409-5e14-a4b5-1ae1d32b30a0', NULL, 7, 7, 'He said, "Put your hand inside your cloak again." He put his hand inside his cloak again, and when he took it out of his cloak, behold, it had turned again as his other flesh.'),
  ('9f6c1614-d044-5260-a72d-10f18aec64df', 'adfab075-8409-5e14-a4b5-1ae1d32b30a0', NULL, 8, 8, '"It will happen, if they will neither believe you nor listen to the voice of the first sign, that they will believe the voice of the latter sign.'),
  ('f56c131b-3689-568a-a7ba-a308da806f58', 'adfab075-8409-5e14-a4b5-1ae1d32b30a0', NULL, 9, 9, 'It will happen, if they will not believe even these two signs, neither listen to your voice, that you shall take of the water of the river, and pour it on the dry land. The water which you take out of the river will become blood on the dry land."')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('74b52e25-1d6a-58e7-aef7-3f2e32a4d5ad', 'adfab075-8409-5e14-a4b5-1ae1d32b30a0', NULL, 10, 10, 'Moses said to Yahweh, "O Lord, I am not eloquent, neither before now, nor since you have spoken to your servant; for I am slow of speech, and of a slow tongue."'),
  ('9f2f6b9a-64c7-5e29-a46f-717cf90c4d3c', 'adfab075-8409-5e14-a4b5-1ae1d32b30a0', NULL, 11, 11, 'Yahweh said to him, "Who made man''s mouth? Or who makes one mute, or deaf, or seeing, or blind? Isn''t it I, Yahweh?'),
  ('1f0d7709-f2a3-5499-a6df-7912ac999876', 'adfab075-8409-5e14-a4b5-1ae1d32b30a0', NULL, 12, 12, 'Now therefore go, and I will be with your mouth, and teach you what you shall speak."'),
  ('f0c2f2ec-8352-53fb-ac66-f1afc4125b27', 'adfab075-8409-5e14-a4b5-1ae1d32b30a0', NULL, 13, 13, 'He said, "Oh, Lord, please send someone else."'),
  ('a6a7e3d4-0cb8-5f4c-a701-7aec0756a4d1', 'adfab075-8409-5e14-a4b5-1ae1d32b30a0', NULL, 14, 14, 'The anger of Yahweh was kindled against Moses, and he said, "What about Aaron, your brother, the Levite? I know that he can speak well. Also, behold, he comes forth to meet you. When he sees you, he will be glad in his heart.'),
  ('e02a5ed6-e71b-5397-ad21-d4bf8ac3803f', 'adfab075-8409-5e14-a4b5-1ae1d32b30a0', NULL, 15, 15, 'You shall speak to him, and put the words in his mouth. I will be with your mouth, and with his mouth, and will teach you what you shall do.'),
  ('1ef3c8b5-6565-5739-a35e-09a9248f9e5d', 'adfab075-8409-5e14-a4b5-1ae1d32b30a0', NULL, 16, 16, 'He will be your spokesman to the people; and it will happen, that he will be to you a mouth, and you will be to him as God.'),
  ('6a7980a9-b040-5720-acef-a008f53ec535', 'adfab075-8409-5e14-a4b5-1ae1d32b30a0', NULL, 17, 17, 'You shall take this rod in your hand, with which you shall do the signs."'),
  ('0204a5fe-9ddb-5f00-a3ae-d978ec319c03', 'adfab075-8409-5e14-a4b5-1ae1d32b30a0', NULL, 18, 18, 'Moses went and returned to Jethro his father-in-law, and said to him, "Please let me go and return to my brothers who are in Egypt, and see whether they are still alive." Jethro said to Moses, "Go in peace."'),
  ('49e7d70c-839c-5876-a7c8-7bda66c28aa6', 'adfab075-8409-5e14-a4b5-1ae1d32b30a0', NULL, 19, 19, 'Yahweh said to Moses in Midian, "Go, return into Egypt; for all the men who sought your life are dead."'),
  ('a89427a7-4755-5298-a08d-07b1d8f48cf7', 'adfab075-8409-5e14-a4b5-1ae1d32b30a0', NULL, 20, 20, 'Moses took his wife and his sons, and set them on a donkey, and he returned to the land of Egypt. Moses took God''s rod in his hand.'),
  ('2b25dadc-37a6-564f-acf2-43fbc7c310cd', 'adfab075-8409-5e14-a4b5-1ae1d32b30a0', NULL, 21, 21, 'Yahweh said to Moses, "When you go back into Egypt, see that you do before Pharaoh all the wonders which I have put in your hand, but I will harden his heart and he will not let the people go.'),
  ('a46b380f-0a47-5070-a009-b343e68fcd51', 'adfab075-8409-5e14-a4b5-1ae1d32b30a0', NULL, 22, 22, 'You shall tell Pharaoh, ''Thus says Yahweh, Israel is my son, my firstborn,'),
  ('d8764e57-b431-5762-aa79-dd761b88b9ac', 'adfab075-8409-5e14-a4b5-1ae1d32b30a0', NULL, 23, 23, 'and I have said to you, "Let my son go, that he may serve me;" and you have refused to let him go. Behold, I will kill your son, your firstborn.''"'),
  ('84c56c01-4a37-567e-ab90-356610fd583a', 'adfab075-8409-5e14-a4b5-1ae1d32b30a0', NULL, 24, 24, 'It happened on the way at a lodging place, that Yahweh met Moses and wanted to kill him.'),
  ('5da548f0-41af-522b-a150-da5ea39cf6d7', 'adfab075-8409-5e14-a4b5-1ae1d32b30a0', NULL, 25, 25, 'Then Zipporah took a flint, and cut off the foreskin of her son, and cast it at his feet; and she said, "Surely you are a bridegroom of blood to me."'),
  ('c3a8e645-2f40-5571-ab3c-8092b4124fca', 'adfab075-8409-5e14-a4b5-1ae1d32b30a0', NULL, 26, 26, 'So he let him alone. Then she said, "You are a bridegroom of blood," because of the circumcision.'),
  ('c3bc03b2-7df2-584b-a118-ff0899193b7c', 'adfab075-8409-5e14-a4b5-1ae1d32b30a0', NULL, 27, 27, 'Yahweh said to Aaron, "Go into the wilderness to meet Moses." He went, and met him on God''s mountain, and kissed him.'),
  ('487f4777-62ee-58e1-ad73-6c35282d187b', 'adfab075-8409-5e14-a4b5-1ae1d32b30a0', NULL, 28, 28, 'Moses told Aaron all the words of Yahweh with which he had sent him, and all the signs with which he had instructed him.'),
  ('9852b34b-9ab1-5b2a-a294-9bc97b5a6102', 'adfab075-8409-5e14-a4b5-1ae1d32b30a0', NULL, 29, 29, 'Moses and Aaron went and gathered together all the elders of the children of Israel.'),
  ('450e659f-9ffa-56fb-a688-cc0dc2567cb7', 'adfab075-8409-5e14-a4b5-1ae1d32b30a0', NULL, 30, 30, 'Aaron spoke all the words which Yahweh had spoken to Moses, and did the signs in the sight of the people.'),
  ('85c264c0-bca9-58c4-a68e-e6b1f6358e48', 'adfab075-8409-5e14-a4b5-1ae1d32b30a0', NULL, 31, 31, 'The people believed, and when they heard that Yahweh had visited the children of Israel, and that he had seen their affliction, then they bowed their heads and worshiped.'),
  ('ae86a348-afb4-5d2f-ad30-e6c359f0fc0a', '1ea34752-8193-50f5-aa4f-f394f29458e4', NULL, 1, 1, 'Afterward Moses and Aaron came, and said to Pharaoh, "This is what Yahweh, the God of Israel, says, ''Let my people go, that they may hold a feast to me in the wilderness.''"'),
  ('9c8c1fdf-6b47-5b18-a1aa-cfb66979af23', '1ea34752-8193-50f5-aa4f-f394f29458e4', NULL, 2, 2, 'Pharaoh said, "Who is Yahweh, that I should listen to his voice to let Israel go? I don''t know Yahweh, and moreover I will not let Israel go."'),
  ('b6905d1d-ac7c-53f8-a4a9-a65aaf5cc4e5', '1ea34752-8193-50f5-aa4f-f394f29458e4', NULL, 3, 3, 'They said, "The God of the Hebrews has met with us. Please let us go three days'' journey into the wilderness, and sacrifice to Yahweh, our God, lest he fall on us with pestilence, or with the sword."'),
  ('2f67eddb-8fc1-5fef-ab70-b6da8e010709', '1ea34752-8193-50f5-aa4f-f394f29458e4', NULL, 4, 4, 'The king of Egypt said to them, "Why do you, Moses and Aaron, take the people from their work? Get back to your burdens!"'),
  ('50b36c8c-6df7-5811-a43f-07f929a81e8a', '1ea34752-8193-50f5-aa4f-f394f29458e4', NULL, 5, 5, 'Pharaoh said, "Behold, the people of the land are now many, and you make them rest from their burdens."'),
  ('d7374492-a954-5909-a15a-c77974778f59', '1ea34752-8193-50f5-aa4f-f394f29458e4', NULL, 6, 6, 'The same day Pharaoh commanded the taskmasters of the people, and their officers, saying,'),
  ('1f383d4c-9ff9-5c9d-a1d2-21520963856c', '1ea34752-8193-50f5-aa4f-f394f29458e4', NULL, 7, 7, '"You shall no longer give the people straw to make brick, as before. Let them go and gather straw for themselves.'),
  ('c6e41beb-478d-5edc-af87-9b32df43cbb9', '1ea34752-8193-50f5-aa4f-f394f29458e4', NULL, 8, 8, 'The number of the bricks, which they made before, you require from them. You shall not diminish anything of it, for they are idle; therefore they cry, saying, ''Let us go and sacrifice to our God.'''),
  ('7bdba111-7c8b-57ab-adb3-aa95a0cf77a3', '1ea34752-8193-50f5-aa4f-f394f29458e4', NULL, 9, 9, 'Let heavier work be laid on the men, that they may labor therein; and don''t let them pay any attention to lying words."'),
  ('9c089942-e717-5652-a58e-c5492111ae80', '1ea34752-8193-50f5-aa4f-f394f29458e4', NULL, 10, 10, 'The taskmasters of the people went out, and their officers, and they spoke to the people, saying, "This is what Pharaoh says: ''I will not give you straw.'),
  ('4853c82d-924b-5c03-a4bd-86e813990090', '1ea34752-8193-50f5-aa4f-f394f29458e4', NULL, 11, 11, 'Go yourselves, get straw where you can find it, for nothing of your work shall be diminished.''"'),
  ('34f9dc42-0b0f-504a-ad51-7a97b153e418', '1ea34752-8193-50f5-aa4f-f394f29458e4', NULL, 12, 12, 'So the people were scattered abroad throughout all the land of Egypt to gather stubble for straw.'),
  ('21fd781d-0f0a-5846-a3f8-0894d72c5187', '1ea34752-8193-50f5-aa4f-f394f29458e4', NULL, 13, 13, 'The taskmasters were urgent saying, "Fulfill your work quota daily, as when there was straw!"'),
  ('3f7cb0d1-1133-551e-a335-77f5e924f166', '1ea34752-8193-50f5-aa4f-f394f29458e4', NULL, 14, 14, 'The officers of the children of Israel, whom Pharaoh''s taskmasters had set over them, were beaten, and demanded, "Why haven''t you fulfilled your quota both yesterday and today, in making brick as before?"'),
  ('73d52666-3dcc-5773-a470-41cac7e7eb22', '1ea34752-8193-50f5-aa4f-f394f29458e4', NULL, 15, 15, 'Then the officers of the children of Israel came and cried to Pharaoh, saying, "Why do you deal this way with your servants?'),
  ('523349c2-e898-5915-a6c8-b9241ec6bb76', '1ea34752-8193-50f5-aa4f-f394f29458e4', NULL, 16, 16, 'No straw is given to your servants, and they tell us, ''Make brick!'' and behold, your servants are beaten; but the fault is in your own people."'),
  ('675826eb-f819-5a7a-a0a4-71a7057c3725', '1ea34752-8193-50f5-aa4f-f394f29458e4', NULL, 17, 17, 'But he said, "You are idle! You are idle! Therefore you say, ''Let us go and sacrifice to Yahweh.'''),
  ('434fc492-edcb-5cd9-a88b-8861e3dfa33b', '1ea34752-8193-50f5-aa4f-f394f29458e4', NULL, 18, 18, 'Go therefore now, and work, for no straw shall be given to you, yet you shall deliver the same number of bricks!"'),
  ('aba7f1b5-0f7f-5d54-ab2e-91f143d90197', '1ea34752-8193-50f5-aa4f-f394f29458e4', NULL, 19, 19, 'The officers of the children of Israel saw that they were in trouble, when it was said, "You shall not diminish anything from your daily quota of bricks!"'),
  ('97340a40-136e-51f7-aa0f-f7d56357f803', '1ea34752-8193-50f5-aa4f-f394f29458e4', NULL, 20, 20, 'They met Moses and Aaron, who stood in the way, as they came forth from Pharaoh:'),
  ('20bc930a-e589-5b77-a29a-a2db03ff8d56', '1ea34752-8193-50f5-aa4f-f394f29458e4', NULL, 21, 21, 'and they said to them, "May Yahweh look at you, and judge, because you have made us a stench to be abhorred in the eyes of Pharaoh, and in the eyes of his servants, to put a sword in their hand to kill us."'),
  ('4c6bb06a-c33f-53b0-aef1-fa4f75ae97bc', '1ea34752-8193-50f5-aa4f-f394f29458e4', NULL, 22, 22, 'Moses returned to Yahweh, and said, "Lord, why have you brought trouble on this people? Why is it that you have sent me?'),
  ('575a0956-519c-5cc6-a980-271ab03dcd47', '1ea34752-8193-50f5-aa4f-f394f29458e4', NULL, 23, 23, 'For since I came to Pharaoh to speak in your name, he has brought trouble on this people; neither have you delivered your people at all."'),
  ('cf62dbec-a967-5d0c-a8c5-d945b579988e', 'c84cf184-33cb-5d92-aa95-214ec0934f16', NULL, 1, 1, 'Yahweh said to Moses, "Now you shall see what I will do to Pharaoh, for by a strong hand he shall let them go, and by a strong hand he shall drive them out of his land."'),
  ('d2127b2c-90c0-56b5-a1d4-3ba5ceb3b170', 'c84cf184-33cb-5d92-aa95-214ec0934f16', NULL, 2, 2, 'God spoke to Moses, and said to him, "I am Yahweh;'),
  ('5005a372-06bc-5385-a5e9-4621280fb1aa', 'c84cf184-33cb-5d92-aa95-214ec0934f16', NULL, 3, 3, 'and I appeared to Abraham, to Isaac, and to Jacob, as God Almighty; but by my name Yahweh I was not known to them.'),
  ('f8469284-17f0-5199-a7a1-1883f3c849d9', 'c84cf184-33cb-5d92-aa95-214ec0934f16', NULL, 4, 4, 'I have also established my covenant with them, to give them the land of Canaan, the land of their travels, in which they lived as aliens.'),
  ('b6772ee7-e821-5ee4-ade5-da712583eee2', 'c84cf184-33cb-5d92-aa95-214ec0934f16', NULL, 5, 5, 'Moreover I have heard the groaning of the children of Israel, whom the Egyptians keep in bondage, and I have remembered my covenant.'),
  ('e9e62edb-9afe-52b1-a8d7-43e28e3d4313', 'c84cf184-33cb-5d92-aa95-214ec0934f16', NULL, 6, 6, 'Therefore tell the children of Israel, ''I am Yahweh, and I will bring you out from under the burdens of the Egyptians, and I will rid you out of their bondage, and I will redeem you with an outstretched arm, and with great judgments:'),
  ('62893818-1640-53ee-a0bf-fc31273b9ece', 'c84cf184-33cb-5d92-aa95-214ec0934f16', NULL, 7, 7, 'and I will take you to me for a people, and I will be to you a God; and you shall know that I am Yahweh your God, who brings you out from under the burdens of the Egyptians.'),
  ('136164bd-dbfe-5e9c-aae9-5fccd56618f8', 'c84cf184-33cb-5d92-aa95-214ec0934f16', NULL, 8, 8, 'I will bring you into the land which I swore to give to Abraham, to Isaac, and to Jacob; and I will give it to you for a heritage: I am Yahweh.''"'),
  ('82b70c90-3214-587f-a3e9-01b51511d303', 'c84cf184-33cb-5d92-aa95-214ec0934f16', NULL, 9, 9, 'Moses spoke so to the children of Israel, but they didn''t listen to Moses for anguish of spirit, and for cruel bondage.'),
  ('06b08c7b-aa0c-546f-ad47-2c6b3ed1c48b', 'c84cf184-33cb-5d92-aa95-214ec0934f16', NULL, 10, 10, 'Yahweh spoke to Moses, saying,'),
  ('8c957e6c-2d4b-52d9-a9f0-b9b37608716f', 'c84cf184-33cb-5d92-aa95-214ec0934f16', NULL, 11, 11, '"Go in, speak to Pharaoh king of Egypt, that he let the children of Israel go out of his land."'),
  ('169b943f-37b3-54f6-a440-e0244e965682', 'c84cf184-33cb-5d92-aa95-214ec0934f16', NULL, 12, 12, 'Moses spoke before Yahweh, saying, "Behold, the children of Israel haven''t listened to me. How then shall Pharaoh listen to me, who am of uncircumcised lips?"'),
  ('8f676b8c-dc16-5fba-a413-2e3e71788086', 'c84cf184-33cb-5d92-aa95-214ec0934f16', NULL, 13, 13, 'Yahweh spoke to Moses and to Aaron, and gave them a command to the children of Israel, and to Pharaoh king of Egypt, to bring the children of Israel out of the land of Egypt.'),
  ('a1634816-a990-5aaa-a5e8-e1cb9e2a9bf0', 'c84cf184-33cb-5d92-aa95-214ec0934f16', NULL, 14, 14, 'These are the heads of their fathers'' houses. The sons of Reuben the firstborn of Israel: Hanoch, and Pallu, Hezron, and Carmi; these are the families of Reuben.'),
  ('5af9ceeb-e57e-5659-a7ea-62210dc2991f', 'c84cf184-33cb-5d92-aa95-214ec0934f16', NULL, 15, 15, 'The sons of Simeon: Jemuel, and Jamin, and Ohad, and Jachin, and Zohar, and Shaul the son of a Canaanite woman; these are the families of Simeon.'),
  ('6e5f5c47-736f-5f32-ad52-bafb5bcdbb5d', 'c84cf184-33cb-5d92-aa95-214ec0934f16', NULL, 16, 16, 'These are the names of the sons of Levi according to their generations: Gershon, and Kohath, and Merari; and the years of the life of Levi were one hundred thirty-seven years.'),
  ('5a856339-7c95-5678-a2ba-78d21c83f5c7', 'c84cf184-33cb-5d92-aa95-214ec0934f16', NULL, 17, 17, 'The sons of Gershon: Libni and Shimei, according to their families.'),
  ('c23bcff0-16d6-5ff1-aee7-58559096c59d', 'c84cf184-33cb-5d92-aa95-214ec0934f16', NULL, 18, 18, 'The sons of Kohath: Amram, and Izhar, and Hebron, and Uzziel; and the years of the life of Kohath were one hundred thirty-three years.'),
  ('648572b5-c074-5184-a897-0f18c9c321cd', 'c84cf184-33cb-5d92-aa95-214ec0934f16', NULL, 19, 19, 'The sons of Merari: Mahli and Mushi. These are the families of the Levites according to their generations.'),
  ('57788e63-2653-5862-add7-ecdd345e91aa', 'c84cf184-33cb-5d92-aa95-214ec0934f16', NULL, 20, 20, 'Amram took Jochebed his father''s sister to himself as wife; and she bore him Aaron and Moses: and the years of the life of Amram were a hundred and thirty-seven years.'),
  ('0e686224-5a57-5ed6-a989-4d1a7749bcb8', 'c84cf184-33cb-5d92-aa95-214ec0934f16', NULL, 21, 21, 'The sons of Izhar: Korah, and Nepheg, and Zichri.'),
  ('dc744da4-9f2a-59fd-ae6a-a658e80c23f0', 'c84cf184-33cb-5d92-aa95-214ec0934f16', NULL, 22, 22, 'The sons of Uzziel: Mishael, and Elzaphan, and Sithri.'),
  ('5fee5563-6c82-513a-a406-60ced3d627aa', 'c84cf184-33cb-5d92-aa95-214ec0934f16', NULL, 23, 23, 'Aaron took Elisheba, the daughter of Amminadab, the sister of Nahshon, as his wife; and she bore him Nadab and Abihu, Eleazar and Ithamar.'),
  ('5d28b15d-e687-525f-a94e-191f76178467', 'c84cf184-33cb-5d92-aa95-214ec0934f16', NULL, 24, 24, 'The sons of Korah: Assir, and Elkanah, and Abiasaph; these are the families of the Korahites.'),
  ('4fdee266-5887-5fac-a5cb-bae9e25ed47e', 'c84cf184-33cb-5d92-aa95-214ec0934f16', NULL, 25, 25, 'Eleazar Aaron''s son took one of the daughters of Putiel as his wife; and she bore him Phinehas. These are the heads of the fathers'' houses of the Levites according to their families.'),
  ('568eb3f9-68d3-531f-a793-f456784d24e8', 'c84cf184-33cb-5d92-aa95-214ec0934f16', NULL, 26, 26, 'These are that Aaron and Moses, to whom Yahweh said, "Bring out the children of Israel from the land of Egypt according to their armies."'),
  ('5590237c-9b12-51e8-ab06-75968775a4bc', 'c84cf184-33cb-5d92-aa95-214ec0934f16', NULL, 27, 27, 'These are those who spoke to Pharaoh king of Egypt, to bring out the children of Israel from Egypt. These are that Moses and Aaron.'),
  ('747344a2-069d-56ca-a266-47f2de17fd3e', 'c84cf184-33cb-5d92-aa95-214ec0934f16', NULL, 28, 28, 'It happened on the day when Yahweh spoke to Moses in the land of Egypt,'),
  ('cb6c60be-4752-5a89-a364-a06c005b69c5', 'c84cf184-33cb-5d92-aa95-214ec0934f16', NULL, 29, 29, 'that Yahweh spoke to Moses, saying, "I am Yahweh. Speak to Pharaoh king of Egypt all that I speak to you."'),
  ('5d2215f2-6753-5049-a01a-29068831651d', 'c84cf184-33cb-5d92-aa95-214ec0934f16', NULL, 30, 30, 'Moses said before Yahweh, "Behold, I am of uncircumcised lips, and how shall Pharaoh listen to me?"'),
  ('7d4260b2-1d32-5aed-a909-3bcfbfc5717d', '6a672923-b799-5ad6-ac72-83e404828173', NULL, 1, 1, 'Yahweh said to Moses, "Behold, I have made you as God to Pharaoh; and Aaron your brother shall be your prophet.'),
  ('8fc7326e-9473-5f4a-a2fa-73b5e7bb4091', '6a672923-b799-5ad6-ac72-83e404828173', NULL, 2, 2, 'You shall speak all that I command you; and Aaron your brother shall speak to Pharaoh, that he let the children of Israel go out of his land.'),
  ('c4ea0e7e-dc2e-5ae0-afa5-968aee7cd1ad', '6a672923-b799-5ad6-ac72-83e404828173', NULL, 3, 3, 'I will harden Pharaoh''s heart, and multiply my signs and my wonders in the land of Egypt.'),
  ('946d4e38-ace2-5007-a161-212f8c98573d', '6a672923-b799-5ad6-ac72-83e404828173', NULL, 4, 4, 'But Pharaoh will not listen to you, and I will lay my hand on Egypt, and bring forth my armies, my people the children of Israel, out of the land of Egypt by great judgments.'),
  ('a4a6b2cf-6344-51a7-a810-cf188250c409', '6a672923-b799-5ad6-ac72-83e404828173', NULL, 5, 5, 'The Egyptians shall know that I am Yahweh, when I stretch forth my hand on Egypt, and bring out the children of Israel from among them."'),
  ('2b7d1743-b2b0-5779-a359-0ccc6c9fe19d', '6a672923-b799-5ad6-ac72-83e404828173', NULL, 6, 6, 'Moses and Aaron did so. As Yahweh commanded them, so they did.'),
  ('d8101ab4-03c7-5b53-a84c-71916140bc2e', '6a672923-b799-5ad6-ac72-83e404828173', NULL, 7, 7, 'Moses was eighty years old, and Aaron eighty-three years old, when they spoke to Pharaoh.'),
  ('921762f0-7c93-5c7a-a22e-e9ce9c20f375', '6a672923-b799-5ad6-ac72-83e404828173', NULL, 8, 8, 'Yahweh spoke to Moses and to Aaron, saying,'),
  ('79b17853-bb4d-5aba-a229-d122119ebc02', '6a672923-b799-5ad6-ac72-83e404828173', NULL, 9, 9, '"When Pharaoh speaks to you, saying, ''Perform a miracle!'' then you shall tell Aaron, ''Take your rod, and cast it down before Pharaoh, that it become a serpent.''"'),
  ('275d4de9-b6ef-5f9e-a1f1-cd3319d45863', '6a672923-b799-5ad6-ac72-83e404828173', NULL, 10, 10, 'Moses and Aaron went in to Pharaoh, and they did so, as Yahweh had commanded: and Aaron cast down his rod before Pharaoh and before his servants, and it became a serpent.'),
  ('a94f433b-9dee-59ad-a56f-8c271d09ba25', '6a672923-b799-5ad6-ac72-83e404828173', NULL, 11, 11, 'Then Pharaoh also called for the wise men and the sorcerers. They also, the magicians of Egypt, did the same thing with their enchantments.'),
  ('78bcb6b0-fb67-5acb-a994-7354ea1afd9a', '6a672923-b799-5ad6-ac72-83e404828173', NULL, 12, 12, 'For they each cast down their rods, and they became serpents: but Aaron''s rod swallowed up their rods.'),
  ('f4f1c379-8535-5702-a26b-1a8f919593f9', '6a672923-b799-5ad6-ac72-83e404828173', NULL, 13, 13, 'Pharaoh''s heart was hardened, and he didn''t listen to them; as Yahweh had spoken.'),
  ('0bf3132c-88ec-52b1-a29f-dcb4c0e9527f', '6a672923-b799-5ad6-ac72-83e404828173', NULL, 14, 14, 'Yahweh said to Moses, "Pharaoh''s heart is stubborn. He refuses to let the people go.'),
  ('1d081774-a6e1-52b9-a78a-f3bb14b54c6e', '6a672923-b799-5ad6-ac72-83e404828173', NULL, 15, 15, 'Go to Pharaoh in the morning. Behold, he goes out to the water; and you shall stand by the river''s bank to meet him; and the rod which was turned to a serpent you shall take in your hand.'),
  ('603b6723-eafb-57ab-a9a3-21e293b37172', '6a672923-b799-5ad6-ac72-83e404828173', NULL, 16, 16, 'You shall tell him, ''Yahweh, the God of the Hebrews, has sent me to you, saying, "Let my people go, that they may serve me in the wilderness:" and behold, until now you haven''t listened.'),
  ('7ee7a2ed-ffe4-5bdc-a459-d6a5af80ca8f', '6a672923-b799-5ad6-ac72-83e404828173', NULL, 17, 17, 'Thus says Yahweh, "In this you shall know that I am Yahweh. Behold, I will strike with the rod that is in my hand on the waters which are in the river, and they shall be turned to blood.'),
  ('2e3c7646-eea9-586e-a989-5a96e8bedc01', '6a672923-b799-5ad6-ac72-83e404828173', NULL, 18, 18, 'The fish that are in the river shall die, and the river shall become foul; and the Egyptians shall loathe to drink water from the river."''"'),
  ('96aa8665-f322-53a7-adce-134687ec8306', '6a672923-b799-5ad6-ac72-83e404828173', NULL, 19, 19, 'Yahweh said to Moses, "Tell Aaron, ''Take your rod, and stretch out your hand over the waters of Egypt, over their rivers, over their streams, and over their pools, and over all their ponds of water, that they may become blood; and there shall be blood throughout all the land of Egypt, both in vessels of wood and in vessels of stone.''"'),
  ('47f1f191-2ad0-516c-a74d-42ed1777f81f', '6a672923-b799-5ad6-ac72-83e404828173', NULL, 20, 20, 'Moses and Aaron did so, as Yahweh commanded; and he lifted up the rod, and struck the waters that were in the river, in the sight of Pharaoh, and in the sight of his servants; and all the waters that were in the river were turned to blood.'),
  ('4e91095c-ae44-5eb7-a71b-6c18a0c4275a', '6a672923-b799-5ad6-ac72-83e404828173', NULL, 21, 21, 'The fish that were in the river died; and the river became foul, and the Egyptians couldn''t drink water from the river; and the blood was throughout all the land of Egypt.'),
  ('c4439899-002f-50e4-afe3-988385128f4b', '6a672923-b799-5ad6-ac72-83e404828173', NULL, 22, 22, 'The magicians of Egypt did the same thing with their enchantments; and Pharaoh''s heart was hardened, and he didn''t listen to them; as Yahweh had spoken.'),
  ('3f673e4a-93b0-5191-a059-8145e8eacff8', '6a672923-b799-5ad6-ac72-83e404828173', NULL, 23, 23, 'Pharaoh turned and went into his house, neither did he lay even this to heart.'),
  ('d167d0ae-eab4-5d6a-a18b-556c3a07e7f9', '6a672923-b799-5ad6-ac72-83e404828173', NULL, 24, 24, 'All the Egyptians dug around the river for water to drink; for they couldn''t drink of the water of the river.'),
  ('3738d9a3-e480-5f98-a39d-9a670b11c17c', '6a672923-b799-5ad6-ac72-83e404828173', NULL, 25, 25, 'Seven days were fulfilled, after Yahweh had struck the river.'),
  ('044afa34-2c7e-515b-a8fc-ffb3959c7c49', '7c119c9f-9fde-5184-a23c-9330b956b4d5', NULL, 1, 1, 'Yahweh spoke to Moses, Go in to Pharaoh, and tell him, "This is what Yahweh says, ''Let my people go, that they may serve me.'),
  ('4cbc4004-3089-53a6-ae64-24696a1bc6cb', '7c119c9f-9fde-5184-a23c-9330b956b4d5', NULL, 2, 2, 'If you refuse to let them go, behold, I will plague all your borders with frogs:'),
  ('edf73721-3bc1-53f2-a983-837269662b81', '7c119c9f-9fde-5184-a23c-9330b956b4d5', NULL, 3, 3, 'and the river shall swarm with frogs, which shall go up and come into your house, and into your bedroom, and on your bed, and into the house of your servants, and on your people, and into your ovens, and into your kneading troughs:'),
  ('1405293b-37c5-5436-a737-3dbc197dcc48', '7c119c9f-9fde-5184-a23c-9330b956b4d5', NULL, 4, 4, 'and the frogs shall come up both on you, and on your people, and on all your servants.''"'),
  ('28cec94a-5281-5dab-a7cb-656e18bd51af', '7c119c9f-9fde-5184-a23c-9330b956b4d5', NULL, 5, 5, 'Yahweh said to Moses, "Tell Aaron, ''Stretch forth your hand with your rod over the rivers, over the streams, and over the pools, and cause frogs to come up on the land of Egypt.''"'),
  ('3dba3bb6-8673-58ad-a910-179d5531b569', '7c119c9f-9fde-5184-a23c-9330b956b4d5', NULL, 6, 6, 'Aaron stretched out his hand over the waters of Egypt; and the frogs came up, and covered the land of Egypt.'),
  ('ad9eb6b6-a5ce-5330-a089-98e290f4de60', '7c119c9f-9fde-5184-a23c-9330b956b4d5', NULL, 7, 7, 'The magicians did the same thing with their enchantments, and brought up frogs on the land of Egypt.'),
  ('ccd78ada-b4d9-5894-a75a-7e75dd2b97f7', '7c119c9f-9fde-5184-a23c-9330b956b4d5', NULL, 8, 8, 'Then Pharaoh called for Moses and Aaron, and said, "Entreat Yahweh, that he take away the frogs from me, and from my people; and I will let the people go, that they may sacrifice to Yahweh."'),
  ('336e88cc-44ca-5440-aa07-f883b943e149', '7c119c9f-9fde-5184-a23c-9330b956b4d5', NULL, 9, 9, 'Moses said to Pharaoh, "I give you the honor of setting the time that I should pray for you, and for your servants, and for your people, that the frogs be destroyed from you and your houses, and remain in the river only."'),
  ('d48ae1d1-3405-5db4-ac38-9b2327e6879e', '7c119c9f-9fde-5184-a23c-9330b956b4d5', NULL, 10, 10, 'He said, "Tomorrow." He said, "Be it according to your word, that you may know that there is none like Yahweh our God.'),
  ('8d29c79d-a76b-5ea3-a78f-9aa5cf93cc3a', '7c119c9f-9fde-5184-a23c-9330b956b4d5', NULL, 11, 11, 'The frogs shall depart from you, and from your houses, and from your servants, and from your people. They shall remain in the river only."'),
  ('15c9c689-9a6e-5abd-a86a-be16a25271b3', '7c119c9f-9fde-5184-a23c-9330b956b4d5', NULL, 12, 12, 'Moses and Aaron went out from Pharaoh, and Moses cried to Yahweh concerning the frogs which he had brought on Pharaoh.'),
  ('2219b159-3416-5a1d-ac7b-7293b1a9641e', '7c119c9f-9fde-5184-a23c-9330b956b4d5', NULL, 13, 13, 'Yahweh did according to the word of Moses, and the frogs died out of the houses, out of the courts, and out of the fields.'),
  ('20f1bd8e-6558-56f6-abc1-66bb5ff7b07f', '7c119c9f-9fde-5184-a23c-9330b956b4d5', NULL, 14, 14, 'They gathered them together in heaps, and the land stank.'),
  ('e4a698e8-473c-576e-a18f-1f333dcbe9ee', '7c119c9f-9fde-5184-a23c-9330b956b4d5', NULL, 15, 15, 'But when Pharaoh saw that there was a respite, he hardened his heart, and didn''t listen to them, as Yahweh had spoken.'),
  ('efc4985a-ebab-5a41-aeff-44d515ccf0db', '7c119c9f-9fde-5184-a23c-9330b956b4d5', NULL, 16, 16, 'Yahweh said to Moses, "Tell Aaron, ''Stretch out your rod, and strike the dust of the earth, that it may become lice throughout all the land of Egypt.''"'),
  ('362fff52-5905-5090-ab34-cda1834509dc', '7c119c9f-9fde-5184-a23c-9330b956b4d5', NULL, 17, 17, 'They did so; and Aaron stretched out his hand with his rod, and struck the dust of the earth, and there were lice on man, and on animal; all the dust of the earth became lice throughout all the land of Egypt.'),
  ('0ebdfaf9-61ba-5630-a524-7b6f1b506548', '7c119c9f-9fde-5184-a23c-9330b956b4d5', NULL, 18, 18, 'The magicians tried with their enchantments to bring forth lice, but they couldn''t. There were lice on man, and on animal.'),
  ('351c8521-7abd-5df0-ae77-6a3a81167b74', '7c119c9f-9fde-5184-a23c-9330b956b4d5', NULL, 19, 19, 'Then the magicians said to Pharaoh, "This is the finger of God:" and Pharaoh''s heart was hardened, and he didn''t listen to them; as Yahweh had spoken.'),
  ('ec5e9202-7d5e-50d4-aa67-2ced3c9d7110', '7c119c9f-9fde-5184-a23c-9330b956b4d5', NULL, 20, 20, 'Yahweh said to Moses, "Rise up early in the morning, and stand before Pharaoh; behold, he comes forth to the water; and tell him, ''This is what Yahweh says, "Let my people go, that they may serve me.'),
  ('07b71dcc-a9de-5560-acf8-2e214e3070b9', '7c119c9f-9fde-5184-a23c-9330b956b4d5', NULL, 21, 21, 'Else, if you will not let my people go, behold, I will send swarms of flies on you, and on your servants, and on your people, and into your houses: and the houses of the Egyptians shall be full of swarms of flies, and also the ground whereon they are.'),
  ('f9e7ec53-daba-5e3e-aa0c-ef68c97b2b52', '7c119c9f-9fde-5184-a23c-9330b956b4d5', NULL, 22, 22, 'I will set apart in that day the land of Goshen, in which my people dwell, that no swarms of flies shall be there; to the end you may know that I am Yahweh in the midst of the earth.'),
  ('f71099a1-71fd-5548-afab-59caecb6dc06', '7c119c9f-9fde-5184-a23c-9330b956b4d5', NULL, 23, 23, 'I will put a division between my people and your people: by tomorrow shall this sign be."''"'),
  ('038a6b2e-543c-5846-ae7e-b77489c0366b', '7c119c9f-9fde-5184-a23c-9330b956b4d5', NULL, 24, 24, 'Yahweh did so; and there came grievous swarms of flies into the house of Pharaoh, and into his servants'' houses: and in all the land of Egypt the land was corrupted by reason of the swarms of flies.'),
  ('8e026327-843f-5f79-ab10-547b737186cd', '7c119c9f-9fde-5184-a23c-9330b956b4d5', NULL, 25, 25, 'Pharaoh called for Moses and for Aaron, and said, "Go, sacrifice to your God in the land!"'),
  ('2700a380-d375-5c14-af7a-74d9a29c92ed', '7c119c9f-9fde-5184-a23c-9330b956b4d5', NULL, 26, 26, 'Moses said, "It isn''t appropriate to do so; for we shall sacrifice the abomination of the Egyptians to Yahweh our God. Behold, shall we sacrifice the abomination of the Egyptians before their eyes, and won''t they stone us?'),
  ('f60e58f4-4d0f-5257-a433-73e5f6729674', '7c119c9f-9fde-5184-a23c-9330b956b4d5', NULL, 27, 27, 'We will go three days'' journey into the wilderness, and sacrifice to Yahweh our God, as he shall command us."'),
  ('0bebc1a1-dc2e-5027-a9d5-2d157598090f', '7c119c9f-9fde-5184-a23c-9330b956b4d5', NULL, 28, 28, 'Pharaoh said, "I will let you go, that you may sacrifice to Yahweh your God in the wilderness, only you shall not go very far away. Pray for me."'),
  ('56ed15b6-7a58-596f-a0eb-31e935ded942', '7c119c9f-9fde-5184-a23c-9330b956b4d5', NULL, 29, 29, 'Moses said, "Behold, I go out from you, and I will pray to Yahweh that the swarms of flies may depart from Pharaoh, from his servants, and from his people, tomorrow; only don''t let Pharaoh deal deceitfully any more in not letting the people go to sacrifice to Yahweh."'),
  ('8ca3ba7a-7f02-553a-a503-e206dfb7dee7', '7c119c9f-9fde-5184-a23c-9330b956b4d5', NULL, 30, 30, 'Moses went out from Pharaoh, and prayed to Yahweh.'),
  ('ab03c40c-8cff-5e5c-a91b-62336b83938e', '7c119c9f-9fde-5184-a23c-9330b956b4d5', NULL, 31, 31, 'Yahweh did according to the word of Moses, and he removed the swarms of flies from Pharaoh, from his servants, and from his people. There remained not one.'),
  ('d5772bdb-2683-56a9-a398-ff62a9172cfe', '7c119c9f-9fde-5184-a23c-9330b956b4d5', NULL, 32, 32, 'Pharaoh hardened his heart this time also, and he didn''t let the people go.'),
  ('74812c0d-01e9-521b-abbb-ffa5facddec5', '57cebd86-52fa-597c-a13a-8f36d16c1bf1', NULL, 1, 1, 'Then Yahweh said to Moses, "Go in to Pharaoh, and tell him, ''This is what Yahweh, the God of the Hebrews, says: "Let my people go, that they may serve me.'),
  ('629f3b9c-5c6c-58f8-af73-ad2fef2f99a9', '57cebd86-52fa-597c-a13a-8f36d16c1bf1', NULL, 2, 2, 'For if you refuse to let them go, and hold them still,'),
  ('1210156e-c5d8-58f3-a572-f1a58b8ffcec', '57cebd86-52fa-597c-a13a-8f36d16c1bf1', NULL, 3, 3, 'behold, the hand of Yahweh is on your livestock which are in the field, on the horses, on the donkeys, on the camels, on the herds, and on the flocks with a very grievous pestilence.'),
  ('8daa97e1-0bf8-5296-a5e7-d6e96eb6af05', '57cebd86-52fa-597c-a13a-8f36d16c1bf1', NULL, 4, 4, 'Yahweh will make a distinction between the livestock of Israel and the livestock of Egypt; and nothing shall die of all that belongs to the children of Israel."''"'),
  ('7d68c881-b22f-5245-a3dc-cf39bcd4a806', '57cebd86-52fa-597c-a13a-8f36d16c1bf1', NULL, 5, 5, 'Yahweh appointed a set time, saying, "Tomorrow Yahweh shall do this thing in the land."'),
  ('ace4a24d-9693-5e7c-a9a0-92284d78ae66', '57cebd86-52fa-597c-a13a-8f36d16c1bf1', NULL, 6, 6, 'Yahweh did that thing on the next day; and all the livestock of Egypt died, but of the livestock of the children of Israel, not one died.'),
  ('1ca3b85c-079e-5135-ad48-354c166c4648', '57cebd86-52fa-597c-a13a-8f36d16c1bf1', NULL, 7, 7, 'Pharaoh sent, and, behold, there was not so much as one of the livestock of the Israelites dead. But the heart of Pharaoh was stubborn, and he didn''t let the people go.'),
  ('31976cf5-507e-541a-a4ad-81292eee6b17', '57cebd86-52fa-597c-a13a-8f36d16c1bf1', NULL, 8, 8, 'Yahweh said to Moses and to Aaron, "Take to you handfuls of ashes of the furnace, and let Moses sprinkle it toward the sky in the sight of Pharaoh.'),
  ('1231cbf5-c29b-5a70-af3f-a74a8887003a', '57cebd86-52fa-597c-a13a-8f36d16c1bf1', NULL, 9, 9, 'It shall become small dust over all the land of Egypt, and shall be a boil breaking forth with boils on man and on animal, throughout all the land of Egypt."'),
  ('e6b33c85-ae98-5fe6-a397-3048d508d2ec', '57cebd86-52fa-597c-a13a-8f36d16c1bf1', NULL, 10, 10, 'They took ashes of the furnace, and stood before Pharaoh; and Moses sprinkled it up toward the sky; and it became a boil breaking forth with boils on man and on animal.'),
  ('c9847d82-acd6-5fc5-a003-68f5f24dd10a', '57cebd86-52fa-597c-a13a-8f36d16c1bf1', NULL, 11, 11, 'The magicians couldn''t stand before Moses because of the boils; for the boils were on the magicians, and on all the Egyptians.'),
  ('dcff6a39-2d58-59bc-a490-03b8d472149f', '57cebd86-52fa-597c-a13a-8f36d16c1bf1', NULL, 12, 12, 'Yahweh hardened the heart of Pharaoh, and he didn''t listen to them, as Yahweh had spoken to Moses.'),
  ('ee446da2-6cb9-5983-ae1b-7eb77e34e44b', '57cebd86-52fa-597c-a13a-8f36d16c1bf1', NULL, 13, 13, 'Yahweh said to Moses, "Rise up early in the morning, and stand before Pharaoh, and tell him, ''This is what Yahweh, the God of the Hebrews, says: "Let my people go, that they may serve me.'),
  ('2538cead-7523-5acf-a922-db31c6f5d7ce', '57cebd86-52fa-597c-a13a-8f36d16c1bf1', NULL, 14, 14, 'For this time I will send all my plagues against your heart, against your officials, and against your people; that you may know that there is none like me in all the earth.'),
  ('c346fe3b-b993-5591-af83-fede8ca97f5c', '57cebd86-52fa-597c-a13a-8f36d16c1bf1', NULL, 15, 15, 'For now I would have put forth my hand, and struck you and your people with pestilence, and you would have been cut off from the earth;'),
  ('f277b4be-ee7f-552d-ac84-b5f8cce0e65f', '57cebd86-52fa-597c-a13a-8f36d16c1bf1', NULL, 16, 16, 'but indeed for this cause I have made you stand: to show you my power, and that my name may be declared throughout all the earth;'),
  ('53246354-f574-5efe-a617-081a077e0f23', '57cebd86-52fa-597c-a13a-8f36d16c1bf1', NULL, 17, 17, 'as you still exalt yourself against my people, that you won''t let them go.'),
  ('9eb45930-d0fb-5cd3-a55b-9870be091d7e', '57cebd86-52fa-597c-a13a-8f36d16c1bf1', NULL, 18, 18, 'Behold, tomorrow about this time I will cause it to rain a very grievous hail, such as has not been in Egypt since the day it was founded even until now.'),
  ('62f38218-6cb8-5ccb-aedb-e758bb9dc4f7', '57cebd86-52fa-597c-a13a-8f36d16c1bf1', NULL, 19, 19, 'Now therefore command that all of your livestock and all that you have in the field be brought into shelter. Every man and animal that is found in the field, and isn''t brought home, the hail shall come down on them, and they shall die."''"'),
  ('ea9c6b49-9c7f-5300-af8e-d9557654b866', '57cebd86-52fa-597c-a13a-8f36d16c1bf1', NULL, 20, 20, 'Those who feared the word of Yahweh among the servants of Pharaoh made their servants and their livestock flee into the houses.'),
  ('c00c1fc4-e819-534c-a464-7b6532a60f37', '57cebd86-52fa-597c-a13a-8f36d16c1bf1', NULL, 21, 21, 'Whoever didn''t respect the word of Yahweh left his servants and his livestock in the field.'),
  ('f728adb5-d70b-54d0-aad2-5e9b9968dbbd', '57cebd86-52fa-597c-a13a-8f36d16c1bf1', NULL, 22, 22, 'Yahweh said to Moses, "Stretch forth your hand toward the sky, that there may be hail in all the land of Egypt, on man, and on animal, and on every herb of the field, throughout the land of Egypt."'),
  ('7441f2e7-098d-52ed-ad21-d86c10d51372', '57cebd86-52fa-597c-a13a-8f36d16c1bf1', NULL, 23, 23, 'Moses stretched forth his rod toward the heavens, and Yahweh sent thunder, hail, and lightning flashed down to the earth. Yahweh rained hail on the land of Egypt.'),
  ('598898c2-bb87-5a38-ae19-0f163512efe2', '57cebd86-52fa-597c-a13a-8f36d16c1bf1', NULL, 24, 24, 'So there was very severe hail, and lightning mixed with the hail, such as had not been in all the land of Egypt since it became a nation.'),
  ('3dbe5cad-5a2e-5e52-ac2f-163e19832b58', '57cebd86-52fa-597c-a13a-8f36d16c1bf1', NULL, 25, 25, 'The hail struck throughout all the land of Egypt all that was in the field, both man and animal; and the hail struck every herb of the field, and broke every tree of the field.'),
  ('52739e58-2cae-5c90-a0d3-a15a204ab40c', '57cebd86-52fa-597c-a13a-8f36d16c1bf1', NULL, 26, 26, 'Only in the land of Goshen, where the children of Israel were, there was no hail.'),
  ('41cbb737-287b-50a2-a4b3-2502efc53ec8', '57cebd86-52fa-597c-a13a-8f36d16c1bf1', NULL, 27, 27, 'Pharaoh sent, and called for Moses and Aaron, and said to them, "I have sinned this time. Yahweh is righteous, and I and my people are wicked.'),
  ('c63097cd-fa82-5fe3-a3f4-194fac34bf37', '57cebd86-52fa-597c-a13a-8f36d16c1bf1', NULL, 28, 28, 'Pray to Yahweh; for there has been enough of mighty thunderings and hail. I will let you go, and you shall stay no longer."'),
  ('4e50cc90-0b82-53b0-a1d8-e4bbcf7cccb2', '57cebd86-52fa-597c-a13a-8f36d16c1bf1', NULL, 29, 29, 'Moses said to him, "As soon as I have gone out of the city, I will spread abroad my hands to Yahweh. The thunders shall cease, neither shall there be any more hail; that you may know that the earth is Yahweh''s.'),
  ('6af83309-4c13-56be-a0ec-2108a610c7ef', '57cebd86-52fa-597c-a13a-8f36d16c1bf1', NULL, 30, 30, 'But as for you and your servants, I know that you don''t yet fear Yahweh God."'),
  ('9dd070c3-89e6-5c98-aa29-63e8e5a7e4a2', '57cebd86-52fa-597c-a13a-8f36d16c1bf1', NULL, 31, 31, 'The flax and the barley were struck, for the barley was in the ear, and the flax was in bloom.'),
  ('a36ee19c-cfda-5476-a9bd-79c2bbe3108f', '57cebd86-52fa-597c-a13a-8f36d16c1bf1', NULL, 32, 32, 'But the wheat and the spelt were not struck, for they had not grown up.'),
  ('1cdc7874-4625-57d1-ab3f-f330297a5f3a', '57cebd86-52fa-597c-a13a-8f36d16c1bf1', NULL, 33, 33, 'Moses went out of the city from Pharaoh, and spread abroad his hands to Yahweh; and the thunders and hail ceased, and the rain was not poured on the earth.'),
  ('c84a7d5c-b8dd-5bab-a0fa-a79ae9603b02', '57cebd86-52fa-597c-a13a-8f36d16c1bf1', NULL, 34, 34, 'When Pharaoh saw that the rain and the hail and the thunders were ceased, he sinned yet more, and hardened his heart, he and his servants.'),
  ('440ba8c8-e9c6-5b51-a0f0-151ea1a8e5ec', '57cebd86-52fa-597c-a13a-8f36d16c1bf1', NULL, 35, 35, 'The heart of Pharaoh was hardened, and he didn''t let the children of Israel go, just as Yahweh had spoken through Moses.'),
  ('1365bf35-c853-5f15-aac6-7f75bb3bc4af', '39db611b-477e-5b63-a2f5-9007cef80be6', NULL, 1, 1, 'Yahweh said to Moses, "Go in to Pharaoh, for I have hardened his heart, and the heart of his servants, that I may show these my signs in the midst of them,'),
  ('c79f1d0c-0737-59a9-a32d-10874b00eee2', '39db611b-477e-5b63-a2f5-9007cef80be6', NULL, 2, 2, 'and that you may tell in the hearing of your son, and of your son''s son, what things I have done to Egypt, and my signs which I have done among them; that you may know that I am Yahweh."'),
  ('c9b7c353-2bdc-5c20-a324-d2242f647e07', '39db611b-477e-5b63-a2f5-9007cef80be6', NULL, 3, 3, 'Moses and Aaron went in to Pharaoh, and said to him, "This is what Yahweh, the God of the Hebrews, says: ''How long will you refuse to humble yourself before me? Let my people go, that they may serve me.'),
  ('3d340a88-4258-5e38-a1bf-28d78ce54bcd', '39db611b-477e-5b63-a2f5-9007cef80be6', NULL, 4, 4, 'Or else, if you refuse to let my people go, behold, tomorrow I will bring locusts into your country,'),
  ('75324789-c76b-5842-a4c8-48a2262525c7', '39db611b-477e-5b63-a2f5-9007cef80be6', NULL, 5, 5, 'and they shall cover the surface of the earth, so that one won''t be able to see the earth. They shall eat the residue of that which has escaped, which remains to you from the hail, and shall eat every tree which grows for you out of the field.'),
  ('8cf561a7-142e-59c3-a699-e6bceb726b19', '39db611b-477e-5b63-a2f5-9007cef80be6', NULL, 6, 6, 'Your houses shall be filled, and the houses of all your servants, and the houses of all the Egyptians; as neither your fathers nor your fathers'' fathers have seen, since the day that they were on the earth to this day.''" He turned, and went out from Pharaoh.'),
  ('a256aba4-daa5-5216-a1e9-007faef77055', '39db611b-477e-5b63-a2f5-9007cef80be6', NULL, 7, 7, 'Pharaoh''s servants said to him, "How long will this man be a snare to us? Let the men go, that they may serve Yahweh, their God. Don''t you yet know that Egypt is destroyed?"'),
  ('acfe5cb4-1bf5-5a93-a4f1-7e02bb31579b', '39db611b-477e-5b63-a2f5-9007cef80be6', NULL, 8, 8, 'Moses and Aaron were brought again to Pharaoh, and he said to them, "Go, serve Yahweh your God; but who are those who will go?"'),
  ('7072b0da-a566-5fc0-adb2-aff5653232f5', '39db611b-477e-5b63-a2f5-9007cef80be6', NULL, 9, 9, 'Moses said, "We will go with our young and with our old; with our sons and with our daughters, with our flocks and with our herds will we go; for we must hold a feast to Yahweh."'),
  ('96e1584d-09be-5e86-a049-e873e9c2c61a', '39db611b-477e-5b63-a2f5-9007cef80be6', NULL, 10, 10, 'He said to them, "Yahweh be with you if I will let you go with your little ones! See, evil is clearly before your faces.'),
  ('040f536e-9e69-5f40-a382-21dfea03d7a8', '39db611b-477e-5b63-a2f5-9007cef80be6', NULL, 11, 11, 'Not so! Go now you who are men, and serve Yahweh; for that is what you desire!" They were driven out from Pharaoh''s presence.'),
  ('8fc9e134-f48d-5807-a94c-fdbfce670ea8', '39db611b-477e-5b63-a2f5-9007cef80be6', NULL, 12, 12, 'Yahweh said to Moses, "Stretch out your hand over the land of Egypt for the locusts, that they may come up on the land of Egypt, and eat every herb of the land, even all that the hail has left."'),
  ('57ebed7f-61e5-5533-a9f3-c36f6420ee92', '39db611b-477e-5b63-a2f5-9007cef80be6', NULL, 13, 13, 'Moses stretched forth his rod over the land of Egypt, and Yahweh brought an east wind on the land all that day, and all the night; and when it was morning, the east wind brought the locusts.'),
  ('7771623b-d1fa-5ea3-a2bb-65ea6f98ad6a', '39db611b-477e-5b63-a2f5-9007cef80be6', NULL, 14, 14, 'The locusts went up over all the land of Egypt, and rested in all the borders of Egypt. They were very grievous. Before them there were no such locusts as they, neither after them shall be such.'),
  ('99dc1614-7a03-5e0a-aceb-923d7a5cd07b', '39db611b-477e-5b63-a2f5-9007cef80be6', NULL, 15, 15, 'For they covered the surface of the whole earth, so that the land was darkened, and they ate every herb of the land, and all the fruit of the trees which the hail had left. There remained nothing green, either tree or herb of the field, through all the land of Egypt.'),
  ('68a3b91a-7995-596b-a9b2-4df3ee0f7bd5', '39db611b-477e-5b63-a2f5-9007cef80be6', NULL, 16, 16, 'Then Pharaoh called for Moses and Aaron in haste, and he said, "I have sinned against Yahweh your God, and against you.'),
  ('73ab01af-4092-5810-a10a-890b8ade6841', '39db611b-477e-5b63-a2f5-9007cef80be6', NULL, 17, 17, 'Now therefore please forgive my sin again, and pray to Yahweh your God, that he may also take away from me this death."'),
  ('8bfe2ca2-62c9-518c-a162-6398284f36b6', '39db611b-477e-5b63-a2f5-9007cef80be6', NULL, 18, 18, 'He went out from Pharaoh, and prayed to Yahweh.'),
  ('3cbd6a2a-ce16-577d-a54b-62da7e3a6531', '39db611b-477e-5b63-a2f5-9007cef80be6', NULL, 19, 19, 'Yahweh turned an exceeding strong west wind, which took up the locusts, and drove them into the Red Sea. There remained not one locust in all the borders of Egypt.'),
  ('3306a01a-3e88-5d8e-af00-53ac2817798d', '39db611b-477e-5b63-a2f5-9007cef80be6', NULL, 20, 20, 'But Yahweh hardened Pharaoh''s heart, and he didn''t let the children of Israel go.'),
  ('bae0f088-662a-592d-a8a5-1bbecbe05ce0', '39db611b-477e-5b63-a2f5-9007cef80be6', NULL, 21, 21, 'Yahweh said to Moses, "Stretch out your hand toward the sky, that there may be darkness over the land of Egypt, even darkness which may be felt."'),
  ('7dc1fc16-b38e-5c54-aed6-ba2f25ecede4', '39db611b-477e-5b63-a2f5-9007cef80be6', NULL, 22, 22, 'Moses stretched forth his hand toward the sky, and there was a thick darkness in all the land of Egypt three days.'),
  ('e8cd0b6e-a56a-5003-af21-ad8c2ec4b6b3', '39db611b-477e-5b63-a2f5-9007cef80be6', NULL, 23, 23, 'They didn''t see one another, neither did anyone rise from his place for three days; but all the children of Israel had light in their dwellings.'),
  ('7e1fb8dd-cf85-5fb2-a622-5de9e5990e63', '39db611b-477e-5b63-a2f5-9007cef80be6', NULL, 24, 24, 'Pharaoh called to Moses, and said, "Go, serve Yahweh. Only let your flocks and your herds stay behind. Let your little ones also go with you."'),
  ('bc9b235a-dec4-592c-a605-8ca1d113c336', '39db611b-477e-5b63-a2f5-9007cef80be6', NULL, 25, 25, 'Moses said, "You must also give into our hand sacrifices and burnt offerings, that we may sacrifice to Yahweh our God.'),
  ('29bd21bc-3f6e-5cf3-a473-742a2edd8424', '39db611b-477e-5b63-a2f5-9007cef80be6', NULL, 26, 26, 'Our livestock also shall go with us. Not a hoof shall be left behind, for of it we must take to serve Yahweh our God; and we don''t know with what we must serve Yahweh, until we come there."'),
  ('f3e33233-5e82-5aec-ad8d-91a4d8c55410', '39db611b-477e-5b63-a2f5-9007cef80be6', NULL, 27, 27, 'But Yahweh hardened Pharaoh''s heart, and he wouldn''t let them go.'),
  ('ac332ec7-2006-5b03-a8b5-bbe83fb6b5b3', '39db611b-477e-5b63-a2f5-9007cef80be6', NULL, 28, 28, 'Pharaoh said to him, "Get away from me! Be careful to see my face no more; for in the day you see my face you shall die!"'),
  ('b79a4261-5837-5470-aae8-fd875842aea6', '39db611b-477e-5b63-a2f5-9007cef80be6', NULL, 29, 29, 'Moses said, "You have spoken well. I will see your face again no more."'),
  ('be136f15-0160-5480-a545-ae8999ed3ec4', 'b64572cf-76b4-5544-af9b-42a332f47c3f', NULL, 1, 1, 'Yahweh said to Moses, "Yet one plague more will I bring on Pharaoh, and on Egypt; afterwards he will let you go. When he lets you go, he will surely thrust you out altogether.'),
  ('afb57fc4-05e1-5f15-a300-64ed9d2da536', 'b64572cf-76b4-5544-af9b-42a332f47c3f', NULL, 2, 2, 'Speak now in the ears of the people, and let them ask every man of his neighbor, and every woman of her neighbor, jewels of silver, and jewels of gold."'),
  ('8a44ecc4-512b-5c78-a242-c2f98a3a6c1e', 'b64572cf-76b4-5544-af9b-42a332f47c3f', NULL, 3, 3, 'Yahweh gave the people favor in the sight of the Egyptians. Moreover the man Moses was very great in the land of Egypt, in the sight of Pharaoh''s servants, and in the sight of the people.'),
  ('58d43900-c639-53c3-add4-5bc535655cea', 'b64572cf-76b4-5544-af9b-42a332f47c3f', NULL, 4, 4, 'Moses said, "This is what Yahweh says: ''About midnight I will go out into the midst of Egypt,'),
  ('b812ca59-08fe-5acd-ac57-77945fe49b9d', 'b64572cf-76b4-5544-af9b-42a332f47c3f', NULL, 5, 5, 'and all the firstborn in the land of Egypt shall die, from the firstborn of Pharaoh who sits on his throne, even to the firstborn of the female servant who is behind the mill; and all the firstborn of livestock.'),
  ('99c86170-9551-56c6-a08c-892d2c681f77', 'b64572cf-76b4-5544-af9b-42a332f47c3f', NULL, 6, 6, 'There shall be a great cry throughout all the land of Egypt, such as there has not been, nor shall be any more.'),
  ('d30b33ec-ecc6-59f4-ae98-aa335750f636', 'b64572cf-76b4-5544-af9b-42a332f47c3f', NULL, 7, 7, 'But against any of the children of Israel a dog won''t even bark or move its tongue, against man or animal; that you may know that Yahweh makes a distinction between the Egyptians and Israel.'),
  ('4d573b05-9912-50f1-ae95-c383f655a6d0', 'b64572cf-76b4-5544-af9b-42a332f47c3f', NULL, 8, 8, 'All these your servants shall come down to me, and bow down themselves to me, saying, "Get out, with all the people who follow you;" and after that I will go out.''" He went out from Pharaoh in hot anger.'),
  ('be41e2a9-9319-5455-a26e-ba55b09ab25c', 'b64572cf-76b4-5544-af9b-42a332f47c3f', NULL, 9, 9, 'Yahweh said to Moses, "Pharaoh won''t listen to you, that my wonders may be multiplied in the land of Egypt."'),
  ('a430b7ec-26cb-511d-aa50-8241f63e0d3a', 'b64572cf-76b4-5544-af9b-42a332f47c3f', NULL, 10, 10, 'Moses and Aaron did all these wonders before Pharaoh, and Yahweh hardened Pharaoh''s heart, and he didn''t let the children of Israel go out of his land.'),
  ('94020806-34ed-56ae-a789-eec4b05f3dfe', '507fc779-01aa-5459-a39d-ffc6b8f9cff1', NULL, 1, 1, 'Yahweh spoke to Moses and Aaron in the land of Egypt, saying,'),
  ('5d1d991a-d652-54b5-a5c7-c9ec65a1cc61', '507fc779-01aa-5459-a39d-ffc6b8f9cff1', NULL, 2, 2, '"This month shall be to you the beginning of months. It shall be the first month of the year to you.'),
  ('0702407e-1405-5cbc-a4d8-f3a3f1eeebd4', '507fc779-01aa-5459-a39d-ffc6b8f9cff1', NULL, 3, 3, 'Speak to all the congregation of Israel, saying, ''On the tenth day of this month, they shall take to them every man a lamb, according to their fathers'' houses, a lamb for a household;'),
  ('6733f3bb-4fd9-5c17-a15a-edb95110e3f1', '507fc779-01aa-5459-a39d-ffc6b8f9cff1', NULL, 4, 4, 'and if the household is too little for a lamb, then he and his neighbor next to his house shall take one according to the number of the souls; according to what everyone can eat you shall make your count for the lamb.'),
  ('3dc0db86-cefc-51ae-af1b-21c8658bc4e9', '507fc779-01aa-5459-a39d-ffc6b8f9cff1', NULL, 5, 5, 'Your lamb shall be without blemish, a male a year old. You shall take it from the sheep, or from the goats:'),
  ('a35180f3-2614-5d8e-a614-1e7e779e5864', '507fc779-01aa-5459-a39d-ffc6b8f9cff1', NULL, 6, 6, 'and you shall keep it until the fourteenth day of the same month; and the whole assembly of the congregation of Israel shall kill it at evening.'),
  ('5386f726-7cad-5b6c-a3bd-22b038b6a93d', '507fc779-01aa-5459-a39d-ffc6b8f9cff1', NULL, 7, 7, 'They shall take some of the blood, and put it on the two doorposts and on the lintel, on the houses in which they shall eat it.'),
  ('fcecc3a9-272d-52fb-afa7-3548dd3486e7', '507fc779-01aa-5459-a39d-ffc6b8f9cff1', NULL, 8, 8, 'They shall eat the flesh in that night, roasted with fire, and unleavened bread. They shall eat it with bitter herbs.'),
  ('2b0db16b-3c75-5d8d-af76-49777b687870', '507fc779-01aa-5459-a39d-ffc6b8f9cff1', NULL, 9, 9, 'Don''t eat it raw, nor boiled at all with water, but roasted with fire; with its head, its legs and its inner parts.'),
  ('79be6430-3c62-5562-a65d-abfe0a4ad2ab', '507fc779-01aa-5459-a39d-ffc6b8f9cff1', NULL, 10, 10, 'You shall let nothing of it remain until the morning; but that which remains of it until the morning you shall burn with fire.'),
  ('1e96c669-5c79-54d1-aee8-f3dd8b8d56cb', '507fc779-01aa-5459-a39d-ffc6b8f9cff1', NULL, 11, 11, 'This is how you shall eat it: with your belt on your waist, your shoes on your feet, and your staff in your hand; and you shall eat it in haste: it is Yahweh''s Passover.'),
  ('466b4b89-ef73-5623-a6be-a06a796230a4', '507fc779-01aa-5459-a39d-ffc6b8f9cff1', NULL, 12, 12, 'For I will go through the land of Egypt in that night, and will strike all the firstborn in the land of Egypt, both man and animal. Against all the gods of Egypt I will execute judgments: I am Yahweh.'),
  ('2868bd09-6d11-51f5-af3a-889999fe8aa3', '507fc779-01aa-5459-a39d-ffc6b8f9cff1', NULL, 13, 13, 'The blood shall be to you for a token on the houses where you are: and when I see the blood, I will pass over you, and there shall no plague be on you to destroy you, when I strike the land of Egypt.'),
  ('fce800f2-9ecc-586a-a195-c2502d0b834b', '507fc779-01aa-5459-a39d-ffc6b8f9cff1', NULL, 14, 14, 'This day shall be to you for a memorial, and you shall keep it a feast to Yahweh: throughout your generations you shall keep it a feast by an ordinance forever.'),
  ('49e1ce24-e24e-5c62-a5a6-3bfbc1c70e75', '507fc779-01aa-5459-a39d-ffc6b8f9cff1', NULL, 15, 15, '"''Seven days you shall eat unleavened bread; even the first day you shall put away yeast out of your houses, for whoever eats leavened bread from the first day until the seventh day, that soul shall be cut off from Israel.'),
  ('10bbc4f6-2cae-591d-a5a6-333ed3f73a16', '507fc779-01aa-5459-a39d-ffc6b8f9cff1', NULL, 16, 16, 'In the first day there shall be to you a holy convocation, and in the seventh day a holy convocation; no kind of work shall be done in them, except that which every man must eat, that only may be done by you.'),
  ('778504e8-98ab-54dd-ab14-d64510fc9d9b', '507fc779-01aa-5459-a39d-ffc6b8f9cff1', NULL, 17, 17, 'You shall observe the feast of unleavened bread; for in this same day have I brought your armies out of the land of Egypt: therefore you shall observe this day throughout your generations by an ordinance forever.'),
  ('a914b7db-da84-587f-a1a0-a19fdca0f4c0', '507fc779-01aa-5459-a39d-ffc6b8f9cff1', NULL, 18, 18, 'In the first month, on the fourteenth day of the month at evening, you shall eat unleavened bread, until the twenty first day of the month at evening.'),
  ('2549becd-f422-51d3-a9d4-f5c1aeb75a07', '507fc779-01aa-5459-a39d-ffc6b8f9cff1', NULL, 19, 19, 'Seven days shall there be no yeast found in your houses, for whoever eats that which is leavened, that soul shall be cut off from the congregation of Israel, whether he be a foreigner, or one who is born in the land.'),
  ('ed046146-ffc4-52b8-a1b9-f3d8e65fd37d', '507fc779-01aa-5459-a39d-ffc6b8f9cff1', NULL, 20, 20, 'You shall eat nothing leavened. In all your habitations you shall eat unleavened bread.''"'),
  ('ff449f55-ad32-56ba-a652-1d0649ba7b4b', '507fc779-01aa-5459-a39d-ffc6b8f9cff1', NULL, 21, 21, 'Then Moses called for all the elders of Israel, and said to them, "Draw out, and take lambs according to your families, and kill the Passover.'),
  ('0d4a59ae-44bd-545f-ab9c-5f3a02367666', '507fc779-01aa-5459-a39d-ffc6b8f9cff1', NULL, 22, 22, 'You shall take a bunch of hyssop, and dip it in the blood that is in the basin, and strike the lintel and the two doorposts with the blood that is in the basin; and none of you shall go out of the door of his house until the morning.'),
  ('b418dec4-6a46-5338-a5ea-83d2e8734d39', '507fc779-01aa-5459-a39d-ffc6b8f9cff1', NULL, 23, 23, 'For Yahweh will pass through to strike the Egyptians; and when he sees the blood on the lintel, and on the two doorposts, Yahweh will pass over the door, and will not allow the destroyer to come in to your houses to strike you.'),
  ('e1e8bbe5-e9ce-59ea-ac55-c052bd6e5a12', '507fc779-01aa-5459-a39d-ffc6b8f9cff1', NULL, 24, 24, 'You shall observe this thing for an ordinance to you and to your sons forever.'),
  ('d721b967-8dcb-5c9d-ac39-9375dfc9188d', '507fc779-01aa-5459-a39d-ffc6b8f9cff1', NULL, 25, 25, 'It shall happen when you have come to the land which Yahweh will give you, according as he has promised, that you shall keep this service.'),
  ('58ea4825-a0eb-5ac8-a86c-650b39bb016b', '507fc779-01aa-5459-a39d-ffc6b8f9cff1', NULL, 26, 26, 'It will happen, when your children ask you, ''What do you mean by this service?'''),
  ('d61216da-a566-5d5b-ad8f-adcde776d77c', '507fc779-01aa-5459-a39d-ffc6b8f9cff1', NULL, 27, 27, 'that you shall say, ''It is the sacrifice of Yahweh''s Passover, who passed over the houses of the children of Israel in Egypt, when he struck the Egyptians, and spared our houses.''" The people bowed their heads and worshiped.'),
  ('4ccf5ad4-0d40-515d-a7c9-87e076b15c90', '507fc779-01aa-5459-a39d-ffc6b8f9cff1', NULL, 28, 28, 'The children of Israel went and did so; as Yahweh had commanded Moses and Aaron, so they did.'),
  ('a6ee0d31-b0b9-54f5-a80b-dbdd31f411f5', '507fc779-01aa-5459-a39d-ffc6b8f9cff1', NULL, 29, 29, 'It happened at midnight, that Yahweh struck all the firstborn in the land of Egypt, from the firstborn of Pharaoh who sat on his throne to the firstborn of the captive who was in the dungeon; and all the firstborn of livestock.'),
  ('6b96ce0d-288c-50fe-a0b5-fee8c25f3858', '507fc779-01aa-5459-a39d-ffc6b8f9cff1', NULL, 30, 30, 'Pharaoh rose up in the night, he, and all his servants, and all the Egyptians; and there was a great cry in Egypt, for there was not a house where there was not one dead.'),
  ('911ab2d6-4d3e-5ac2-a826-1cf22f430b20', '507fc779-01aa-5459-a39d-ffc6b8f9cff1', NULL, 31, 31, 'He called for Moses and Aaron by night, and said, "Rise up, get out from among my people, both you and the children of Israel; and go, serve Yahweh, as you have said!'),
  ('a7fe3931-d2b6-530b-a33a-beb0da1bad7e', '507fc779-01aa-5459-a39d-ffc6b8f9cff1', NULL, 32, 32, 'Take both your flocks and your herds, as you have said, and be gone; and bless me also!"'),
  ('2197e623-6232-5e52-a894-43f56136f2fb', '507fc779-01aa-5459-a39d-ffc6b8f9cff1', NULL, 33, 33, 'The Egyptians were urgent with the people, to send them out of the land in haste, for they said, "We are all dead men."'),
  ('0e936b2e-17fe-5af3-a3fd-c9c0bde8f9e4', '507fc779-01aa-5459-a39d-ffc6b8f9cff1', NULL, 34, 34, 'The people took their dough before it was leavened, their kneading troughs being bound up in their clothes on their shoulders.'),
  ('55e08956-be41-51c9-a885-5bc6cfd95546', '507fc779-01aa-5459-a39d-ffc6b8f9cff1', NULL, 35, 35, 'The children of Israel did according to the word of Moses; and they asked of the Egyptians jewels of silver, and jewels of gold, and clothing.'),
  ('812f3f20-2a7f-5674-a307-92d944125ffe', '507fc779-01aa-5459-a39d-ffc6b8f9cff1', NULL, 36, 36, 'Yahweh gave the people favor in the sight of the Egyptians, so that they let them have what they asked. They despoiled the Egyptians.'),
  ('71a3425a-a08d-51a1-af4f-cb416e1b6327', '507fc779-01aa-5459-a39d-ffc6b8f9cff1', NULL, 37, 37, 'The children of Israel traveled from Rameses to Succoth, about six hundred thousand on foot who were men, besides children.'),
  ('d98cfaba-e1bf-5a45-adc6-257b6f119c30', '507fc779-01aa-5459-a39d-ffc6b8f9cff1', NULL, 38, 38, 'A mixed multitude went up also with them, with flocks, herds, and even very much livestock.'),
  ('d65ec36e-aca0-5333-ae81-b0e99f83a42c', '507fc779-01aa-5459-a39d-ffc6b8f9cff1', NULL, 39, 39, 'They baked unleavened cakes of the dough which they brought forth out of Egypt; for it wasn''t leavened, because they were thrust out of Egypt, and couldn''t wait, neither had they prepared for themselves any food.'),
  ('ea9bf47d-2a26-5ac4-a204-77f9a8ec9ba3', '507fc779-01aa-5459-a39d-ffc6b8f9cff1', NULL, 40, 40, 'Now the time that the children of Israel lived in Egypt was four hundred thirty years.'),
  ('9d9eb66f-9f31-53a3-ab87-801fec314f78', '507fc779-01aa-5459-a39d-ffc6b8f9cff1', NULL, 41, 41, 'It happened at the end of four hundred thirty years, even the same day it happened, that all the armies of Yahweh went out from the land of Egypt.'),
  ('1483896b-a1ce-5eb1-a70f-fa3486b501df', '507fc779-01aa-5459-a39d-ffc6b8f9cff1', NULL, 42, 42, 'It is a night to be much observed to Yahweh for bringing them out from the land of Egypt. This is that night of Yahweh, to be much observed of all the children of Israel throughout their generations.'),
  ('5f92da0e-2e6a-5cdf-ad55-3f466419d558', '507fc779-01aa-5459-a39d-ffc6b8f9cff1', NULL, 43, 43, 'Yahweh said to Moses and Aaron, "This is the ordinance of the Passover. No foreigner shall eat of it,'),
  ('4cf57561-aedf-51cb-a51a-7c902caeff3f', '507fc779-01aa-5459-a39d-ffc6b8f9cff1', NULL, 44, 44, 'but every man''s servant who is bought for money, when you have circumcised him, then shall he eat of it.')
